    ["Accept Rig Wars before Chief Engineer Scooty. If Rig Wars disappears, abandon Chief Engineer Scooty and it will reappear."] = "'선임기술자 스쿠티'보다 먼저 '기술 전쟁'을 수락하세요. '기술 전쟁'이 사라지면 '선임기술자 스쿠티'를 포기하여 다시 표시할 수 있습니다.",
    ["Accept Rig Wars first; completion is not required for Chief Engineer Scooty."] = "먼저 기술 전쟁을 수락합니다. 선임기술자 스쿠티에는 완료가 필요하지 않습니다.",
    ["Accept Rig Wars from Nogg. You do not need to complete it before continuing to Chief Engineer Scooty."] = "노그에게서 '기술 전쟁'을 수락하세요. 완료하지 않아도 '선임기술자 스쿠티' 퀘스트를 진행할 수 있습니다.",
    ["Accept Rig Wars here"] = "여기에서 기술 전쟁을 수락하세요.",
    ["Accompany Lumina Windsinger and help her escape Fenris Keep."] = "루미나 윈드싱어와 동행하여 펜리스 성채에서 탈출하도록 도와주세요.",
    ["Acidic Walkers"] = "방사능처리 장화",
    ["Acidproof Cloak"] = "산성 면역 망토",
    ["Acquire 4 Healthy Courser Glands and bring them to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath."] = "건강한 준마샘 4개를 획득하고 아즈샤라에 있는 오그틴크에게 가져가세요. 오그틴크는 엘다라스 폐허 북동쪽 절벽 꼭대기에 거주합니다.",
    ["Acquire an Ichor of Undeath for Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath."] = "아즈샤라에서 오그틴크용 불사의 영액을 획득합니다. 오그틴크는 엘다라스 폐허 북동쪽 절벽 꼭대기에 거주합니다.",
    ["Acquire special horse feed used for feeding a spirit horse. Merideth Carlson in Southshore apparently is the source for such food. Travel to the Dire Maul dungeon in Feralas and slay Tendris Warpwood. Doing so will free the Ancient Equine Spirit. Feed it the special horse feed, thereby soothing the spirit. Finally, give it the Arcanite Barding so it may bless it."] = "정령 말에게 먹이를 주는 데 사용되는 특별한 말 사료를 획득하세요. 사우스쇼어의 메리데스 칼슨는 분명히 그러한 음식의 원천입니다. 페랄라스를 타고 혈투의 전장 던전으로 이동하여 굽이나무 텐드리스를 처치하세요. 그렇게 하면 고대 준마의 영혼가 해제됩니다. 특별한 말 사료를 먹이면 정신이 안정됩니다. 마지막으로 아케이나이트 마갑을 주어 축복을 받을 수 있도록 하세요.",
    ["Acquire the Grimy Key for Magus Wordeen Voidglare in Tarren Mill."] = "타렌 밀농장에서 학자 워딘 보이드글레어에 대한 때 묻은 열쇠를 획득합니다.",
    ["Acquire the Mana Sieve from within the temple in Shen'dralas and use it to collect Ancient Mana Crystals, then empower the pylons and return to Mordent Evenshade."] = "셴드랄라스의 사원 내에서 마나 체를 획득하고 이를 사용하여 고대 마나 수정을 수집한 다음 철탑에 권한을 부여하고 모르덴트 이븐셰이드로 돌아갑니다.",
    ["Acquire the reagents Ghak Healtouch needs from the Badlands, then return to him in Thelsamar."] = "황야의 땅에게서 가크 힐터치에 필요한 시약을 획득한 후 텔사마에 있는 그에게 돌아가세요.",
