    ["After Baron Rivendare dies, use the glowing rune on the floor of his room, then take the follow-up back to Leonid."] = "남작 리븐데어가 죽은 후 그의 방 바닥에 빛나는 룬을 사용한 다음 리어니드에게 후속 조치를 취하십시오.",
    ["After the pyramid event, speak to Weegli Blastfuse to open the gate, then confront Bly about the Divino-matic Rod to fight him and his companions. Drops the rod for the Divino-matic Rod quest."] = "피라미드 이벤트가 끝난 후 위글리 블라스트퓨즈에게 말을 걸어 문을 연 다음 자동 탐사막대에 대해 블라이와 대결하여 그와 그의 동료들과 싸우세요. 자동 탐사막대 퀘스트를 위해 막대를 떨어뜨립니다.",
    ["Afterwards Ekkal takes more pouches as a repeatable quest (Timbermaw Hold +100)."] = "이후 에칼는 반복 가능한 퀘스트로 더 많은 주머니를 가져옵니다(나무구렁 요새 +100).",
