    ["Alterac Mountains"] = "알터랙 산맥",
    ["Altered Beings"] = "변화된 생물",
    ["Ambassador Malcin is in the tents of the outdoor thorn maze, before the instance portal. Starts from the Small Scroll dropped by Charlga Razorflank in Razorfen Kraul."] = "사절 말킨는 인스턴스 포털 앞 야외 가시 미로의 텐트에 있습니다. 가시덩굴 우리에서 서슬깃 차를가가 드롭한 작은 두루마리부터 시작합니다.",
