    ["An Ambassador of Evil"] = "악의 사자",
    ["An Ancient Grudge"] = "해묵은 원한",
    ["An Imp's Request"] = "임프의 부탁",
    ["An Underrated Talent"] = "숨겨진 재능",
    ["An Unholy Alliance"] = "사악한 동맹",
    ["An Unsent Letter"] = "부치지 않은 편지",
    ["An ancient titan facility in the northern hills of Un'Goro Crater, overlooking dinosaurs, tar pits and powerful crystals. Collect power crystals across Un'Goro and use them at the consoles inside the terrace."] = "운고로 분화구 북쪽 언덕에 있는 고대 타이탄 시설로 공룡, 타르 구덩이, 강력한 수정이 내려다보입니다. 운고로 전역에서 마력 수정을 모아 테라스 내부 콘솔에서 사용하세요.",
    ["An ancient titan vault buried beneath the Badlands, overrun by troggs and Shadowforge dwarves. Archaedas guards the Discs of Norgannon in its deepest chamber."] = "황야의 땅 아래에 묻혀 있는 고대 타이탄 금고에는 트로그와 어둠괴철로 드워프가 들끓고 있습니다. 아카에다스는 노르간논의 원반의 가장 깊은 방을 지키고 있습니다.",
    ["An arcane golem by the Magus Commerce Exchange, with Angry Tomes. Malfunction hits everyone within 25 yards."] = "분노한 고서와 함께 마법사 교역소가 제작한 신비한 골렘입니다. 오작동으로 인해 25야드 내의 모든 사람이 피해를 입습니다.",
    ["An irradiated ooze in the Hall of Gears."] = "기어 홀에 있는 방사능 수액입니다.",
    ["An'Alleum Power Stone"] = "안알레움 마법석",
