    ["Beyond Earth Song Falls, find the chamber of brilliant white crystals guarded by giants. Retrieve An'she's Radiance from the crystal near the highest part of the chamber. Rewards 300 Earthen Ring and 200 Thunder Bluff reputation."] = "대지노래 폭포 너머에서 거인들이 지키고 있는 찬란한 흰색 수정의 방을 찾으세요. 방의 가장 높은 부분 근처에 있는 수정에서 안쉬의 광채를 회수하세요. 300 대지 고리회 및 200 썬더 블러프 평판을 보상합니다.",
    ["Beyond a long-sealed gate in Azshara lies the furbolg city of the Blackmaw clan, fighting a corruption that spreads through its groves and mountain tunnels. A large max-level dungeon with several routes and bosses; its depths may lead even farther below Azeroth."] = "아즈샤라의 오랫동안 봉인된 관문 너머에는 숲과 산 터널을 통해 퍼지는 부패에 맞서 싸우고 있는 검은아귀 부족의 펄볼그 도시가 있습니다. 여러 경로와 보스가 있는 대규모 최대 레벨 던전. 그 깊이는 아제로스 아래로 훨씬 더 깊어질 수도 있습니다.",
