    ["Blacksmithing"] = "대장기술",
    ["Blacksmithing 270 (Armorsmith). Use the Blood Stained Pike on Goraluk's corpse and loot the Unforged Rune Covered Breastplate nearby."] = "대장기술 270 (방어구제작). 고랄루크의 시체에 핏물이 깃든 창을 사용하고 근처에 있는 벼려지지 않은 룬문자 흉갑을 약탈하세요.",
    ["Blacksmithing. Bring a Sulfuron Ingot (Golemagg, Molten Core) to Lokhtos in the Grim Guzzler to get the contract, then hand it back for the Sulfuron Hammer plans."] = "대장기술. 험상궂은 주정뱅이 선술집에 있는 로크토스에게 설퍼론 주괴(골레마그, 화산 심장부)를 가져와 계약을 받은 다음 설퍼론 망치 계획을 위해 다시 건네주세요.",
