    ["Breaching Charge"] = "돌파용 폭탄",
    ["Break Their Chains"] = "속박을 끊어라",
    ["Break the three kegs in the Grim Guzzler storeroom to spawn Hurley Blackbreath and his guards.\n\nOptional introductory quest:"] = "험상궂은 주정뱅이 선술집 창고에 있는 세 개의 술통을 부수고 헐레이 블랙브레스와 그의 경비병을 소환하세요.\n\n선택적인 소개 퀘스트:",
    ["Break their Chains"] = "속박을 끊어라",
    ["Break their Chains and Rise Up"] = "속박을 끊고 일어서라",
    ["Breastplate of Valor"] = "용맹의 흉갑",
    ["Briarwood Reed"] = "가시나무 줄기",
    ["Bridgebreaker Bindings"] = "다리파괴자 손목띠",
    ["Brigam Girdle"] = "약탈의 벨트",
    ["Brightly Glowing Stone"] = "밝게 빛나는 돌",
    ["Brightspark Gloves"] = "섬광의 장갑",
    ["Brill"] = "브릴",
    ["Brill by"] = "브릴 인근",
    ["Brinebelly Leggings"] = "소금배 다리보호구",
    ["Brinescale Skirmishers on the sea floor west of Grom'gol (around 22, 26)"] = "그롬골 서쪽 해저의 염수비늘 척후병(약 22, 26)",
    ["Brinescale Skirmishers — around the Vile Reef"] = "염수비늘 척후병 — 부패한 산호초 주변",
    ["Brinescale Trident"] = "소금비늘 삼지창",
    ["Bring 1 Jeering Spectre's Essence, 4 Dark Runes and 8 Large Brilliant Shards to Falrin Treeshaper inside Dire Maul."] = "혈투의 전장에 있는 팔린 트리셰이퍼에 엘드레스 영혼의 정수 1개, 암흑 룬 4개, 크고 빛나는 파편 8개를 가져가세요.",
    ["Bring 1 pile of Kraul Guano from the Kraul bats to Master Apothecary Faranell."] = "크라울 박쥐에게서 가시덩굴 조분석 더미 1개를 수석 연금술사 파라넬로 가져옵니다.",
    ["Bring 1 pile of Kraul Guano to Master Apothecary Faranell in the Undercity."] = "언더시티에 있는 수석 연금술사 파라넬에 가시덩굴 조분석 더미 1개를 가져오세요.",
    ["Bring 10 Elixirs of Shadow Power to Gorzeeki Wildeyes in the Burning Steppes."] = "불타는 평원에 있는 고르지키 와일드아이즈에게 어둠의 힘의 비약 10개를 가져가야 합니다.",
    ["Bring 10 Encoded Fragments to Archmage Xylem in Azshara."] = "10 암호화된 페이지를 아즈샤라의 대마법사 실렘에 가져옵니다.",
    ["Bring 10 Glittering Dust to Archmage Xylem."] = "반짝이는 가루 10개를 대마법사 실렘에 가져옵니다.",
    ["Bring 10 Rotting Wood and 4 Bloodvenom Essence to Impsy in Felwood."] = "악령의 숲에 있는 임프시에게 썩은 나무 10개와 피멍울 정수 4개를 가져옵니다.",
    ["Bring 12 Essential Artificials to Klockmort Spannerspan in Ironforge."] = "12개의 필수 인공장치를 아이언포지의 클락몰트 스패너스판에 가져옵니다.",
    ["Bring 12 Magenta Fungus Caps to Ghak Healtouch in Thelsamar."] = "텔사마에 있는 가크 힐터치에게 자홍색 곰팡이 모자 12개를 가져가세요.",
    ["Bring 12 Magenta Fungus Caps to Jarkal Mossmeld in Kargath."] = "카르가스에 있는 자칼 모스멜드에게 자홍색 곰팡이 모자 12개를 가져가세요.",
    ["Bring 15 Red Leather Bandanas to Scout Galiaan at Sentinel Hill."] = "감시의 언덕에 있는 정찰병 갈리안에게 붉은 가죽 복면 15개를 가져가세요.",
    ["Bring 20 Deviate Hides to Nalpak."] = "돌연변이 통가죽 20개를 날팍에게 가져가세요.",
    ["Bring 20 Hearts of Zeal from the Scarlet Monastery to Master Apothecary Faranell."] = "붉은십자군 수도원에서 열정의 증거 20개를 수석 연금술사 파라넬로 가져가세요.",
    ["Bring 20 Vials of Troll Temper to Trenton Lighthammer in Gadgetzan."] = "트롤 경화제의 약병 20개를 가젯잔의 트렌튼 라이트해머에 가져가세요.",
    ["Bring 3 Arcanite Bars to Gorzeeki in the Burning Steppes."] = "불타는 평원에 있는 고르지키에게 아케이나이트 주괴 3개를 가져가야 합니다.",
    ["Bring 30 bottles of Raging Beast's Blood to Mor'zul Bloodbringer in the Burning Steppes."] = "불타는 평원에 있는 모르줄 블러드브링어에게 흉포한 올빼미야수의 피 30병을 가져가세요.",
    ["Bring 35 Black Dragonscales to Gorzeeki Wildeyes in the Burning Steppes."] = "불타는 평원에 있는 고르지키 와일드아이즈에게 검은용 비늘 35개를 가져가야 합니다.",
    ["Bring 4 Bolts of Runecloth, 8 Rugged Leather, 2 Rune Threads and 1 Ogre Tannin (basket on the upper level beyond Knot). Make any suits and learn the pattern before freeing Knot, because he leaves."] = "룬무늬 볼트 4개, 튼튼한 가죽 8개, 룬 실 2개, 오우거 타닌 1개(매듭 너머 상단에 있는 바구니)를 가져옵니다. 노트를 풀어주기 전에 슈트를 만들고 패턴을 배우세요. 노트이 떠나니까요.",
    ["Bring 4 Bolts of Runecloth, 8 Rugged Leather, 2 Rune Threads, and Ogre Tannin to Knot Thimblejack. He is currently chained inside the Gordok wing of Dire Maul."] = "룬무늬 볼트 4개, 튼튼한 가죽 8개, 룬 실타래 2개, 오우거 타닌을 노트 팀블잭에게 가져가세요. 그는 현재 혈투의 전장의 고르독 구역 안에 묶여 있습니다.",
    ["Bring 4 Carved Stone Urns to Prospector Ironband in Loch Modan."] = "모단 호수에 있는 발굴조사단장 아이언밴드에게 조각된 돌 항아리 4개를 가져가세요.",
    ["Bring 4 Gromsblood, 10 Giant Silver Veins and Nagmara's Filled Vial to Mistress Nagmara in Blackrock Depths."] = "검은바위 나락에 있는 지배인 나그마라에 그롬스블러드 4개, 거대 은맥 10개, 가득 찬 나그마라의 약병을 가져가세요.",
    ["Bring 4 Skullsplitter Fetishes to Brother Nimetz."] = "수사 니메츠에 해골분쇄기 우상 4개를 가져가세요.",
    ["Bring 4 Thick Leather and 12 Iron Bars to Alphonse Dumas."] = "두꺼운 가죽 4개와 철괴 12개를 알퐁스 뒤마에 가져오세요.",
    ["Bring 4 Thick Leather and 12 Iron Bars to Kreza Darkthorn."] = "두꺼운 가죽 4개와 철괴 12개를 크레자 다크쏜에 가져오세요.",
    ["Bring 40 Runecloth, 6 Arcanite Bars, 10 Arthas' Tears, 5 Stratholme Holy Water vials, and 150 gold to Grimand Elmore in the Dwarven District of Stormwind."] = "스톰윈드의 드워프 지구에 있는 그리만트 엘모어에게 룬무늬 40개, 아케이나이트 주괴 6개, 아서스의 눈물 10개, 스트라솔름 성수 약병 5개, 골드 150개를 가져가세요.",
    ["Bring 5 Buzzard Gizzards, 10 Crag Coyote Fangs, and 5 Rock Elemental Shards to Jarkal Mossmeld in Kargath, Badlands."] = "카르가스에 있는 자칼 모스멜드, 황야의 땅에게 독수리 모래주머니 5개, 바위산코요테 송곳니 10개, 바위 정령 파편 5개를 가져가세요.",
    ["Bring 5 Uncracked Scarab Shells to Tran'rek in Gadgetzan."] = "가젯잔에 있는 트란렉에게 깨지지 않은 왕쇠똥구리 껍질 5개를 가져가세요.",
    ["Bring 6 Large Brilliant Shards and 25 Dark Iron Ore to Gorzeeki in the Burning Steppes."] = "불타는 평원에 있는 고르지키에게 눈부신 대형 파편 6개와 검은무쇠 광석 25개를 가져가세요.",
    ["Bring 6 Wailing Essence to Mebok Mizzyrix."] = "통곡의 정수 6개를 메보크 미지릭스에 가져옵니다.",
    ["Bring 6 Wavethrasher Scales to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath."] = "아즈샤라에 있는 오그틴크에게 폭풍히드라 비늘 6개를 가져옵니다. 오그틴크는 엘다라스 폐허 북동쪽 절벽 꼭대기에 거주합니다.",
    ["Bring 6 samples of Lake Creeper Moss, 6 samples of Lake Skulker Moss and a Hardened Tumor to Master Apothecary Faranell in the Undercity."] = "언더시티에 있는 호수늪지이끼 샘플 6개, 호수덤불이끼 샘플 6개, 굳어진 종양을 수석 연금술사 파라넬에 가져옵니다.",
    ["Bring 7 Jungle Remedies and 1 Venom Fern Extract to Sergeant Yohwa."] = "하사관 요화에 정글 치료제 7개와 독고사리 즙 1개를 가져오세요.",
    ["Bring 8 Altered Snapjaw Shells to Tonga Runetotem at the Crossroads."] = "교차로에 있는 통가 룬토템에게 변경된 스냅조 껍질 8개를 가져가세요.",
    ["Bring 8 Broodling Essence and the Draco-Incarcinatrix 900 to Tinkee Steamboil at the Flame Crest in the Burning Steppes."] = "불타는 평원의 불꽃 마루에 있는 새끼용의 정수 8개와 새끼용 속박장치 900를 팅키 스팀보일에게 가져가세요.",
    ["Bring 8 Collected Dragon Eggs and the Collectronic Module to Tinkee Steamboil at Flame Crest in the Burning Steppes."] = "불타는 평원의 화염 문장에 있는 팅키 스팀보일에게 수집한 드래곤 알 8개와 수집전자 모듈을 가져가세요.",
    ["Bring 8 Dentrium Power Stones and 8 An'Alleum Power Stones to Rigglefuzz in the Badlands."] = "황야의 땅에 있는 리글퍼즈에게 덴트리움 마법석 8개와 안알레움 마법석 8개를 가져가세요.",
    ["Bring 8 Uncracked Chillwind Horns to Felnok Steelspring."] = "깨지지 않은 서리바람 키메라의 뿔 8개를 펠노크 스틸스프링에 가져가세요.",
    ["Bring Ambassador Malcin's Head to Varimathras in the Undercity."] = "언더시티를 타고 바리마트라스에게 사절 말킨의 머리카락을 가져가세요.",
    ["Bring Doomrigger's Clasp to Mayara Brightwing in the Burning Steppes."] = "불타는 평원에 있는 파멸의 기념물을 마야라 브라이트윙에게 가져가세요.",
    ["Bring Fel-Tainted Flesh."] = "지옥 마력으로 오염된 살점을 가져옵니다.",
    ["Bring Felnok's Package to Tinkee Steamboil in the Burning Steppes."] = "불타는 평원에 있는 펠노크의 소포를 팅키 스팀보일에게 가져가세요.",
    ["Bring Fragments of Rok'Alim to Dorn Plainstalker in Thousand Needles."] = "로크알림의 파편을 버섯구름 봉우리의 도른 플레인스토커로 가져옵니다.",
    ["Bring Gahz'rilla's Electrified Scale to Wizzle Brassbolts in the Shimmering Flats."] = "소금 평원에 있는 가즈릴라의 전기 비늘을 위즐 브라스볼츠에게 가져가세요.",
    ["Bring Gloom'rel 2 Star Rubies, 20 Gold Bars and 10 Truesilver Bars, then place them in the Spectral Chalice in the Summoners' Tomb."] = "그늘의 문지기 2성 루비, 금괴 20개, 진은괴 10개를 가져와 소환사의 무덤에 있는 유령의 성배에 넣으세요.",
    ["Bring Grenka's Claw to Dorn Plainstalker in Thousand Needles."] = "그렌카의 발톱을 버섯구름 봉우리의 도른 플레인스토커로 가져옵니다.",
    ["Bring High Potency Radioactive Fallout and the Heavy Leaden Collection Phial back to Ozzie. The fallout collapses quickly."] = "고농축 방사성 폐기물과 빈 대형 가연채집병을 오지에게 다시 가져오세요. 낙진은 빠르게 무너집니다.",
    ["Bring Highlord Omokk's Head and a Roughshod Pike to Urok's Tribute Pile beyond the spiders to start the waves."] = "거미 너머의 우로크 공물 더미에 대군주 오모크의 머리와 날카로운 장창을 가져와 파도를 시작하세요.",
    ["Bring Lethtendris' Web to Latronicus Moonspear at the Feathermoon Stronghold in Feralas."] = "페랄라스의 페더문 요새에 있는 라트로니쿠스 문스피어에 레스텐드리스의 거미줄을 가져옵니다.",
    ["Bring Lethtendris's Web to Talo Thornhoof at Camp Mojache in Feralas."] = "페랄라스의 모자케 야영지에서 레스텐드리스의 그물을 탈로 쏜후프로 가져옵니다.",
    ["Bring Mayena Earthseeker a Moist Crystal, a Charged Crystal, a Noxious Crystal and a Fiery Crystal from Shaper's Terrace."] = "마예나 어스시커에게 구체자의 정원에게서 촉촉한 수정, 충전된 수정, 유독한 수정, 불타는 수정을 가져오세요.",
    ["Bring Me His Head"] = "그자의 머리를 가져와라",
    ["Bring Nekrum's Medallion to Thadius Grimshade in the Blasted Lands."] = "저주받은 땅에 있는 네크룸의 메달을 샤디우스 그림섀이드에게 가져가세요.",
    ["Bring Ott's Masterwork to Trevan Rol in Silverpine Forest."] = "오트의 걸작을 은빛소나무 숲의 트레반 롤로 가져옵니다.",
    ["Bring Private Rocknot two Dark Iron Ale Mugs."] = "병사 락노트 검은무쇠 에일 머그잔 2개를 가져오세요.",
    ["Bring Razorflank's Heart to Auld Stonespire in Thunder Bluff."] = "차를가의 심장을 썬더 블러프의 아울드 스톤스파이어로 가져옵니다.",
    ["Bring Razorflank's Medallion to Falfindel Waywarder in Thalanaar."] = "탈라나르에 있는 차를가의 메달을 팔핀델 웨이워더에게 가져가세요.",
    ["Bring Rethiel the Greenwarden 9 Crude Flints."] = "신록의수호자 레시엘 9개의 조잡한 부싯돌을 가져오세요.",
    ["Bring Ribbly's Head to Yuka Screwspigot in the Burning Steppes."] = "불타는 평원에 있는 리블리의 머리카락을 유카 스크류스피곳에게 가져가세요.",
    ["Bring Sharpbeak's Feather to Thadius Grimshade in the Blasted Lands."] = "저주받은 땅에 있는 뾰족부리의 깃털을 샤디우스 그림섀이드에게 가져가세요.",
    ["Bring Techbot's Memory Core to Tinkmaster Overspark in Ironforge."] = "첨단로봇의 기억회로를 아이언포지의 수석땜장이 오버스파크로 가져옵니다.",
    ["Bring Thun'grim Firegaze 15 Smoky Iron Ingots, 10 Powdered Azurite, 10 Iron Bars and a Vial of Phlogiston."] = "툰그림 파이어게이즈 연기가 자욱한 철 주괴 15개, 아주라이트 가루 10개, 철괴 10개 및 연소 약병 1개를 가져오세요.",
    ["Bring Varrox Bleakhoof's Head to Gatekeeper Rageroar at Ursolan."] = "바록스 블리크후프의 머리를 우르솔란에 있는 문지기 레이지로어에게 가져가세요.",
    ["Bring a Libram of Focus, 1 Pristine Black Diamond, 4 Large Brilliant Shards, and 2 Skin of Shadow to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Focus."] = "혈투의 전장에서 집중의 성서, 온전한 검은 다이아몬드 1개, 대형 브릴리언트 파편 4개, 어둠의 허물 2개를 현자 리드로스에 가져가면 집중의 영석을 받을 수 있습니다.",
    ["Bring a Libram of Protection, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 1 Frayed Abomination Stitching to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Protection."] = "혈투의 전장에서 보호의 성서, 온전한 검은 다이아몬드 1개, 대형 브릴리언트 파편 2개, 닳아해진 누더기골렘 조각 1개를 현자 리드로스에 가져가면 보호의 영석을 받을 수 있습니다.",
    ["Bring a Libram of Rapidity, 1 Pristine Black Diamond, 2 Large Brilliant Shards, and 2 Blood of Heroes to Lorekeeper Lydros in Dire Maul to receive an Arcanum of Rapidity."] = "혈투의 전장에서 신속의 성서, 온전한 검은 다이아몬드 1개, 대형 브릴리언트 파편 2개, 영웅의 피 2개를 현자 리드로스에 가져가면 신속의 영석을 받을 수 있습니다.",
    ["Bring a Lieutenant's Insignia from the Burning Blade in Skull Rock to Thrall."] = "해골 바위굴의 불타는 칼날단에서 부관의 휘장을 스랄에게 가져옵니다.",
    ["Bring a Prismatic Punch Card to Master Mechanic Castpipe in Ironforge."] = "오색 천공 카드를 아이언포지의 수석수리공 캐스트파이프로 가져옵니다.",
    ["Bring a Tablet Shard to Kin'weelay at Grom'gol Base Camp."] = "그롬골 베이스캠프에 있는 킨윌레이에게 서판 조각을 가져가세요.",
    ["Bring a Venom Bottle to an apothecary in Tarren Mill."] = "독병을 타렌 밀농장에 있는 약종상에게 가져가세요.",
    ["Bring a pair of Perfect Courser Antlers to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast of the Ruins of Eldarath."] = "완벽한 순록 뿔 한 쌍을 아즈샤라에 있는 오그틴크에게 가져가세요. 오그틴크는 엘다라스 폐허 북동쪽 절벽 꼭대기에 거주합니다.",
    ["Bring a piece of felcloth to Impsy in Felwood."] = "악령의 숲에 있는 임프시에게 지옥옷감 조각을 가져가세요.",
    ["Bring a total of 6 Voodoo Feathers from the trolls in sunken temple."] = "가라앉은 사원의 트롤에게서 총 6개의 부두 깃털을 가져오세요.",
    ["Bring an Azerothian Diamond and a Pristine Black Diamond to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."] = "스톰윈드 대성당 구역에 있는 아제로스 다이아몬드와 온전한 검은 다이아몬드를 그레이슨 섀도브레이커 경에 가져가세요.",
    ["Bring an Enchanted Thorium Bar, 5 Crystal Restore, and a Vial of Dire Water to Aurora Skycaller near the Northpass Tower in Eastern Plaguelands."] = "동부 역병지대의 노스패스 타워 근처에 있는 아우로라 스카이콜러에 마력 깃든 토륨 주괴, 5개의 회복의 수정, 혈투의 웅덩이 물병을 가져옵니다.",
    ["Bring an Infernal Orb to Tabetha in Dustwallow Marsh."] = "먼지진흙 습지대에 있는 타베사에게 지옥의 보주를 가져가세요.",
    ["Bring an Undamaged Venom Sac to Apothecary Lydon in Tarren Mill."] = "온전한 독주머니를 타렌 밀농장의 연금술사 라이던에 가져옵니다.",
    ["Bring five silver bars to Talvash del Kissel in Ironforge."] = "아이언포지에 있는 탈바쉬 델 키젤에 은괴 5개를 가져가세요.",
    ["Bring the Ancient Egg to Yeh'kinya in Tanaris."] = "타나리스에 있는 예킨야에게 고대의 알을 가져가세요.",
    ["Bring the Atal'ai Tablet Fragment to Brohann Caskbelly in Stormwind."] = "아탈라이 서판 조각을 스톰윈드의 브로한 캐스크벨리로 가져옵니다.",
    ["Bring the Blood-Stained Letter to Orphan Matron Nightingale."] = "피로 얼룩진 편지를 보육원 원장님 나이팅게일로 가져오세요.",
    ["Bring the Book of Ur from Shadowfang Keep to Keeper Bel'dugur."] = "그림자송곳니 성채에서 관리인 벨두거로 우르의 책을 가져오세요.",
    ["Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Nogg in Orgrimmar."] = "반짝이는 금반지, 은괴, 태마노 및 은화 30개를 오그리마에 있는 노그에게 가져가세요.",
    ["Bring the Brilliant Gold Ring, a Silver Bar, a Moss Agate, and 30 silver coins to Talvash del Kissel in Ironforge."] = "아이언포지에 있는 탈바쉬 델 키젤에게 반짝이는 금반지, 은괴, 태마노, 은화 30개를 가져가세요.",
    ["Bring the Bundle of Atal'ai Artifacts to the Atal'ai Exile in the Hinterlands."] = "동부 내륙에 있는 아탈라이 유물 자루를 추방된 아탈라이트롤에게 가져가세요.",
    ["Bring the Case of Blood to Gorzeeki Wildeyes in the Burning Steppes."] = "불타는 평원에 있는 고르지키 와일드아이즈에게 피가 담긴 상자를 가져가세요.",
    ["Bring the Cask of Scalder to Furen Longbeard."] = "스칼더 술통을 푸렌 롱비어드로 가져옵니다.",
    ["Bring the Claws of the Great Bear and the Tusks of the Unbroken to Ogtinc in Azshara."] = "아즈샤라에 있는 오그틴크에게 큰곰의 발톱과 깨지지 않은 자의 엄니를 가져가세요.",
    ["Bring the Crest of Lordaeron to the Undercity."] = "로데론의 문장을 언더시티로 가져옵니다.",
    ["Bring the Damp Note to Je'neu Sancrea in Ashenvale."] = "축축한 쪽지를 잿빛 골짜기의 제네우 생크리로 가져옵니다.",
    ["Bring the Darkstone Tablet to Shadow Mage Vivian Lagrave in Kargath."] = "카르가스에 있는 그림자 마법사 비비안 라그레이브에게 다크스톤 서판을 가져가세요.",
    ["Bring the Divino-matic Rod to Chief Engineer Bilgewhizzle in Gadgetzan."] = "자동 탐사막대를 가젯잔의 선임기술자 빌지위즐로 가져옵니다.",
    ["Bring the End"] = "암네나르 처치",
    ["Bring the Fifth and Sixth Mosh'aru Tablets to Prospector Ironboot in Tanaris."] = "타나리스에 있는 발굴조사단장 아이언부트에게 다섯 번째와 여섯 번째 모쉬아루 서판을 가져가세요.",
    ["Bring the Filled Egg of Hakkar to Yeh'kinya in Tanaris."] = "타나리스에 있는 예킨야에게 충만한 학카르의 알을 가져가세요.",
    ["Bring the First and Second Mosh'aru Tablets to Yeh'kinya in Tanaris."] = "타나리스에 있는 예킨야에게 첫 번째와 두 번째 모쉬아루 서판을 가져가세요.",
    ["Bring the Frozen Eggs to Betina Bigglezink."] = "얼어붙은 알을 베티나 비글징크로 가져오세요.",
    ["Bring the Frozen Eggs to Leonid Barthalomew in the Eastern Plaguelands."] = "얼어붙은 알을 동부 역병지대의 리어니드 바돌로매로 가져옵니다.",
    ["Bring the Gems of Cobrahn, Anacondra, Pythas and Serpentis to Nara Wildmane."] = "코브란, 아나콘드라, 피타스 및 서펜티스의 보석을 나라 와일드메인에 가져가세요.",
    ["Bring the Heart of the Mountain to Maxwort Uberglint in the Burning Steppes."] = "불타는 평원에 있는 산의 정수를 맥스워트 우버글린트에게 가져가세요.",
    ["Bring the Imp in a Jar to the alchemy lab in the Scholomance. After the parchment is created, return the jar to Gorzeeki Wildeyes."] = "단지 안에 든 임프를 스칼로맨스에 있는 연금술 연구실로 가져가세요. 양피지를 만든 후 병을 고르지키 와일드아이즈에게 돌려주세요.",
    ["Bring the Inert Scourgestone to Commander Ashlan Valorfist in Chillwind Point."] = "서리바람 거점으로에 있는 아쉬람 발러피스트 사령관에게 마력을 잃은 스컬지석을 가져가세요.",
    ["Bring the Light"] = "빛의 힘",
    ["Bring the Lost Thunderbrew Recipe to Ragnar Thunderbrew in Kharanos."] = "카라노스에 있는 라그나르 썬더브루에게 잃어버린 썬더브루 제조법을 가져가세요.",
    ["Bring the Lost Thunderbrew Recipe to Vivian Lagrave in Kargath."] = "카르가스에 있는 비비안 라그레이브에게 잃어버린 썬더브루 제조법을 가져가세요.",
    ["Bring the Remote Detonator Kit back to Sprite Jumpsprocket in the Dwarven District."] = "원격 기폭장치 도구를 드워프 지구의 스프라이트 점프스프로켓으로 다시 가져옵니다.",
    ["Bring the Satchel of Cursed Mementos to Ashe Amberhall in Farholde Keep."] = "파홀데 성채에 있는 애쉬 앰버홀에게 저주받은 기념품 가방을 가져가세요.",
    ["Bring the Satchel of Mementos to Melanie Sable."] = "기념품 주머니를 멜라니 세이블에게 가져가세요.",
    ["Bring the Strange Water Globe to Je'neu Sancrea at Zoram'gar Outpost, Ashenvale."] = "조람가르 전초기지 잿빛 골짜기에 있는 제네우 생크리에게 이상한 물구슬을 가져가세요.",
    ["Bring the Tablet of Ryun'eh to Theldurin the Lost."] = "류네의 서판을 실성한 텔두린으로 가져옵니다.",
    ["Bring the Third and Fourth Mosh'aru Tablets to Prospector Ironboot in Tanaris."] = "세 번째와 네 번째 모쉬아루 서판을 타나리스에 있는 발굴조사단장 아이언부트에 가져가세요.",
    ["Bring the Tiara of the Deep to Tabetha in Dustwallow Marsh."] = "심연의 티아라를 먼지진흙 습지대의 타베사에게 가져가세요.",
    ["Bring the Tooth of Morphaz to Ogtinc in Azshara. Ogtinc resides atop the cliffs northeast the Ruins of Eldarath."] = "몰파즈의 이빨을 아즈샤라의 오그틴크에 가져오세요. 오그틴크는 엘다라스 폐허 북동쪽 절벽 꼭대기에 거주합니다.",
    ["Bring the Voodoo Feathers from the trolls in the Sunken Temple to the Fallen Hero of the Horde."] = "가라앉은 사원의 트롤에게서 부두 깃털을 호드 영웅의 넋으로 가져옵니다.",
    ["Bring the book Rituals of Power to Tabetha in Dustwallow Marsh."] = "먼지진흙 습지대에 있는 타베사에게 책 마력의 의식을 가져가세요.",
    ["Bring the pieces for the spirit totem to Bath'rah the Windwatcher."] = "영혼 토템 조각을 바람의감시자 바스라에게 가져가세요.",
    ["Bring the voodoo feathers to Ashlam Valorfist."] = "아쉬람 발러피스트에게 부두 깃털을 가져가세요.",
    ["Bring the voodoo feathers to Bath'rah the Windwatcher."] = "부두 깃털을 바람의감시자 바스라에게 가져가세요.",
    ["Bring twenty-four Robo-mechanical Guts to Shoni in Stormwind."] = "스톰윈드에 있는 쇼니에게 24개의 기계장치 부속품을 가져가세요.",
    ["Bring word of Varian Wrynn's fate to Thrall in Orgrimmar."] = "오그리마에 있는 스랄에게 바리안 린의 운명에 대한 소식을 전하세요.",
    ["Briny Sash"] = "짠물 장식띠",
    ["Bristleback Retreat"] = "뾰족털 골짜기",
    ["Brohann Caskbelly"] = "브로한 캐스크벨리",
    ["Brohann Caskbelly in Stormwind wants you to search for the Temple of Atal'Hakkar."] = "브로한 캐스크벨리의 스톰윈드가 아탈학카르 사원을 검색해 달라고 부탁했습니다.",
    ["Brohann Caskbelly — Stormwind"] = "브로한 캐스크벨리 — 스톰윈드",
    ["Brohann Caskbelly — 스톰윈드"] = "브로한 캐스크벨리 — 스톰윈드",
    ["Brohann Caskbelly, Stormwind"] = "브로한 캐스크벨리, 스톰윈드",
    ["Brohann Caskbelly, 스톰윈드"] = "브로한 캐스크벨리, 스톰윈드",
    ["Bronzed Shoulderguards"] = "청동 어깨보호대",
    ["Broodling Essence"] = "새끼용의 정수",
    ["Brother Anton"] = "수사 안톤",
    ["Brother Anton — Desolace"] = "수사 안톤 — 잊혀진 땅",
    ["Brother Anton, Desolace"] = "수사 안톤, 잊혀진 땅",
    ["Brother Anton, Nijel's Point, Desolace"] = "수사 안톤, 나이젤스 포인트, 잊혀진 땅",
    ["Brother Crowley"] = "수사 크롤리",
    ["Brother Crowley — Stormwind"] = "수사 크롤리 — 스톰윈드",
    ["Brother Crowley — 스톰윈드"] = "수사 크롤리 — 스톰윈드",
    ["Brother Crowley, Cathedral of Light, Stormwind"] = "수사 크롤리, 빛의 대성당, 스톰윈드",
    ["Brother Crowley, Cathedral of Light, 스톰윈드"] = "수사 크롤리, 빛의 대성당, 스톰윈드",
    ["Brother Crowley: Cathedral of Light, Stormwind"] = "수사 크롤리: 빛의 대성당, 스톰윈드",
    ["Brother Crowley: Cathedral of Light, 스톰윈드"] = "수사 크롤리: 빛의 대성당, 스톰윈드",
    ["Brother Nimetz"] = "수사 니메츠",
    ["Brother Nimetz at the Rebel Camp, northern Stranglethorn Vale"] = "가시덤불 골짜기 북부 반란군 캠프의 수사 니메츠",
    ["Brother Nimetz — Rebel Camp"] = "수사 니메츠 — 반란군 캠프",
    ["Brother Nimetz, Rebel Camp, Stranglethorn Vale"] = "수사 니메츠, 반란군 캠프, 가시덤불 골짜기",
    ["Brother Nimetz, Rebel Camp, 가시덤불 골짜기"] = "수사 니메츠, 반란군 캠프, 가시덤불 골짜기",
    ["Brotherhood of the Horse +150"] = "말의 형제애 +150",
    ["Bruegal Ironknuckle"] = "브루갈 아이언너클",
    ["Brusslehide Leggings"] = "가시껍질 다리보호구",
    ["Brutal Armor"] = "투사의 방어구",
    ["Brutal Gauntlets"] = "투사 건틀릿",
    ["Brutal Hauberk"] = "투사 갑옷",
