    ["Choose: Ancient Voodoo Pouch or Intrepid Explorer's Chainmail\nAlso: Translated Tale of I'lalai\n2,350 XP • 35s • Stormwind +75 • Ironforge +50"] = "선택: 고대 부두 주머니 또는 용맹스러운 탐험가의 사슬 갑옷\n또한: 일랄라이의 번역된 이야기\n2,350 경험치 • 35초 • 스톰윈드 +75 • 아이언포지 +50",
    ["Choose: Apothecary Gloves, Heat Resistant Mitts or Safety Boots\n4,930 XP • 10s"] = "선택: 약제사 장갑, 내열 미트 또는 안전 부츠\n4,930 경험치 • 10초",
