    ["Choose: Catacomb Cloak or Deepgrave Trousers\n3,570 XP"] = "선택: 지하묘지 망토 또는 깊은무덤 바지\n3,570 경험치",
    ["Choose: Ceremonial Mallet, Sacrificial Sword or I'lalai Flayer\nAlso: Translated Tale of I'lalai, Tale of I'lalai in Zandali\n2,350 XP • 35s"] = "선택: 의식용 망치, 희생의 검 또는 일랄라이 도살자\n또한: 번역된 일랄라이 이야기, 잔달라의 일랄라이 이야기\n2,350 경험치 • 35초",
    ["Choose: Crescent Staff, Wingblade or Hammerbone\n6,380 XP • Thunder Bluff +150"] = "선택: 초승달 지팡이, 날개검 또는 해머본\n6,380 경험치 • 썬더 블러프 +150",
    ["Choose: Dusty Belt or Cryptwalker Bracers\n3,570 XP • 7s • Ironforge +100"] = "선택: 먼지투성이 허리띠 또는 지하방랑자 팔보호구\n3,570 경험치 • 7초 • 아이언포지 +100",
    ["Choose: Duty Bound Leggings or Remembrance Armor\n9,750 XP • 45s"] = "선택: 의무 결속 레깅스 또는 기억 갑옷\n9,750 경험치 • 45초",
    ["Choose: Dwarven Tome or Tomb Robber's Gloves\n4,590 XP • 7s • Gadgetzan +100"] = "선택: 드워프 고서 또는 도굴꾼의 장갑\n4,590 경험치 • 7초 • 가젯잔 +100",
    ["Choose: Edwards' Knife or Tabitha's Cuffs\n7,040 XP • Undercity +150"] = "선택: 에드워드의 칼 또는 타비사의 수갑\n7,040 경험치 • 언더시티 +150",
    ["Choose: Fatebound Buckler, Courier's Clasp or Dustwallow Dirk\n2,400 XP • Orgrimmar +100"] = "선택: 운명결속 버클러, 택배사의 걸쇠 또는 먼지진흙 더크\n2,400 경험치 • 오그리마 +100",
    ["Choose: Forsaken Greataxe or Gnarled Necromancer's Staff\n0 XP • Undercity +150"] = "선택: 포세이큰 거대도끼 또는 울퉁불퉁한 강령술사의 지팡이\n0 경험치 • 언더시티 +150",
    ["Choose: Grizzled Boots, Steel-clasped Bracers or Tattered Mittens\n9,135 XP • Undercity +100"] = "선택: 불곰 장화, 강철죔쇠 팔보호구 또는 너덜너덜한 장갑\n9,135 경험치 • 언더시티 +100",
    ["Choose: Indoctrinated Choker or Convert's Bindings\n11,050 XP"] = "선택: 세뇌된 목장식 또는 개종자의 바인딩\n11,050 경험치",
    ["Choose: Kor'kron Battle Gauntlets, Marshdweller's Pants or Naga Scale Spaulders\n9,700 XP • Orgrimmar +75"] = "선택: 코르크론 전투 건틀릿, 마쉬드웰러 바지 또는 나가 비늘 어깨덮개\n9,700 경험치 • 오그리마 +75",
    ["Choose: Monstrous Cleaver, Grave Shroud or Slain Baron's Signet\n6,188 XP"] = "선택: 괴물 같은 식칼, 무덤 장막 또는 살해당한 남작의 인장\n6,188 경험치",
    ["Choose: Mutinous Cuffs or South Seas Shroud\n10,450 XP • Booty Bay +100 • Ratchet +50 • Gadgetzan +50 • Everlook +50"] = "선택: 반란의 수갑 또는 남해의 수의\n10,450 경험치 • 무법항 +100 • 톱니항 +50 • 가젯잔 +50 • 눈망루 마를 +50",
    ["Choose: Orb of Soran'ruk or Staff of Soran'ruk\n2,550 XP"] = "선택: 소랜루크 수정구 또는 소랜루크의 지팡이\n2,550경험치",
    ["Choose: Overgrown Cuffs or Thornplated Cord\n11,100 XP"] = "선택: 자란 소맷단 또는 가시도금 끈\n11,100경험치",
    ["Choose: Pattern: Deviate Scale Belt, Sizzle Stick or Dagmire Gauntlets\n5,945 XP • 25s"] = "선택: 도안: 돌연변이 비늘 허리띠, 불타는 나뭇가지 또는 수렁늪 건틀릿\n5,945 경험치 • 25초",
    ["Choose: Plaguefang or Blight Gloves\n8,320 XP"] = "선택: 역병송곳니 또는 역병 장갑\n8,320경험치",
    ["Choose: Rock on Stick, Bigger Rock on Bigger Stick or Stick No Rock\n11,500 XP • 1g 30s"] = "선택: 막대기에 붙인 돌, 더 큰 막대기에 더 큰 돌 또는 스틱 돌 없음\n11,500 경험치 • 1g 30초",
    ["Choose: Rock on Stick, Stick No Rock or Bigger Rock on Bigger Stick\n11,500 XP • 1g 30s • Brotherhood of the Horse +150"] = "선택: 막대기에 붙인 돌, 돌 없는 막대기 또는 더 큰 막대기에 더 큰 돌\n11,500 경험치 • 1g 30초 • 말의 형제애 +150",
    ["Choose: Rune-Etched Epaulets or Apprentice Sorcerer's Slacks\n2,350 XP • 35s • Stormwind +75"] = "선택: 룬새김 견장 또는 수습 마법사의 바지\n2,350 경험치 • 35초 • 스톰윈드 +75",
    ["Choose: Rusted Troll War Belt or Saltseer's Helm\n10,450 XP • 1g • Booty Bay +100 • Ratchet +50 • Gadgetzan +50 • Everlook +50"] = "선택: 녹슨 트롤 전쟁 허리띠 or 소금현자의 투구\n10,450 경험치 • 1g • 무법항 +100 • 톱니항 +50 • 가젯잔 +50 • 눈망루 마를 +50",
    ["Choose: Slick Deviate Leggings or Deviate Hide Pack\n4,640 XP • 18s"] = "선택: 돌연변이 가죽 다리보호구 또는 돌연변이 통가죽 배낭\n4,640 경험치 • 18초",
    ["Choose: The Stitcher or Spare Part Bindings\n7,040 XP • 45s • Undercity +150"] = "선택: 스티처 또는 예비 부품 바인딩\n7,040 경험치 • 45초 • 언더시티 +150",
    ["Choose: Theramore Defender's Gauntlets, Marshdweller's Pants or Naga Scale Spaulders\n11,550 XP • Stormwind +100 • Ironforge +100"] = "선택: 테라모어 방어자의 건틀릿, 마쉬드웰러의 바지 또는 나가 비늘 어깨덮개\n11,550 경험치 • 스톰윈드 +100 • 아이언포지 +100",
    ["Choose: Twilight Initiate's Belt or Torn Cultist Cloak\n11,050 XP • Brotherhood of the Horse +150"] = "선택: 황혼의 신입생의 허리띠 or 찢어진 이교도 망토\n11,050 경험치 • 말의 형제애 +150",
    ["Cinder"] = "잉걸불",
    ["Cinderedge"] = "잉걸날",
