    ["Circle of Hope"] = "희망의 고리",
    ["City of Dalaran"] = "달라란",
    ["City of Dalaran Entrance"] = "달라란 입구",
    ["Civinad Robes"] = "선민의 로브",
    ["Classes: Shaman"] = "클래스: 주술사",
    ["Classic"] = "클래식",
    ["Claw of Celebras"] = "셀레브라스의 발톱",
    ["Claws That Rend, Tusks that Gore"] = "살을 찢는 발톱, 몸을 꿰뚫는 엄니",
    ["Claws of the Great Bear"] = "큰곰의 발톱",
    ["Claymore of Two Moons"] = "두 달의 클레이모어",
    ["Cleft of Shadow"] = "어둠의 틈",
    ["Cleft of Shadow, Orgrimmar"] = "어둠의 틈, 오그리마",
    ["Cleft of Shadow, 오그리마"] = "어둠의 틈, 오그리마",
    ["Click a Cauldron of Agamaggan's Blood to summon the Virulent Blood of Agamaggan and kill it for the blood. One cauldron is in the tent nearest the last boss (it may also be in other tents). Blood from Razorfen Kraul doesn't count."] = "아감마간의 피가 담긴 가마솥을 클릭하여 악성 아감마간의 핏덩이를 소환하고 피를 위해 처치하세요. 가마솥 하나는 마지막 보스와 가장 가까운 텐트에 있습니다(다른 텐트에도 있을 수 있음). 가시덩굴 우리의 혈액은 포함되지 않습니다.",
    ["Climb into Thoradin's Wall from the cart on the Hillsbrad side (87.3, 49.6), go through the room in the wall and look outside to the right: the bag hangs there."] = "힐스브래드 쪽(87.3, 49.6)에 있는 카트에서 소라딘의 성벽으로 올라가 벽에 있는 방을 통과하여 오른쪽 밖을 살펴보세요. 가방이 거기에 걸려 있습니다.",
    ["Cloak of Hermitic Bliss"] = "은둔의 행복 망토",
    ["Cloak of the Cosmos"] = "질서의 망토",
    ["Cloak of the Fleshborer"] = "살점포식자의 망토",
    ["Cloak of the Tidemistress"] = "해일여제의 망토",
    ["Clockwerk Run"] = "시계장치 통로",
    ["Cloth"] = "천",
    ["Cloud Stone"] = "구름 수정구",
    ["Cloudrunner Girdle"] = "구름걸이 벨트",
    ["Clugfist"] = "클러그피스트",
    ["Clugfist — Riverglades"] = "클러그피스트 — 강물터",
    ["Clugfist's Decree"] = "클러그피스트의 포고령",
    ["Clugfist, Riverglades (64.4, 14.8)"] = "클러그피스트, 강물터 (64.4, 14.8)",
    ["Clutch of Andros"] = "안드로스의 손아귀",
    ["Coal Miner Boots"] = "석탄광 장화",
    ["Cobalt Crusher"] = "코발트 분쇄기",
    ["Cobrahn"] = "코브란",
    ["Cobrahn's Grasp"] = "코브란의 허리띠",
    ["Codex of Defense"] = "방어의 고서",
    ["Codex of Defense (book, Dire Maul drop)"] = "방어의 고서 (책, 혈투의 전장 드롭)",
    ["Coldbringer"] = "콜드브링어",
    ["Coldbringer Spine"] = "냉기인도자 가시",
    ["Coldrage Dagger"] = "한파의 단검",
    ["Coldspire Staff"] = "냉기첨탑 지팡이",
    ["Collect 10 Atal'ai Tablets around the temple; tablets in the outer temple also count."] = "사원 주변에서 아탈라이 서판 10개를 수집하세요. 바깥 사원에 있는 석판도 중요합니다.",
    ["Collect 10 Bloodied Insignias."] = "피 묻은 휘장 10개를 수집하세요.",
    ["Collect 10 Nordrassil Root Caps in Blackmaw Hold."] = "검은아귀 요새에서 놀드랏실 뿌리껍질 10개를 수집하세요.",
    ["Collect 10 Red Silk Bandanas from Defias inside the Deadmines."] = "죽음의 폐광 안에 있는 데피아즈로부터 붉은 비단 복면 10개를 수집하세요.",
    ["Collect 10 Red Wool Bandanas from Defias prisoners in The Stockade."] = "스톰윈드 지하감옥에 있는 데피아즈 포로로부터 붉은 양모 반다나 10개를 수집하세요.",
    ["Collect 10 Serpentbloom from Wailing Caverns."] = "통곡의 동굴에서 뱀꽃 10개를 수집하세요.",
    ["Collect 10 Shadowshard Fragments from Maraudon and return them to Archmage Tervosh in Theramore on the coast of Dustwallow Marsh."] = "마라우돈에게서 음영석 조각 10개를 모아 먼지진흙 습지대 해안에 있는 테라모어에 있는 대마법사 테르보쉬에게 돌려주세요.",
    ["Collect 10 Shadowshard Fragments from Maraudon and return them to Uthel'nay in Orgrimmar."] = "마라우돈에게서 음영석 조각 10개를 모아 오그리마에 있는 우텔나이에게 가져가세요.",
    ["Collect 10 Twilight Pendants from Twilight's Hammer members in Blackfathom Deeps."] = "검은심연 나락에 있는 황혼의 망치단 멤버로부터 황혼의 펜던트 10개를 수집하세요.",
    ["Collect 10 Voodoo-Infused Artifacts from the Saltseer pirates in the Drowned City."] = "익사한 도시에 있는 소금 시어 해적에게서 부두교가 주입된 유물 10개를 수집하세요.",
    ["Collect 15 Bloodpetals and return to Muigin."] = "핏빛꽃잎 15개를 모아 무이긴에게 돌아가세요.",
    ["Collect 15 Cultist Ears from the Twilight's Hammer in Krol'dok Stronghold."] = "크롤도크 보루에 있는 황혼의 망치단에서 이교도 귀 15개를 수집하세요.",
    ["Collect 15 Partially Digested Journal Pages in Shaper's Terrace."] = "구체자의 정원에서 부분적으로 소화된 일지 페이지 15개를 수집하세요.",
    ["Collect 20 Fetishes of Hakkar and bring them to Fel'Zerul in Stonard."] = "학카르의 우상 20개를 모아 스토나드에 있는 펠제룰에게 가져가세요.",
    ["Collect 20 Fetishes of Hakkar from Atal'ai trolls; outer-temple trolls also drop them."] = "아탈라이 트롤에게서 학카르의 우상 20개를 수집하세요. 외부 사원 트롤도 떨어뜨립니다.",
    ["Collect 20 Minion's Scourgestones and bring them to High Priest Thel'danis in the Western Plaguelands."] = "앞잡이의 스컬지석 20개를 모아 서부 역병지대에 있는 대사제 텔다니스에게 가져가세요.",
    ["Collect 20 Sapphires of Aku'Mai in Blackfathom Deeps."] = "검은심연 나락에서 아쿠마이의 사파이어 20개를 수집하세요.",
    ["Collect 25 Intact Limbs within Ruins of Lordaeron."] = "로데론의 폐허 내에서 온전한 사지 25개를 수집하세요.",
    ["Collect 25 Ogre Warbeads from ogres inside Dire Maul or Blackrock Spire."] = "혈투의 전장이나 검은바위 첨탑 내부의 오우거들로부터 오우거 전투 목걸이 25개를 수집하세요.",
    ["Collect 25 Theradric Crystal Carvings for Willow in Desolace."] = "잊혀진 땅에서 버드나무를 위한 테라드릭 수정 조각품 25개를 수집하세요.",
    ["Collect 4 Miners' Union Cards from undead miners in the tunnels outside the instance."] = "인스턴스 외부 터널에 있는 언데드 광부로부터 광부 조합 카드 4개를 수집하세요.",
    ["Collect 4 Thicket Raptor Hides and take them to James Halloran in Menethil Harbor."] = "덤불 랩터 가죽 4개를 모아 메네실 항구의 제임스 할로란에게 가져가세요.",
    ["Collect 5 I'lalai Fetishes from the trolls in the Drowned City."] = "익사한 도시의 트롤에게서 이랄라이 주물 5개를 수집하세요.",
    ["Collect 5 Stratholme Holy Water from the supply crates in the streets; some crates spawn enemies."] = "거리에 있는 보급 상자에서 스트라솔름 성수 5개를 수집하세요. 일부 상자는 적을 생성합니다.",
    ["Collect 5 Twilight Pages from within Sunnyglade for Ashe Amberhall in Farholde Keep."] = "파홀드 성채에 있는 애쉬 앰버홀을 위해 햇살숲 내에서 황혼의 페이지 5개를 수집하세요.",
    ["Collect 5 Twisted Fire Totems, 5 Twisted Earth Totems, 5 Twisted Air Totems and 5 Twisted Water Totems and turn them in to Prate Cloudseer in Thousand Needles."] = "뒤틀린 불의 토템 5개, 뒤틀린 대지의 토템 5개, 뒤틀린 공기의 토템 5개, 뒤틀린 물의 토템 5개를 모아 버섯구름 봉우리에서 프레이트 클라우드시어에게 가져가세요.",
    ["Collect 5 Twisted Fire Totems, 5 Twisted Earth Totems, 5 Twisted Air Totems and 5 Twisted Water Totems for Veyric Thunderhame in Arathi Highlands."] = "아라시 고원에서 베이릭 썬더헤임을 위해 뒤틀린 불 토템 5개, 뒤틀린 대지 토템 5개, 뒤틀린 공기 토템 5개, 뒤틀린 물 토템 5개를 수집하세요.",
    ["Collect 5 samples of Atal'ai Haze, then return to Muigin in Un'Goro Crater."] = "아탈라이 아지랑이 샘플 5개를 수집한 다음 운고로 분화구에 있는 무이긴에게 돌아가세요.",
    ["Collect 6 Cracked Sentry Cores from the constructs in Dalaran."] = "달라란의 피조물에게서 금이 간 파수꾼 핵 6개를 모으세요.",
    ["Collect 6 Enchanted Coral and return them to Archmage Xylem."] = "마력 깃든 산호 6개를 모아 대마법사 실렘에게 돌려주세요.",
    ["Collect 6 Grizzled Bear Hearts and 6 samples of Skittering Blood and deliver them to Master Apothecary Faranell in the Undercity."] = "회색곰 하트 6개와 땅거미 점액 샘플 6개를 수집하여 언더시티에 있는 수석 연금술사 파라넬에게 전달하세요.",
    ["Collect 7 Longshore Murloc Gills along the Westfall shoreline."] = "서부 몰락지대 해안선을 따라 기나긴 해안 멀록 아가미 7개를 수집하세요.",
    ["Collect 8 Bloodcap and 8 Gorishi Stings, and return to Torwa Pathfinder in Un'Goro Crater."] = "블러드캡 8개와 고리시 스팅 8개를 수집하고 운고로 분화구에 있는 토르와 패스파인더에게 가져가세요.",
    ["Collect 8 Corrupted Brain Stems from creatures in Blackfathom Deeps."] = "검은심연 나락에 있는 생물로부터 손상된 뇌간 8개를 수집하세요.",
    ["Collect 8 Dwarven Heirlooms from the Hall of Thanes."] = "영주의 전당에서 드워프 가보 8개를 수집하세요.",
    ["Collect 8 Suspicious Industrial Supplies from Moonbrook."] = "문브룩에게서 수상한 공업용 보급품 8개를 수집하세요.",
    ["Collect 8 Twilight Bangles from the Twilight's Hammer in Krol'dok Stronghold."] = "크롤도크 보루에 있는 황혼의 망치단에서 황혼의 팔찌 8개를 수집하세요.",
    ["Collect C's payment from the Dead Drop near Pyrewood Village."] = "장작나무 마를 근처의 비밀 접선 지점에서 C의 지불금을 수집합니다.",
    ["Collect Spells of Shadow and Incantations from the Nether inside Ragefire Chasm."] = "성난불길 협곡 내부에서 어둠의 주문서 및 황천의 마법서를 수집합니다.",
    ["Collect a sample of air, fire, earth and water for Bath'rah the Windwatcher."] = "바람의감시자 바스라를 위해 공기, 불, 흙, 물 샘플을 수집하세요.",
    ["Collect the Arcane Mote for the Image of Archmage Modera near the City of Dalaran."] = "달라란 근처에서 대마법사 모데라의 환영용 비전 티끌을 수집하세요.",
    ["Collect the Arcane Mote in the City of Dalaran for Magus Wordeen Voidglare in Tarren Mill."] = "타렌 밀농장의 학자 워딘 보이드글레어에 대해 달라란에서 비전 티끌을 수집합니다.",
    ["Collect the Head of the Baron in Ruins of Lordaeron."] = "로데론의 폐허에서 남작의 머리카락을 수집하세요.",
    ["Collect the Highly Toxic Strain from Witherfang."] = "메마른송곳니에서 고독성 변종을 수집하세요.",
    ["Collecting Memories"] = "기억을 더듬어...",
    ["Collection of Goods"] = "마갑 재료 수집",
    ["Comes for you shortly after Halycon dies."] = "할리콘이 죽은 직후에 찾아옵니다.",
    ["Comes to life at the Grim Guzzler door after Hurley or the bar fight."] = "헐레이나 술집 싸움이 끝난 후 험상궂은 주정뱅이 선술집 문에서 살아납니다.",
    ["Commander Aggro'gosh"] = "사령관 아그로고쉬",
    ["Commander Aggro'gosh at Grom'gol Base Camp, Stranglethorn Vale"] = "사령관 아그로고쉬 그롬골 주둔지에서, 가시덤불 골짜기",
    ["Commander Aggro'gosh at Grom'gol Base Camp, 가시덤불 골짜기"] = "사령관 아그로고쉬 그롬골 주둔지에서, 가시덤불 골짜기",
    ["Commander Aggro'gosh offers it once Enemies in the Water and Locating the Lost City (Kin'weelay) are both handed in."] = "사령관 아그로고쉬는 물속의 적과 잃어버린 도시의 위치(킨윌레이)가 모두 전달되면 이를 제공합니다.",
    ["Commander Aggro'gosh offers it once The Gurubashi Legends of Old is handed in."] = "사령관 아그로고쉬는 구루바시의 옛 전설가 전달되면 제공됩니다.",
    ["Commander Aggro'gosh — Grom'gol Base Camp"] = "사령관 아그로고쉬 — 그롬골 주둔지",
    ["Commander Aggro'gosh, Grom'gol Base Camp, Stranglethorn Vale"] = "사령관 아그로고쉬, 그롬골 베이스캠프, 가시덤불 골짜기",
    ["Commander Aggro'gosh, Grom'gol Base Camp, 가시덤불 골짜기"] = "사령관 아그로고쉬, 그롬골 베이스캠프, 가시덤불 골짜기",
    ["Commander Ashlam Valorfist"] = "사령관 아쉬람 발러피스트",
    ["Commander Ashlam Valorfist — Western Plaguelands"] = "사령관 아쉬람 발러피스트 — 서부 역병지대",
