    ["Defeat 2 Dragonmaw Saboteurs and 4 Dragonmaw Warders, recover the Dragonmaw Dispatch, and report to the Deathstalker Agent outside the dungeon."] = "용아귀 파괴공작원 2마리와 용아귀 수호병 4마리를 처치하고 용아귀 전갈을 회수한 뒤 던전 밖의 죽음의 추적자에게 보고하세요.",
    ["Defeat 8 Seeking Remnants, 8 Saturated Remnants, and 8 Mana Echoes inside the City of Dalaran for Archmage Modera outside of Dalaran."] = "달라란 외부의 대마법사 모데라를 위해 달라란 내부의 탐색 잔재 8개, 포화 잔재 8개, 마나 메아리 8개를 처치하세요.",
    ["Defeat 8 Twilight Fanatics, 8 Twilight Corrupters and 8 Twilight Champions within the Twilight's Shroud for Da'grosh."] = "다그로쉬를 위해 황혼의 장막 내에서 황혼의 광신자 8명, 황혼의 타락자 8명, 황혼의 용사 8명을 처치하세요.",
    ["Defeat 8 Twilight Fanatics, 8 Twilight Corrupters and 8 Twilight Champions within the Twilight's Shroud for Sergeant Riftan."] = "하사관 리프탄을 위해 황혼의 장막 내에서 황혼의 광신자 8명, 황혼의 타락자 8명, 황혼의 용사 8명을 처치하세요.",
    ["Defeat 8 Twilight Raiders, 8 Twilight Shadowmancers and 8 Twilight Neophytes within Sunnyglade for Demar Brant."] = "데마르 브란트를 위해 햇살숲에서 황혼 약탈자 8명, 황혼 암흑술사 8명, 황혼 신도 8명을 처치하세요.",
    ["Defeat 8 Twilight Raiders, 8 Twilight Shadowmancers and 8 Twilight Neophytes within Sunnyglade for Tran'gul in Rog'mar."] = "로그마르의 트란굴을 위해 햇살숲에서 황혼 약탈자 8명, 황혼 암흑술사 8명, 황혼 신도 8명을 처치하세요.",
    ["Defeat Atrexis the Grave Knight in the Dalaran Underbelly."] = "달라란 지하에서 무덤 기사 아트렉시스를 처치하세요.",
    ["Defeat Celebras the Cursed where the paths meet and turn in Legends of Maraudon to Celebras the Redeemed, then help with his ritual and speak to him again for the scepter."] = "길이 만나는 곳에서 저주받은 셀레브라스를 물리치고 마라우돈의 전설을 회복된 셀레브라스로 가져온 다음 그의 의식을 돕고 홀을 위해 그와 다시 대화하세요.",
    ["Defeat Charlga Razorflank in Razorfen Kraul and collect information on the quilboar's plans."] = "가시덩굴 우리에서 서슬깃 차를가를 처치하고 가시멧돼지의 계획에 대한 정보를 수집하세요.",
    ["Defeat Edwin VanCleef and collect his head."] = "에드윈 밴클리프를 처치하고 머리를 수집하세요.",
    ["Defeat Lorgus Jett in Blackfathom Deeps."] = "검은심연 나락에서 로구스 제트를 물리치세요.",
    ["Defeat Overlord Kilgar within the Twilight's Shroud and bring his head to Da'grosh."] = "황혼의 장막 안에 있는 대군주 킬가를 처치하고 그의 머리를 다그로쉬에게 가져가세요.",
    ["Defeat Overlord Kilgar within the Twilight's Shroud and bring his head to Sergeant Riftan."] = "황혼의 장막 내에서 대군주 킬가를 처치하고 그의 머리를 하사관 리프탄에게 가져가세요.",
    ["Defeat Twilight Lord Kelris and recover the Head of Kelris."] = "황혼의 군주 켈리스를 처치하고 켈리스의 머리카락을 회수하세요.",
