    ["Dropped by Overlord Wyrmthalak, Lower Blackrock Spire"] = "검은바위 첨탑 하층의 대군주 웜타라크에게서 획득",
    ["Dropped by Sergeant Bly"] = "하사관 블라이에게서 획득",
    ["Dropped by Skullsplitter Witchdoctors and Mystics in the troll ruins south of the Rebel Camp (4 needed)"] = "반란군 캠프 남쪽의 트롤 폐허에 있는 전투해골 절단기 의술사 및 비술사가 떨어뜨림(4개 필요)",
    ["Dropped by Theka the Martyr"] = "순교자 데카에게서 획득",
