    ["Dropped by Tunk, at the forge beside War Handler Ashka in Krol'dok Stronghold; everyone in the group can loot it"] = "크롤도크 보루의 전투조련사 아슈카 옆에 있는 대장간에서 툰크가 떨어뜨렸습니다. 그룹의 모든 사람이 그것을 약탈할 수 있습니다",
    ["Dropped by Twilight Shadowmancers and Twilight Neophytes in Sunnyglade"] = "햇살숲의 황혼 암흑술사와 황혼 신도에게서 획득",
    ["Dropped by Twilight Shadowmancers and Twilight Neophytes in Sunnyglade (25 needed)"] = "햇살숲의 황혼 암흑술사와 황혼 신도에게서 획득 (25개 필요)",
    ["Dropped by Vicious, Primitive and Savage Owlbeasts in The Hinterlands"] = "동부 내륙지의 포악한·원시·야만 올빼미야수에게서 획득합니다.",
    ["Dropped by War Master Voone, Lower Blackrock Spire"] = "검은바위 첨탑 하층의 대장군 부네에게서 획득",
    ["Dropped by buzzards in the Badlands, e.g. around the big carcass at 15, 60 (5 needed)"] = "황야의 땅의 독수리가 떨어뜨립니다. 15, 60의 큰 시체 주변 (5개 필요)",
    ["Dropped by crag coyotes all over the Badlands (10 needed)"] = "황야의 땅 전체에서 암산 코요테가 떨어뜨림(10개 필요)",
    ["Dropped by rock elementals in the hills by Kargath"] = "카르가스 인근 언덕의 바위 정령에게서 획득",
    ["Dropped by rock elementals in the hills by Kargath, around 13, 36 (5 needed)"] = "카르가스 인근 언덕의 바위 정령에게서 획득합니다. 좌표 약 13, 36(5개 필요).",
    ["Dropped by spiders in the Hinterlands around 35, 64 (not every one has it; everyone in the group can loot it)"] = "35, 64 경에 동부 내륙지에서 거미가 떨어뜨림(모든 사람이 가지고 있는 것은 아니며 그룹의 모든 사람이 약탈할 수 있음)",
    ["Dropped by the Kurzen trolls in and around Kurzen's Compound"] = "쿠르젠 단지 안팎의 쿠르젠 트롤이 떨어뜨림",
    ["Dropped by the Kurzen trolls in and around Kurzen's Compound (7 needed)"] = "쿠르젠 주둔지 안팎의 쿠르젠 트롤이 떨어뜨림(7개 필요)",
    ["Dropped by the Obsidian Sentinel in Uldaman"] = "울다만에서 흑요석 파수꾼가 드랍함",
    ["Dropped by the Rot Hide gnolls on Fenris Isle (Rot Hide Savage, Raging Rot Hide, Rot Hide Bruiser, Snarlmane)"] = "펜리스 섬의 썩은가죽 놀에게서 획득합니다. 썩은가죽일족 야만전사·분노한 썩은가죽일족·썩은가죽일족 투사·스날러메인을 처치하세요.",
    ["Dropped by the Saltseer pirates in the Drowned City"] = "가라앉은 도시의 소금예언자 해적이 떨어뜨렸습니다.",
    ["Dropped by the Sandfury trolls in Zul'Farrak"] = "줄파락에서 성난모래 트롤이 떨어뜨림",
    ["Dropped by the Scarshield Quartermaster in the hallway outside the Spire portal"] = "검은바위 첨탑 입구 바깥 복도의 방패부대 병참장교에게서 획득합니다.",
    ["Dropped by the Shade of Eranikus"] = "에라니쿠스의 사령에서 떨어졌습니다.",
    ["Dropped by the Shadowforge dwarves outside the instance (8 needed)"] = "인스턴스 외부의 어둠괴철로 드워프가 떨어뜨림(8개 필요)",
    ["Dropped by the Twilight's Hammer cultists in Krol'dok Stronghold"] = "크롤도크 보루에서 황혼의 망치단 이교도가 떨어뜨림",
    ["Dropped by the Twilight's Hammer cultists in Krol'dok Stronghold (8 needed)"] = "크롤도크 보루에서 황혼의 망치단 이교도가 떨어뜨림(8개 필요)",
    ["Dropped by the Zukk'ash silithid in Feralas, south of Camp Mojache (around 73, 63)"] = "페랄라스 모자케 야영지 남쪽의 주크애쉬 실리시드에게서 획득합니다(좌표 약 73, 63).",
    ["Dropped by the Zukk'ash silithid south of Camp Mojache (around 73, 63)"] = "모자케 야영지 남쪽의 주크애쉬 실리시드에게서 획득합니다(좌표 약 73, 63).",
    ["Dropped by the Zul'Farrak Zombies that rise from the graves in Zul'Farrak"] = "줄파락의 무덤에서 일어나는 줄파락 좀비가 떨어뜨림",
    ["Dropped by the scarabs in Zul'Farrak (a room full of them on the right-hand path)"] = "줄파락의 풍뎅이 옆에서 드랍됨(오른쪽 경로에 풍뎅이가 가득한 방)",
    ["Dropped by the summoners at Mannoroc Coven, Desolace (around 53, 83)"] = "잊혀진 땅의 만노로크 소굴에 있는 소환사에게서 획득합니다(좌표 약 53, 83).",
    ["Dropped by the troggs and Shadowforge dwarves of the Uldaman dig site"] = "울다만 발굴 현장의 트로그와 섀도우포지 드워프가 떨어뜨림",
