    ["Drops from"] = "획득처:",
    ["Drops from Blackfathom Tide Priestess in the entrance tunnels leading to Blackfathom Deeps."] = "검은심연 나락으로 이어지는 입구 통로의 검은심연의 바다여사제가 드롭합니다.",
    ["Drops from Charlga Razorflank in Razorfen Kraul, for every Shaman on the quest"] = "가시덩굴 우리의 서슬깃 차를가가 드롭, 퀘스트를 수행하는 모든 주술사에 대해",
    ["Drops from Dark Iron dwarves in Blackrock Depths once Abandoned Hope is turned in"] = "획득처: 검은무쇠 드워프 in 검은바위 나락 일단 실망가 켜지면",
    ["Drops from Roogug, the first boss in Razorfen Kraul (take the first left)"] = "획득처: 루구그, 가시덩굴 우리의 첫 번째 보스(첫 번째 왼쪽)",
