    ["Elite, level 40: bring a group. At the steam pools in Thousand Needles, stand on the rune circle and use the Corrupted Totems. Waves of elementals come, then an elite quilboar and the Ravaging Tempest, which drops the Eye of the Tempest for every Shaman on the quest."] = "엘리트, 레벨 40: 그룹을 불러옵니다. 버섯구름 봉우리의 스팀 풀에서 룬 서클 위에 서서 타락한 토템을 사용하세요. 정령의 파도가 오고, 그 다음에는 엘리트 가시멧돼지와 파괴적인 폭풍우가 옵니다. 이는 퀘스트에 참여하는 모든 주술사에게 폭풍우의 눈을 떨어뜨립니다.",
    ["Elite, level 40: bring a group. At the steam pools in Thousand Needles, stand on the rune circle and use the Corrupted Totems. Waves of elementals come, then an elite quilboar and the Ravaging Tempest, which drops the Eye of the Tempest for every Shaman on the quest. Horde: givers not confirmed yet, follow your quest log."] = "40레벨 정예 퀘스트이므로 파티를 구성하세요. 버섯구름 봉우리의 증기 웅덩이에 있는 룬 마법진 위에서 타락한 토템을 사용하면 정령들이 여러 차례 나타납니다. 이어서 정예 가시멧돼지와 거센 폭풍이 나타나며, 퀘스트 중인 모든 주술사가 폭풍의 눈을 획득할 수 있습니다. 호드의 퀘스트 제공자는 아직 확인되지 않았으므로 퀘스트 목록의 안내를 따르세요.",
