    ["Enchanting: disenchant rare items, or buy one (8 needed)"] = "마법 부여: 희귀 아이템을 추출하거나 하나 구매하세요(8개 필요)",
    ["Encoded Fragments"] = "암호화된 페이지",
    ["Encountered alongside Shadowpriest Sezz'ziz during the Zul'Farrak pyramid event. Also drops Nekrum's Medallion for the Alliance quest."] = "줄파락 피라미드 이벤트 중에 어둠의사제 세즈지즈와 함께 조우했습니다. 또한 얼라이언스 퀘스트를 위해 네크룸의 메달을 떨어뜨립니다.",
    ["Encroaching Twilight"] = "다가오는 황혼",
    ["Enemies in the Water"] = "물속의 적",
    ["Energetic Rod"] = "원기의 봉",
    ["Energized Chestplate"] = "활력의 흉갑",
    ["Energized Stone Circle"] = "활력의 돌버클러",
    ["Energy Cloak"] = "에너지 망토",
    ["Engineer's Guild Headpiece"] = "기술자 조합 모자",
    ["Engineering"] = "기계공학",
    ["Enohar Thunderbrew"] = "에노하르 썬더브루",
    ["Enohar Thunderbrew — Blasted Lands"] = "에노하르 썬더브루 — 저주받은 땅",
    ["Enohar Thunderbrew, Nethergarde Keep, Blasted Lands"] = "에노하르 썬더브루, 네더가드 성채, 저주받은 땅",
    ["Enohar Thunderbrew: Nethergarde Keep, Blasted Lands"] = "에노하르 썬더브루: 네더가드 성채, 저주받은 땅",
    ["Enter Alcaz Prison and collect 8 Blood Red Bandanas from the human guards there."] = "알카즈 감옥을 입력하고 그곳의 인간 경비병으로부터 블러드 레드 반다나 8개를 수집하세요.",
    ["Enter Alcaz Prison and learn what became of the King of Stormwind."] = "알카즈 감옥을 입력하고 스톰윈드의 왕이 된 일을 알아보세요.",
    ["Enter Blackmaw Hold and recover 5 Blackmaw Pouches for Ekkal at the Ruins of Eldarath in Azshara."] = "검은아귀 요새에 들어가 아즈샤라의 엘다라스 폐허에서 에칼용 검은아귀 주머니 5개를 회수하세요.",
    ["Enter Blackrock Depths and track down Lord Incendius. Slay him and return any source of information you may find to Thunderheart."] = "검은바위 나락을 입력하고 불의군주 인센디우스를 추적합니다. 그를 처치하고 정보를 얻을 수 있는 곳을 썬더하트에게 가져가십시오.",
    ["Enter Hall of Thanes and claim Durgen Dirgehammer's Head."] = "영주의 전당을 입력하고 드루겐 더지해머의 머리카락을 청구하세요.",
    ["Enter the Alcaz Prison and slay 15 Strashaz Soldiers, 8 Strashaz Enchantresses, and bring the head of Tidemistress Ca'zass to Sergeant Ulka."] = "알카즈 감옥에 들어가 스트라샤즈 병사 15명, 스트라샤즈 요술사 8명을 처치하고 여군주 카자스의 머리를 하사관 울카로 가져가세요.",
    ["Enter the Alcaz Prison and slay 15 Strashaz Soldiers, 8 Strashaz Enchantresses, and bring the head of Tidemistress Ca'zass to Sully McCleary."] = "알카즈 감옥에 들어가 스트라샤즈 병사 15명, 스트라샤즈 요술사 8명을 처치하고 여군주 카자스의 머리를 설리 맥클리어리로 가져가세요.",
    ["Enter the Excavation Sites in the Wetlands and bring back 4 Thicket Raptor Meat."] = "저습지의 발굴지에 들어가 덤불 랩터 고기 4개를 가져오세요.",
    ["Enter the Rethban Caverns, reach the first fork and return to Yorus Barleybrew in time. You must not die and release your spirit."] = "레스반 동굴의 첫 번째 갈림길까지 갔다가 제한 시간 안에 요루스 발리브루에게 돌아가세요. 도중에 죽어 영혼을 해방해서는 안 됩니다.",
    ["Enter through the city's sewers: drop through a grate in the streets and follow the Underbelly pipe to the portal"] = "도시의 하수구를 통해 들어갑니다. 거리의 창살을 통해 떨어지고 마법의 뒤안길 파이프를 따라 포털로 이동합니다.",
    ["Enthralled Sphere"] = "매혹의 구슬",
    ["Entrenching Boots"] = "견고한 보루의 장화",
    ["Ephemeral Choker"] = "덧없는 초커",
    ["Ephemeral Grips"] = "덧없는 손장갑",
    ["Equip"] = "착용 효과",
    ["Eric \"The Swift\""] = "날쌘돌이 에릭",
    ["Escort Belnistrasz to the Quilboar's idol in Razorfen Downs. Protect Belnistrasz while he performs the ritual to shut down the idol."] = "가시덩굴 구릉에서 벨니스트라즈를 가시멧돼지의 우상까지 호위하세요. 벨니스트라즈가 우상을 폐쇄하는 의식을 수행하는 동안 그를 보호하세요.",
    ["Escort Kernobee to the Clockwerk Run exit, then report to Scooty in Booty Bay."] = "케르노비를 시계장치 통으로 출구로 호위한 후 무법항에 있는 스쿠티에게 보고하세요.",
    ["Escort Marshal Windsor through the prison. Clear the patrols first and have everyone ready before you start."] = "감옥을 통해 치안대장 윈저를 호위하세요. 먼저 순찰대를 정리하고 시작하기 전에 모두를 준비시키세요.",
    ["Escort Willix the Importer out of Razorfen Kraul."] = "가시덩굴 우리에서 수입업자 윌릭스를 호위합니다.",
    ["Escort the Defias Traitor until he reveals the Defias hideout, then return to Gryan Stoutmantle."] = "데피아즈단 변절자가 데피아즈 은신처를 드러낼 때까지 호위한 후 그라이언 스타우트맨틀로 돌아갑니다.",
    ["Escort your prisoner, Grark Lorkrub, through Burning Steppes and through Blackrock Mountain to the Searing Gorge. You recall Lexlort mentioning that he would have his men waiting on the other side to take Grark into custody. You will also be required to hand over your Thorium Shackles to Lexlort."] = "불타는 평원을 거쳐 검은바위 산을 거쳐 이글거리는 협곡까지 포로 그랄크 로크럽을 호위하세요. 렉스로트가 그랄크를 구금하기 위해 부하들을 반대편에서 기다리게 할 것이라고 언급한 것을 기억하실 것입니다. 또한 토륨 족쇄를 렉스로트에 넘겨야 합니다.",
    ["Essence Font"] = "정수의 샘",
    ["Essence Font, Sunken Temple"] = "정수의 샘, 가라앉은 사원",
    ["Essence Font, 아탈학카르 신전"] = "정수의 샘, 가라앉은 사원",
    ["Essence of Eranikus"] = "에라니쿠스의 정수",
    ["Essence of Eranikus (drops from the Shade of Eranikus)"] = "에라니쿠스의 정수 (에라니쿠스의 사령에서 드랍)",
    ["Essence of Hakkar"] = "학카르의 정수",
    ["Essence of Seeping Slimes"] = "스며드는 슬라임의 정수",
    ["Essence of the Elements drops from BRD elementals and golems."] = "원소의 정수는 검은바위 나락 정령과 골렘에서 떨어집니다.",
