    ["Explore just west of the Vile Reef and find the cavern entrance, then report back to Kin'weelay."] = "사악한 암초 바로 서쪽을 탐험하여 동굴 입구를 찾은 다음 킨윌레이에게 다시 보고하세요.",
    ["Explore the waters of the Forgotten Pools northwest of the Crossroads, then report back."] = "교차로 북서쪽에 있는 잊혀진 웅덩이의 물을 탐험한 후 보고하십시오.",
