    ["Fervent Helm"] = "열의 투구",
    ["Feyscale Cloak"] = "주문미늘 망토",
    ["Fiendish Machete"] = "극악의 마체테",
    ["Fiery Crystal"] = "불타는 수정",
    ["Fights beside Jammal'an the Prophet."] = "예언자 잠말란 옆에서 싸웁니다.",
    ["Fill her vial at the dire pool along Eldreth Row in Dire Maul West; also bring 1 Enchanted Thorium Bar and 5 Crystal Restore.\n\nOptional introductory quest:"] = "혈투의 전장 서쪽의 엘드레스 광장에 있는 무서운 웅덩이에서 약병을 채우세요. 마력 깃든 토륨 주괴 1개와 회복의 수정 5개도 가져오세요.\n\n선택적인 소개 퀘스트:",
    ["Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon. Use the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge. Heal 8 plants by killing these Noxxious Scion, then return to Talendria in Nijel's Point."] = "마라우돈의 주황색 수정 웅덩이에서 빈 감청석 약병을 채우세요. 바일줄기 덩굴에 가득 찬 감청석 약병을 사용하여 손상된 녹시온의 후예를 강제로 출현시키세요. 녹시온의 후예를 죽여 식물 8개를 치료한 다음 나이젤의 야영지에 있는 탈렌드리아로 돌아가세요.",
    ["Fill the Coated Cerulean Vial at the orange crystal pool in Maraudon. Use the Filled Cerulean Vial on the Vylestem Vines to force the corrupted Noxxious Scion to emerge. Heal 8 plants by killing these Noxxious Scion, then return to Vark Battlescar in Shadowprey Village."] = "마라우돈의 주황색 수정 웅덩이에서 빈 감청석 약병을 채우세요. 바일줄기 덩굴에 가득 찬 감청석 약병을 사용하여 손상된 녹시온의 후예를 강제로 출현시키세요. 녹시온의 후예를 처치하여 식물 8개를 치료한 다음 그늘수렵 마을에 있는 바르크 배틀스카에게 돌아가세요.",
    ["Fill the Coated Cerulean Vial at the orange crystal pool in the outer caves, then use it on Vylestem Vines inside (orange side) and kill the Noxxious Scions to heal 8 plants."] = "외부 동굴에 있는 주황색 수정 웅덩이에서 빈 감청석 약병을 채운 다음 내부(주황색 측면) 바일줄기 덩굴에 사용하고 녹시온의 피조물을 처치하여 식물 8개를 치료합니다.",
    ["Fill the Egg of Hakkar from the Hakkari Bloodkeepers to summon the Avatar of Hakkar."] = "학카리 블러드키퍼에게서 학카르의 알을 채워 학카르의 화신을 소환하세요.",
    ["Final Passage"] = "최후의 시험",
    ["Final boss, at the top of the Downs. Drops the Skull of the Coldbringer for Bring the End."] = "가시덩굴 구릉 꼭대기에 있는 마지막 우두머리입니다. '암네나르 처치'에 필요한 혹한의 해골을 획득할 수 있습니다.",
    ["Final boss, deep in the Kraul."] = "가시덩굴 우리 깊숙한 곳에 있는 마지막 우두머리입니다.",
    ["Final boss, deep in the Warpwood Quarter."] = "굽이나무 지구 깊은 곳에 있는 최종 보스입니다.",
    ["Final boss, in Tinkers' Court. Hit the bomb-face buttons to stop the walking bombs."] = "땜장이 왕실의 최종 보스입니다. 폭탄 얼굴 버튼을 눌러 걸어다니는 폭탄을 멈추세요.",
    ["Final boss, in his lair at the bottom of the temple. Drops the Essence of Eranikus."] = "사원 최하층 둥지에 있는 마지막 우두머리입니다. 에라니쿠스의 정수를 획득할 수 있습니다.",
    ["Final boss, in the Athenaeum. Drops the Gauntlet of Gordok Might for Unfinished Gordok Business."] = "도서관의 마지막 우두머리입니다. '고르독 일 마무리'에 필요한 권력의 고르독 건틀릿을 획득할 수 있습니다.",
    ["Final boss, in the Chamber of Khaz'Mul. Use the altar to wake him. Drops the power source for the necklace quests."] = "카즈뮬의 방에 있는 최종 보스. 그를 깨우려면 제단을 이용하세요. 목걸이 퀘스트의 동력원을 떨어뜨립니다.",
    ["Final boss, in the Earth Song Falls. Zaetar's Spirit appears after her death."] = "지구노래폭포의 최종보스. 재타르의 영혼는 그녀의 죽음 이후에 나타납니다.",
    ["Final boss, in the Hall of Champions. When he dies a wave of Scarlet Trainees rushes in."] = "챔피언의 전당에 있는 최종 보스입니다. 그가 죽자 스칼렛 훈련생들의 물결이 몰려옵니다.",
    ["Final boss, in the Headmaster's Study once the six side-room bosses are dead. He teleports players into the side rooms."] = "최종 보스, 교장실의 6명의 옆방 보스가 죽으면 등장합니다. 그는 플레이어를 옆방으로 순간이동시킵니다.",
    ["Final boss, in the Purple Parlor of the Violet Citadel. Don't stand in line with the Bounding Mana target; he polymorphs the group and resets if someone leaves the room."] = "보라색 성채의 보라색 객실에 있는 최종 보스입니다. 도약하는 마나 목표와 일치하지 마십시오. 그는 그룹을 다형성하고 누군가가 방을 떠나면 재설정합니다.",
    ["Final boss, in the Slaughter House. Rescue Ysida Harmon by killing him within 45 minutes."] = "도살장의 최종보스. 45분 이내에 그를 처치하여 이시다 하몬을 구출하세요.",
    ["Final boss, in the throne room with his two Chromatic Elite Guards. Guards Drakkisath's Brand."] = "두 명의 크로마틱 엘리트 가드와 함께 왕좌의 방에 있는 최종 보스. 경비병 드라키사스의 낙인.",
    ["Final boss, on the throne of the Imperial Seat."] = "황좌의 왕좌에 오른 최종보스.",
    ["Final boss, on the top of the temple. One fight together with Ruuzlu."] = "사원 꼭대기에 있는 최종보스. 루즐루와 함께 한 번의 싸움.",
    ["Final boss. Comes out of the back room when Mograine dies and resurrects him."] = "최종보스. 모그레인이 죽으면 뒷방에서 나와 그를 부활시킵니다.",
    ["Final boss. Killing him makes you the new Gordok king and opens the tribute chest."] = "최종보스. 그를 죽이면 당신은 새로운 고르독 왕이 되고 공물 상자가 열립니다.",
    ["Final boss: Bloodaxe overlord in the Chamber of Battle; calls two Bloodaxe Veterans at low health. Drops the Gemstone of Bloodaxe."] = "전투의 방에 있는 마지막 우두머리인 피도끼 대군주입니다. 생명력이 낮아지면 피도끼 고참병 두 명을 부릅니다. 도끼부대 보석을 획득할 수 있습니다.",
    ["Final boss: Grand Crusader Dathrohan in the Hall of Lights turns into the dreadlord Balnazzar. Drops the Head of Balnazzar."] = "빛의 전당에 있는 마지막 우두머리 십자군사령관 다스로한이 공포의 군주 발나자르로 변신합니다. 발나자르의 머리를 획득할 수 있습니다.",
    ["Final boss: a stone Titan construct."] = "최종 보스: 돌 타이탄 구조물.",
    ["Final boss: the Gurubashi witch doctor Min'loth, whose seat of power was I'lalai."] = "최종 보스: 이'랄라이가 권력을 잡은 구루바시 의술사 민로스.",
    ["Final dungeon step of the Defias Brotherhood chain; complete the earlier steps first."] = "데피아즈단 체인의 마지막 던전 단계. 먼저 이전 단계를 완료하세요.",
    ["Final preparation before Destruction in Deadmines."] = "죽음의 폐광 파괴 작전 이전 최종 준비.",
    ["Final prerequisite before the dungeon step of The Defias Brotherhood."] = "데피아즈단 던전 단계 전 최종 전제조건입니다.",
    ["Final required step before Horrors in the Highland."] = "고지대의 공포 이전에 필요한 최종 단계입니다.",
    ["Final step. Ambassador Malcin is outside Razorfen Downs."] = "마지막 단계. 사절 말킨는 가시덩굴 구릉 외부에 있습니다.",
    ["Final step. Choose Rage of the Storm, Lightning's Grasp or Tidebringer's Claw."] = "마지막 단계. 폭풍의 분노, 번개의 손아귀 또는 파도인도자의 발톱을 선택하세요.",
    ["Final step. Choose Rage of the Storm, Lightning's Grasp or Tidebringer's Claw; Alliance Shamans also get Elementalist's Guard."] = "마지막 단계. 폭풍의 분노, 번개의 손아귀 또는 파도인도자의 발톱을 선택하세요. 얼라이언스 주술사는 정령술사의 수호물도 얻습니다.",
    ["Final step. Old Fire-Eye is at the Greymane Wall in southern Silverpine Forest. Rewards Wolfsbane."] = "마지막 단계. 늙은 불눈는 은빛소나무 숲 남부의 그레이메인 성벽에 있습니다. 울프스베인에게 보상을 줍니다.",
    ["Final step. Rewards Brutal Hauberk."] = "마지막 단계. 보상 투사 갑옷.",
    ["Final step. Rewards Fire Hardened Hauberk."] = "마지막 단계. 보상 화염 경화 갑옷.",
    ["Final step. Rewards Verigan's Fist."] = "마지막 단계. 보상 베리간의 망치.",
    ["Find 3 Soran'ruk Fragments and 1 Large Soran'ruk Fragment and return them to Doan Karhan."] = "소란루크 파편 3개와 큰 소랜루크 조각 1개를 찾아 도안 카르한에게 돌려주세요.",
    ["Find Advisor Belgrum and give him his note."] = "조언자 벨그룸을 찾아 그에게 쪽지를 전해주세요.",
    ["Find Agmond"] = "아그몬드 찾기",
    ["Find Agmond."] = "아그몬드 찾기.",
    ["Find Ardin Grassman in the Excavation Sites. Learn what happened to Ardin Grassman."] = "발굴지에서 아르딘 그래스맨을 찾으세요. 아르딘 그래스맨에게 무슨 일이 있었는지 알아보세요.",
    ["Find Argent Guard Thaelrid inside Blackfathom Deeps."] = "검은심연 나락 안에서 은빛경비병 타엘리드를 찾으세요.",
    ["Find Baelog in Uldaman."] = "울다만에서 밸로그를 찾으세요.",
    ["Find Bijou's Belongings and return them to her. Good luck!"] = "비쥬의 소지품을 찾아 그녀에게 돌려주세요. 행운을 빌어요!",
    ["Find Bijou's Belongings and return them to her. You recall her mentioning that she stashed them on the bottom floor of the city."] = "비쥬의 소지품을 찾아 그녀에게 돌려주세요. 당신은 그녀가 그것들을 도시의 맨 아래층에 숨겨두었다고 언급한 것을 기억합니다.",
    ["Find Borelgore in the northern wastes of Eastern Plaguelands and destroy him. Return to Nathanos Blightcaller when the mission is complete."] = "동부 역병지대 북부 황무지에서 보렐고어를 찾아 처치하세요. 임무를 마치면 나타노스 블라이트콜러에게 돌아가세요.",
    ["Find Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains."] = "돌발톱 산맥의 돌발톱 토굴길 입구 근처에서 브라우그 딤스피릿을 찾으세요.",
    ["Find Commander Folkar inside Alcaz Prison."] = "알카즈 감옥 안에서 폴카르 사령관을 찾으세요.",
    ["Find Commander Gor'shak in Blackrock Depths. You recall that the crudely drawn picture of the orc included bars drawn over the portrait. Perhaps you should search for a prison of some sort."] = "검은바위 나락에서 사령관 고르샤크를 찾습니다. 당신은 오크의 투박한 그림에 초상화 위에 막대가 그려져 있다는 것을 기억합니다. 아마도 당신은 일종의 감옥을 찾아야 할 것입니다.",
    ["Find Da'grosh in the hills west of Rog'mar."] = "로그마르 서쪽 언덕에서 다그로쉬를 찾으세요.",
    ["Find Deathstalker Adamant and Deathstalker Vincent inside Shadowfang Keep."] = "그림자송곳니 성채 안에서 죽음의추적자 아다만트와 죽음의추적자 빈센트를 찾으세요.",
    ["Find Doctor Theolen Krastinov inside the Scholomance. Destroy him, then burn the Remains of Eva Sarkhoff and the Remains of Lucien Sarkhoff. Return to Eva Sarkhoff when the task is complete."] = "스칼로맨스 안에서 학자 테올렌 크라스티노브를 찾으세요. 그를 파괴한 다음 에바 사크호프의 유해와 루시엔 사크호프의 유해를 불태우세요. 작업이 완료되면 에바 사크호프로 돌아갑니다.",
    ["Find Duskwing and slay him. From the corpse, recover a Patch of Duskwing's Fur and return it to Nathanos Blightcaller. It is said that Duskwing roams the countryside to the north of Marris Stead."] = "그늘날개를 찾아서 처치하십시오. 시체에서 그늘날개 모피 조각을 회수하여 나타노스 블라이트콜러에게 돌려주세요. 그늘날개은 메리스 농장 북쪽 시골을 돌아 다닌다고합니다.",
    ["Find Egan. You only know that he was last seen around Stratholme."] = "이건을 찾으세요. 당신은 그가 스트라솔름 근처에서 마지막으로 목격되었다는 것만 알고 있습니다.",
    ["Find Fras Siabi's smoke shop in Stratholme and recover a box of Siabi's Premium Tobacco. Return to Smokey LaRue when the job is done."] = "스트라솔름에 있는 프라스 샤비의 담배 가게를 찾아 샤비의 고급 담배 한 상자를 되찾으세요. 작업이 완료되면 스모키 라루로 돌아갑니다.",
    ["Find Hammertoe Grez in Uldaman."] = "울다만에서 해머토 그레즈를 찾으세요.",
    ["Find Hammertoe's Amulet and return it to him in Uldaman."] = "해머토의 아뮬렛을 찾아 울다만에 있는 그에게 가져가세요.",
    ["Find Interesting Landmarks in Shaper's Terrace and fill out the explorer's map at each: the Pillar of Assimilation, the Achromatic Crystal, the Western Gates, the Regrowth Vestibule and the Unearthed Stone Watcher."] = "구체자의 정원에서 흥미로운 랜드마크를 찾아 동화의 기둥, 무채색 수정, 서쪽 관문, 재성장 현관 및 발굴된 돌 감시자 등 각각에서 탐험가의 지도를 작성하세요.",
    ["Find Lord Incendius in Blackrock Depths and destroy him!"] = "검은바위 나락에서 불의군주 인센디우스를 찾아 파괴하세요!",
    ["Find Marvon Rivetseeker in Tanaris."] = "타나리스에서 마본 리벳시커를 찾으세요.",
    ["Find Maur Grimtotem's corpse inside Ragefire Chasm and search it for anything of interest."] = "성난불길 협곡 안에서 마우르 그림토템의 시체를 찾아 흥미로운 것을 찾아보세요.",
    ["Find Parqual Fintallas in Undercity."] = "언더시티에서 파쿠알 핀탈라스를 찾습니다.",
    ["Find Prospector Ryedol and let him know Hammertoe Grez is alive."] = "발굴조사단장 라이돌을 찾아 해머토 그레즈가 살아있다고 알려주세요.",
    ["Find Ras Frostwhisper in the Scholomance. When you have found him, use the Soulbound Keepsake on his undead visage. Should you succeed in reverting him to a mortal, strike him down and recover the Human Head of Ras Frostwhisper. Take the head back to Magistrate Marduke."] = "스칼로맨스에서 라스 프로스트위스퍼를 찾으세요. 그를 찾으면 그의 언데드 얼굴에 영혼이 씌인 유품을 사용하십시오. 그를 필멸자로 되돌리는 데 성공하면 그를 쓰러뜨리고 사람이 된 라스 프로스트위스퍼의 머리카락을 회수하세요. 머리를 집정관 마르듀크로 다시 가져가세요.",
    ["Find Rethiel the Greenwarden in the Wetlands."] = "저습지에서 신록의수호자 레시엘을 찾습니다.",
    ["Find Sergeant Riftan near the Twilight's Shroud to the west."] = "서쪽에 있는 황혼의 장막 근처에서 하사관 리프탄을 찾으세요.",
    ["Find Starfall in Winterspring and speak with Wynd Nightchaser."] = "여명의 설원에서 별똥별을 찾아 윈드 나이트체이서와 대화하세요.",
    ["Find The Beginnings of the Undead Threat and return it to Parqual Fintallas in Undercity."] = "언데드 위협의 기원을 찾아 언더시티에 있는 파쿠알 핀탈라스에게 돌려주세요.",
    ["Find The Eye of Bhossca inside of the Scarlet Monastery. Then, return it to C's dead drop near Pyrewood Village. You must complete the job alone."] = "붉은십자군 수도원에서 보스카의 눈을 찾아 장작나무 마을 근처의 C의 비밀 접선 지점에 가져가세요. 반드시 혼자 수행해야 합니다.",
    ["Find The Horn of Xelthos inside of Shadowfang Keep. Then, return it to C's dead drop near Pyrewood Village. You must complete the job alone."] = "그림자송곳니 성채에서 젤토스의 뿔을 찾아 장작나무 마을 근처의 C의 비밀 접선 지점에 가져가세요. 반드시 혼자 수행해야 합니다.",
    ["Find Treshala's Pendant and return it to Treshala Fallowbrook in Darnassus."] = "트레샬라의 펜던트를 찾아 다르나서스에 있는 트레샬라 팰로우브룩에게 가져가세요.",
    ["Find Woodwyrd in the Forlorn Gardens at Shen'dralas."] = "셴드랄라스에 있는 쓸쓸한 정원에서 우드위어드를 찾으세요.",
    ["Find a Gordok Shackle Key on the ogres of the Gordok wing and use it to free Knot Thimblejack."] = "고르독 날개의 오우거에서 고르독 족쇄 열쇠를 찾아 이를 사용하여 노트 팀블잭을 구출하세요.",
    ["Find a clue as to the gems' whereabouts in the depths of Uldaman."] = "울다만 깊은 곳에서 보석의 행방에 대한 단서를 찾으세요.",
    ["Find a way into Dalaran along Lordamere Lake."] = "로다미어 호수를 따라 달라란으로 들어가는 길을 찾으세요.",
    ["Find a way to remove the grime from the Grime-Encrusted Ring by using the Sparklematic 5200."] = "빤질빤질세척기 5200을 사용하여 꼬질꼬질한 반지에서 때를 제거하는 방법을 찾아보세요.",
    ["Find and slay Golem Lord Argelmach. Return his head to Lotwil. You will also need to collect 10 Intact Elemental Cores from the Ragereaver Golems and Warbringer Constructs protecting Argelmach."] = "골렘 군주 아젤마크를 찾아 처치하세요. 그의 머리를 로트윌에게 돌려주십시오. 또한 아젤마크를 보호하는 분노의 전투골렘 및 전쟁인도자 피조물에서 온전한 정령의 핵 10개를 수집해야 합니다.",
    ["Find someone in Farholde Keep who may know about the mould."] = "파홀드 성채에서 곰팡이에 대해 아는 사람을 찾으세요.",
    ["Find someone in Rog'mar who may know about the mould."] = "로그마르에서 주형에 관해 아는 사람을 찾으세요.",
    ["Find someone who can translate the paladin's journal. The closest location that might have someone is Kargath, in the Badlands."] = "성기사의 일지를 번역할 수 있는 사람을 찾으세요. 누군가가 있을 수 있는 가장 가까운 위치는 황야의 땅의 카르가스입니다.",
    ["Find the Altar of Hakkar in the Sunken Temple in Swamp of Sorrows."] = "슬픔의 늪의 가라앉은 사원에서 학카르 제단을 찾으세요.",
    ["Find the Felvine in Dire Maul and acquire a shard from it. Chances are you'll only be able to procure one with the demise of Alzzin the Wildshaper. Use the Reliquary of Purity to securely seal the shard inside, and return it to Rabine Saturna in Nighthaven, Moonglade."] = "혈투의 전장에서 지옥덩굴을 찾아 파편을 획득하세요. 칼날바람 알진가 사라지고 나서야 하나를 얻을 수 있을 가능성이 높습니다. 정화의 성물함을 사용하여 조각 내부를 단단히 봉인한 후 달숲 나이트헤이븐에 있는 라빈 사투르나에게 돌려주세요.",
    ["Find the Gauntlet of Gordok Might and return it to Captain Kromcrush in Dire Maul. According to Kromcrush, the \"old timey story\" says that Tortheldrin - a \"creepy\" elf who called himself a prince - stole it from one of the Gordok kings."] = "권력의 고르독 건틀릿을 찾아 혈투의 전장에 있는 대장 크롬크러쉬에게 돌려주세요. 크롬크러쉬에 따르면 \"오래된 이야기\"에 따르면 자신을 왕자라고 부르는 \"소름끼치는\" 엘프인 토르텔드린이 고르독 왕 중 한 명에게서 그것을 훔쳤다고 합니다.",
    ["Find the Gems"] = "보석 찾기",
    ["Find the Gems and Power Source"] = "보석과 마력원천 찾기",
    ["Find the Legacy of the Aspects and return it to Braug Dimspirit near the entrance to Talondeep Path in Stonetalon Mountains."] = "고대의 유산을 찾아 돌발톱 산맥의 돌발톱 토굴길 입구 근처에 있는 브라우그 딤스피릿에게 돌려주세요.",
    ["Find the Messenger Bag at Thoradin's Wall, between Hillsbrad Foothills and the Arathi Highlands."] = "힐스브래드 구릉지와 아라시 고원 사이에 있는 소라딘의 성벽에서 배낭을 찾으세요.",
    ["Find the Sacred Highborne Writings in the Temple of Zin-Malor in Azshara, and bring them to Aurora Skycaller near the Northpass Tower in Eastern Plaguelands."] = "아즈샤라의 진말로 사원에서 귀족의 성서를 찾아 동부 역병지대의 노스패스 타워 근처 아우로라 스카이콜러에게 가져가세요.",
    ["Find the Tablet of Will, and return them to Advisor Belgrum in Ironforge."] = "결의의 서판을 찾아 아이언포지의 조언자 벨그룸에 반환합니다.",
    ["Find the Totem of Ursoc and the Totem of Ursol inside Blackmaw Hold. Then, return them to Lorekeeper Nok at Ursolan."] = "검은아귀 요새 안에서 우르속의 토템과 우르솔의 토템을 찾으세요. 그런 다음 우르솔란에 있는 현자 녹에게 가져가십시오.",
    ["Find the brand that General Drakkisath guards and gain the Mark of Drakkisath, so you can use the Orb of Command."] = "사령관 드라키사스가 지키는 브랜드를 찾아 드라키사스의 증표를 획득하면 지배의 보주를 사용할 수 있습니다.",
    ["Find the cozy spot in the mountains between The Barrens and Desolace: the Pocket Litter at an abandoned camp in Stonetalon Mountains."] = "불모의 땅과 잊혀진 땅 사이의 산에서 아늑한 장소를 찾으세요. 돌발톱 산맥의 버려진 캠프에 있는 휴대용 쓰레기통입니다.",
    ["Find the eagle's nest on the face of the Stonewrought Dam in Loch Modan: the Carved Figurine."] = "모단 호수(모단 호수)의 돌다지 댐 표면에서 독수리 둥지를 찾으세요: 조각상.",
    ["Find the forge in the Deadmines and plant the Extra-Destructive Explosives beside it."] = "죽음의 폐광에서 대장간을 찾아 그 옆에 강력 파괴 폭발물을 설치하세요.",
    ["Find the four Forsaken traitors at the Lordamere Internment Camp, recover their Bloodstone artifacts, and return to Magus Wordeen Voidglare."] = "로다미어 수용소에서 포세이큰 반역자 네 명을 찾아 그들의 혈석 유물을 회수한 후 학자 워딘 보이드글레어에게 돌아가세요.",
    ["Find the four troll tablets on the coast and in the Vile Reef, and bring back the First, Second, Third and Fourth Troll Legends."] = "해안과 더러운 암초에서 트롤 석판 4개를 찾아 첫 번째, 두 번째, 세 번째, 네 번째 트롤 전설을 다시 가져오세요.",
    ["Find the missing Kor'kron Elites."] = "사라진 코르크론 엘리트를 찾으세요.",
    ["Find the owner of the Feathered Charm Necklace."] = "깃털 장식 목걸이의 주인을 찾아보세요.",
    ["Find the phrase to Tirth's strongbox, then return to Tirth."] = "틸스의 금고를 여는 주문을 알아낸 뒤 틸스에게 돌아가세요.",
    ["Find the ruby, sapphire, and topaz that are scattered throughout Uldaman. Once acquired, contact Talvash del Kissel remotely by using the Phial of Scrying he previously gave you."] = "울다만 전역에 흩어져 있는 루비, 사파이어, 토파즈를 찾으세요. 획득한 후에는 이전에 받은 수정점의 유리병을 사용하여 원격으로 탈바쉬 델 키젤과 연락하세요.",
    ["Find the three gemstones of command: the Gemstone of Smolderthorn, Gemstone of Spirestone and Gemstone of Bloodaxe. Return them, along with the Unadorned Seal of Ascension, to Vaelan. The generals are War Master Voone of the Smolderthorn, Highlord Omokk of the Spirestone and Overlord Wyrmthalak of the Bloodaxe."] = "명령의 보석 세 개, 즉 가시불꽃부족 보석, 뾰족바위일족 보석, 도끼부대 보석을 찾으세요. 가공하지 않은 승천의 인장과 함께 밸란에게 돌려주세요. 장군은 가시불꽃의 대장군 부네, 뾰족바위의 대군주 오모크, 피도끼의 대군주 웜타라크입니다.",
    ["Findings for the Explorer's League"] = "탐험가 연맹에 전할 발견",
