    ["First Mate Fitzsimmons — Menethil Harbor"] = "일등항해사 피츠시몬즈 — 메네실 항구",
    ["First Mate Fitzsimmons — 메네실 항구"] = "일등항해사 피츠시몬즈 — 메네실 항구",
