    ["First Mate Fitzsimmons, 메네실 항구, 저습지"] = "일등항해사 피츠시몬즈, 메네실 항구, 저습지",
    ["First Mosh'aru Tablet"] = "첫번째 모쉬아루 서판",
    ["First boss, an undead troll. Enrages near death and hits the whole group hard."] = "첫 번째 보스, 언데드 트롤. 죽을 뻔한 분노를 일으키고 그룹 전체를 강타합니다.",
    ["First quest of the Toxic Soil chain."] = "독성 토양 체인의 첫 번째 퀘스트입니다.",
    ["First required Hidden Enemies step for the Ragefire Chasm chain."] = "성난불길 협곡 체인에 대한 첫 번째 필수 내부의 배신자 단계입니다.",
    ["First required step before Horrors in the Highland."] = "고지대의 공포 이전의 첫 번째 필수 단계입니다.",
    ["First required step leading to The Stockade Riots."] = "감옥 폭동으로 이어지는 첫 번째 필수 단계입니다.",
    ["First step of the Eye of Mugg chain (Mobalytics). Done alongside Curious Trinkets; what leads from Ashe's quests to The Western Front is not confirmed yet."] = "머그의 눈 체인(모발리틱스)의 첫 번째 단계입니다. 호기심 많은 장신구와 함께 완료되었습니다. 애쉬의 퀘스트에서 서부 전선으로 이어지는 내용은 아직 확인되지 않았습니다.",
    ["First step of the Twilight Mementos chain (Mobalytics); what leads from it to The Western Front is not confirmed yet."] = "황혼의 유품 체인(모발리틱스)의 첫 번째 단계; 그것에서 서부 전선으로 이어지는 것은 아직 확인되지 않았습니다.",
    ["First step of the required Defias Brotherhood chain."] = "필수 데피아즈 브라더후드 체인의 첫 번째 단계입니다.",
