    ["Flaming Band"] = "타오르는 고리",
    ["Flarethorn"] = "섬광 쐐기",
    ["Fledgeling and Young Chimaeras"] = "갓 부화한 키메라와 어린 키메라",
    ["Fledgeling and Young Chimaeras, Charred Vale, Stonetalon Mountains (12 needed)"] = "갓 부화한 키메라와 어린 키메라, 까맣게 탄 베일, 돌발톱 산맥 (12개 필요)",
    ["Fleetfoot Greaves"] = "날쌘걸음 경갑",
