    ["Focal Blast"] = "집중 폭발",
    ["Folkar"] = "폴카르",
    ["Follow Reginald Windsor through Stormwind. Protect him from harm!"] = "스톰윈드를 통해 레지널드 윈저를 따릅니다. 그를 위험으로부터 보호하세요!",
    ["Follow the charred note from The Barrens to its twin place: the Burned-Out Remains at the Alexston Farmstead in Westfall."] = "불모의 땅에서 그을린 쪽지를 따라 쌍둥이 장소인 서부 몰락지대의 알렉스턴 농장에 있는 불타버린 잔해로 이동하세요.",
    ["Follow the charred note from Westfall to its twin place: the Burned-Out Remains at the burnt tower south of Camp Taurajo in The Barrens."] = "서부 몰락지대에서 그을린 쪽지를 따라 쌍둥이 장소인 불모의 땅의 타우라조 야영지 남쪽에 있는 불탄 탑에 있는 불타버린 잔해로 이동하세요.",
    ["Follow the road from Southshore"] = "사우스쇼어에서 길을 따라 가세요",
    ["Follow the road to Undercity"] = "언더시티로 가는 길을 따라가세요",
    ["Follow the winding stairs and stone paths downward. The path ends at a bridge over lava with the quest giver Thom Filch and the dungeon portal."] = "구불구불한 계단과 돌길을 따라 아래로 내려갑니다. 경로는 퀘스트 제공자 톰 필치와 던전 포털이 있는 용암 위의 다리에서 끝납니다.",
    ["Follows Speak with Shoni."] = "쇼니와의 대화를 따릅니다.",
    ["Follows the Damp Note version of Allegiance to the Old Gods."] = "고대 신들에 대한 충성의 축축한 쪽지 버전을 따릅니다.",
    ["Footpads of the Fang"] = "송곳니의 장화",
    ["For The Horde!"] = "호드를 위하여!",
