    ["Forever"] = "포에버",
    ["Forever에서 새로 추가됨. 책은 신비술사 도안이 가지고 있습니다."] = "포에버에서 새로 추가됨. 책은 신비술사 도안이 가지고 있습니다.",
    ["Forging the Mightstone"] = "퇴마석 만들기",
    ["Forlorn Gardens"] = "쓸쓸한 정원",
    ["Forsaken Greataxe"] = "포세이큰 거대도끼",
    ["Fought together with Chief Ukorz Sandscalp, on the top of the temple."] = "사원 꼭대기에서 족장 우코르즈 샌드스칼프와 함께 싸웠습니다.",
    ["Fought together with Deathless Marrow."] = "불멸의 골수와 함께 싸웠습니다.",
    ["Fought together with Ogom the Wretched, after the six troll minibosses on the balconies are dead. Drops the Head of Jammal'an."] = "발코니의 트롤 중간 우두머리 여섯을 처치한 뒤 비운의 오그옴과 함께 상대합니다. 잠말란의 머리를 획득할 수 있습니다.",
    ["Fought together with a Primeval Elemental."] = "태고의 정령과 함께 싸웠습니다.",
    ["Foulspore Cavern"] = "독버섯 동굴",
    ["Found in a Pitted Iron Chest underwater in the Pool of Ask'ar, in the northern alcove just past Ghamoo-ra's turtle room."] = "아스카르의 웅덩이 물속, 가무라의 거북이 방 바로 뒤 북쪽 구석의 움푹 파인 철제 궤짝에서 획득.",
    ["Found in: Jordan's Hammer, Shadowfang Keep courtyard"] = "발견 위치: 조던의 망치, 그림자송곳니 성채 안뜰",
    ["Found on a table in Archmage Arugal's room at the end of Shadowfang Keep, after you kill him"] = "그림자송곳니 성채의 끝 부분에 있는 대마법사 아루갈의 방 테이블에서 그를 죽인 후 발견했습니다.",
    ["Found while investigating the Dalaran forces around the Lordamere Internment Camp"] = "로다미어 수용소 주변의 달라란 병력을 조사하던 중 발견됨",
