    ["From Amnennar the Coldbringer, the last boss of Razorfen Downs"] = "혹한의 암네나르에서 가시덩굴 구릉의 마지막 보스입니다.",
    ["From Blazeroar in Alcaz Prison"] = "알카즈 감옥의 화염포효에서",
    ["From Bonesnout the Unbroken in Blackmaw Hold"] = "검은아귀 요새의 불굴의 뼈주둥이에서",
    ["From Elder Shaman Bloodmane in Blackmaw Hold"] = "검은아귀 요새의 장으로 주술사 블러드메인에서",
    ["From Eldreth Phantasms, Spectres, Spirits and Apparitions in Dire Maul (1 needed)"] = "혈투의 전장의 엘드레스 환영, 유령, 영혼 및 망령에서 (1개 필요)",
    ["From Gahz'rilla, summoned with the Mallet of Zul'Farrak at the gong"] = "가즈릴라에서 징에서 줄파락의 나무망치로 소환됨",
    ["From Malor's Strongbox, next to Malor the Zealous"] = "말로의 금고에서 광신자 말로 옆",
    ["From Matrix Punchograph 3005-A"] = "행렬 천공기 3005-A에서 획득",
    ["From Matrix Punchograph 3005-B"] = "행렬 천공기 3005-B에서 획득",
    ["From Matrix Punchograph 3005-C"] = "행렬 천공기 3005-C에서 획득",
    ["From Matrix Punchograph 3005-D"] = "행렬 천공기 3005-D에서 획득",
    ["From Nar'gurk in Krol'dok Stronghold"] = "크롤도크 보루의 나르구르크에서",
    ["From Overlord Kilgar at Twilight's Shroud"] = "황혼의 장막의 대군주 킬가에게서",
    ["From Overlord Kilgar in the Twilight's Shroud, Riverglades"] = "황혼의 장막의 대군주 킬가, 강물터",
    ["From Overlord Mugg, the last boss of Krol'dok Stronghold"] = "대군주 머그에서 크롤도크 보루의 마지막 보스입니다.",
    ["From The Beast's corpse, Upper Blackrock Spire"] = "괴수의 시체에서, 검은바위 첨탑 상층",
    ["From The Questioner in Alcaz Prison"] = "알카즈 감옥의 심문관에서",
    ["From Tidemistress Ca'zass in Alcaz Prison"] = "알카즈 감옥의 여군주 카자스에서",
    ["From Witch Doctor Zum'rah, Zul'Farrak"] = "의술사 줌라, 줄파락에서",
    ["From Withermaw in Blackmaw Hold"] = "검은아귀 요새의 메마른아귀에서",
    ["From ogres in Dire Maul or Blackrock Spire (25 needed)"] = "혈투의 전장 또는 검은바위 첨탑의 오우거에게서 (25개 필요)",
    ["From the Blackmaw furbolgs inside Blackmaw Hold"] = "검은아귀 요새 내부의 검은아귀 펄볼그로부터",
    ["From the Defias guards in Alcaz Prison"] = "알카즈 감옥의 데피아즈 경비병에게서",
    ["From the Twilight's Hammer in Sunnyglade (5 needed)"] = "황혼의 망치단 햇살숲에서 (5개 필요)",
    ["From the Virulent Blood of Agamaggan, which a Cauldron of Agamaggan's Blood summons in Razorfen Downs"] = "가시덩굴 구릉에서 아감마간의 피 가마솥이 소환하는 악성 아감마간의 핏덩이에서",
    ["From the first major three-way junction, take the right-hand tunnel, follow it uphill toward the dead end, then enter the small side room on the left. Interact with Maur's corpse there."] = "첫 번째 주요 삼거리에서 오른쪽 터널을 타고 막다른 골목을 향해 오르막길을 따라가다가 왼쪽에 있는 작은 옆방으로 들어갑니다. 그곳에서 마우어의 시체와 상호작용하세요.",
    ["From the most powerful priest in the Drowned City"] = "익사한 도시의 가장 강력한 사제에게서",
    ["From the slimes in the pools inside Shaper's Terrace"] = "구체자의 정원 내부 웅덩이의 슬라임으로부터",
    ["From the small geyser in the pools Rotgrip swims around in, Maraudon"] = "로트그립이 헤엄치는 수영장의 작은 간헐천에서 마라우돈",
