    ["Get Krom Stoutarm's treasured possession from his chest in the North Common Hall of Uldaman, and bring it to him in Ironforge."] = "울다만의 북쪽 공동 회관에 있는 그의 가슴에서 크롬 스타우트암의 소중한 소지품을 꺼내서 아이언포지로 그에게 가져가세요.",
    ["Get Patrick Garrett's family treasure from their family chest in the South Common Hall of Uldaman, and bring it to him in the Undercity."] = "울다만의 남쪽 공동 홀에 있는 가족 상자에서 패트릭 가레트의 가족 보물을 꺼내 언더시티에 있는 그에게 가져가세요.",
    ["Get a Gordok Shackle Key from the North ogres and free Knot; his cache has loot."] = "북부 오우거에게서 고르독 족쇄 열쇠를 얻고 매듭을 풀어주세요. 그의 캐시에는 전리품이 있습니다.",
    ["Get poisoned by Mother Smolderweb and reach Ragged John while still poisoned. Don't let anyone cleanse it."] = "여왕 불그물거미에 중독되어 중독된 상태에서 털보 존에 도달하세요. 누구도 그것을 청소하지 못하게 하십시오.",
    ["Get the Scoop"] = "주문 알아오기",
    ["Get the fragment from the Firelands elementals inside Blackrock Depths. Which one drops it isn't confirmed yet; please report it on Discord. Seen picked up at level 49."] = "검은바위 나락 안에 있는 불의 땅 정령에게서 조각을 얻으세요. 어느 것이 떨어지는지는 아직 확인되지 않았습니다. 디스코드에 신고해주세요. 49레벨에 획득한 것으로 보입니다.",
    ["Get to the Roots of It"] = "뿌리까지 파헤치기",
