    ["Give Aurius the Medallion of Faith; he joins the fight against Baron Rivendare. Claim his reward after the battle."] = "아우리우스에게 신념의 메달을 제공합니다. 그는 남작 리븐데어와의 싸움에 참여합니다. 전투가 끝난 후 보상을 받으세요.",
