    ["Given by Gryphon Master Talonaxe when you accept the quest"] = "퀘스트 수락 시 그리핀 조련사 탈론액스에게 지급됩니다.",
    ["Given by High Explorer Magellas when you accept the quest"] = "퀘스트 수락 시 선임탐험가 마겔라스에게 지급됩니다.",
