    ["Have Tran'rek in your quest log? Hand it in to Tran'rek first: until then you can't accept Scarab Shells, not even when someone shares it."] = "퀘스트 로그에 트란렉이 있나요? 먼저 트란렉에게 전달하세요. 그때까지는 누군가가 공유하더라도 왕쇠똥구리 껍질을 수락할 수 없습니다.",
    ["Haze of Evil"] = "악의 아지랑이",
    ["He appears from The Beast's corpse after the fight. Malyfous then offers the Pristine Hide of the Beast exchanges."] = "전투 후 괴수의 시체에서 등장합니다. 말리퍼스는 온전한 괴수의 가죽 교환을 제공합니다.",
    ["Head"] = "머리",
    ["Head of Balnazzar"] = "발나자르의 혼",
    ["Head of Balnazzar (drops from Balnazzar)"] = "발나자르의 혼 (발나자르 드랍)",
    ["Head straight north from the camp, climb the hill and jump down from its edge to the Mound of Dirt. Watch your step."] = "캠프에서 바로 북쪽으로 향하고 언덕을 올라 가장자리에서 흙무더기까지 뛰어내립니다. 발걸음을 조심하세요.",
    ["Head to Stormwind Harbor and take the boat to Auberdine. Once you arrive, go to the opposite side of the Auberdine docks and board the ship to Menethil Harbor. Do not get off at Menethil Harbor, stay on the same ship and it will continue to Southshore in Hillsbrad Foothills."] = "스톰윈드 항구로 가서 보트를 타고 아우버다인으로 가세요. 도착하면 아우버다인 부두 반대편으로 가서 메네실 항구로 가는 배에 탑승하세요. 메네실 항구에서 내리지 마시고, 같은 배에 머무르시면 힐스브래드 구릉지에서 사우스쇼어로 계속 이동하게 됩니다.",
    ["Head to the High Seat, King Magni's throne room. As you walk in, take the spiderweb-covered corridor on your left, at coordinates 43.5, 52.0."] = "마그니 왕의 알현실인 높은 자리로 향하세요. 들어와서 좌표 43.5, 52.0에서 왼쪽에 있는 거미줄로 덮인 복도를 따라 가세요.",
    ["Head west to the tunnel that connects Loch Modan to Dun Morogh. Keep moving through the gate and continue west toward Ironforge."] = "모단 호수와 던 모로를 연결하는 터널로 서쪽으로 가세요. 계속해서 게이트를 통과하여 아이언포지 방향으로 서쪽으로 계속 이동하세요.",
