    ["Horde Route to Hall of Thanes"] = "호드 영주의 전당으로 라우팅",
    ["Horde players get it from Mithera after her Forlorn Gardens quest (Wowhead lists that one for the Horde only; how the Alliance gets Word of the Woods is not confirmed yet)."] = "호드 플레이어는 미테라의 쓸쓸한 정원 퀘스트를 마친 뒤 받을 수 있습니다. 와우헤드에서는 해당 퀘스트를 호드 전용으로 분류하고 있으며, 얼라이언스가 '숲의 전언'을 받는 방법은 아직 확인되지 않았습니다.",
