    ["Horde step required before Nogg's Ring Redo."] = "노그의 반지 수리 이전에 호드 단계가 필요합니다.",
    ["Horde version. Handing it in to Da'grosh opens A Token of Vengeance."] = "호드 버전. 다그로쉬에게 전달하면 복수의 토큰이 열립니다.",
    ["Horn of Xelthos"] = "젤토스의 뿔",
    ["Hornbeam Heft"] = "혼빔 높이",
    ["Horned Viking Helmet"] = "바이킹 뿔투구",
    ["Horns of Eranikus"] = "에라니쿠스의 뿔",
    ["Horns of Varrox"] = "바로스의 뿔",
    ["Hot and Itchy"] = "뜨거운 소유욕",
    ["Hotshot Pilot's Gloves"] = "일등 조종사 장갑",
    ["Houndmaster"] = "사냥개조련사",
    ["Houndmaster Boomerang"] = "사냥개조련사 부메랑",
    ["Houndmaster's Bow"] = "사냥개조련사의 활",
    ["Houndmaster's Rifle"] = "사냥개조련사의 라이플",
    ["Houses of the Holy"] = "성스러운 집",
    ["Hulkstone Pauldrons"] = "기암석 어깨갑옷",
    ["Hunt 5 Bloodpetal Lashers, 5 Bloodpetal Threshers, 5 Bloodpetal Flayers and 5 Bloodpetal Trappers for Larion at Marshal's Refuge."] = "마샬의 야영지에 있는 라리온을 위해 붉은꽃잎 채찍꾼 5마리, 붉은꽃잎 탈곡꾼 5마리, 붉은꽃잎 약탈꾼 5마리, 붉은꽃잎 사냥꾼 5마리를 사냥하십시오.",
    ["Hunter class book. Click the book to start the quest."] = "사냥꾼 직업 책입니다. 책을 클릭하면 퀘스트가 시작됩니다.",
    ["Hunter class quest. The Tooth of Morphaz drops from Morphaz.\n\nOptional introductory quest:"] = "헌터 클래스 퀘스트. 몰파즈의 이빨는 몰파즈에서 떨어집니다.\n\n선택적인 소개 퀘스트:",
    ["Hunter trainers"] = "헌터 트레이너",
    ["Hunter with her bear Ferra, on the pylon terraces."] = "철탑 테라스에 있는 헌터와 곰 페라.",
    ["Hunting Spear"] = "사냥용 창",
    ["Hurd Smasher"] = "난타 장갑",
    ["Hurley"] = "헐레이",
    ["Hurley's Tankard"] = "헐레이의 술잔",
    ["Husk of Nerub'enkan"] = "네룹엔칸의 허물",
    ["Hydra Leather Legs"] = "히드라 가죽 다리보호구",
    ["Hydrocane"] = "수력지팡이",
    ["Hydromancer Velratha"] = "유체술사 벨라타",
    ["Hyena Hide Jerkin"] = "하이에나 가죽 웃옷",
    ["Hypnotic Blade"] = "최면의 단검",
    ["I'lalai"] = "일랄라이",
    ["I'lalai Fetish"] = "일랄라이 페티쉬",
    ["I'lalai Flayer"] = "일랄라이 도살자",
    ["I'lalai, a lost Gurubashi troll city, has risen from the sea off the coast of Stranglethorn Vale, west of Grom'gol. Trolls and naga roam the streets of this open-air dungeon, a pirate ship lies wrecked nearby, and the weather builds into a full storm before the final fight. Dive underwater to find the entrance."] = "잃어버린 구루바시 트롤 도시 이랄라이가 그롬골 서쪽 가시덤불 골짜기 해안 바다에서 솟아올랐습니다. 이 야외 던전의 거리에는 트롤과 나가가 배회하고, 근처에는 해적선이 난파되어 있으며, 마지막 전투가 시작되기 전에 날씨가 폭풍처럼 몰아칩니다. 입구를 찾기 위해 수중으로 다이빙하세요.",
    ["Iceblade Hacker"] = "얼음날 도끼",
    ["Icemetal Barbute"] = "빙철 투구",
    ["Idol of Ferocity"] = "야성의 우상",
    ["Idol of Hakkar"] = "학카르 신상",
    ["If you agree to aid Belnistrasz, speak with him again and hand the Oathstone he gave you back to him."] = "벨니스트라즈를 돕는 데 동의한다면 그와 다시 대화하고 그가 준 맹세석을 그에게 돌려주십시오.",
    ["If you are interested in helping Sagorne Crestrider in Orgrimmar's Valley of Wisdom, bring him an Azerothian Diamond and a Pristine Black Diamond."] = "오그리마의 지혜의 계곡에서 사고른 크레스트스트라이더를 돕는 데 관심이 있다면 그에게 아제로스 다이아몬드와 온전한 검은 다이아몬드를 가져오세요.",
    ["If you have faith, leap from the planks overlooking Thousand Needles."] = "믿음이 있다면 버섯구름 봉우리가 내려다보이는 판자에서 뛰어내려보세요.",
    ["If you're not Undead, take the Zeppelin from Orgrimmar to Undercity"] = "언데드가 아니라면 오그리마에서 언더시티로 제플린을 타고 이동하세요.",
    ["Illusionary Rod"] = "환영 마법막대",
    ["Image of Archmage Modera"] = "대마법사 모데라의 환영",
    ["Image of Archmage Modera — Lordamere Lake"] = "대마법사 모데라의 환영 — 로다미어 호수",
    ["Image of Archmage Modera — Lordamere Lake near Dalaran"] = "대마법사 모데라의 환영 — 달라란 근처의 로다미어 호수",
    ["Image of Archmage Modera — Silverpine Forest"] = "대마법사 모데라의 환영 — 은빛소나무 숲",
    ["Image of Archmage Modera — 은빛소나무 숲"] = "대마법사 모데라의 환영 — 은빛소나무 숲",
    ["Image of Archmage Modera, Lordamere Lake near Dalaran"] = "대마법사 모데라의 환영, 달라란 근처의 로다미어 호수",
    ["Imp Delivery"] = "임프 배달",
    ["Impaan"] = "임판",
    ["Impaan the Imprisoner"] = "감금자 임판",
    ["Impaling Harpoon"] = "뾰족한 작살",
    ["Imperial Jewel"] = "제왕의 보석",
    ["Impervious Giant"] = "거대한 무적 망치",
    ["Impish Chain Hood"] = "임피쉬 체인 후드",
    ["Important Heirlooms"] = "중요한 가보",
    ["Impsy"] = "임프시",
    ["Impsy — Felwood"] = "임프시 — 악령의 숲",
    ["Impsy, Bloodvenom Falls, Felwood"] = "임시, 블러드베놈 폴스, 악령의 숲",
    ["Impsy, Felwood"] = "임프시, 악령의 숲",
    ["In Search of Thaelrid"] = "타엘리드 찾기",
    ["In Search of The Temple"] = "신전을 찾아서",
    ["In a tent on top of the mountain above Wailing Caverns"] = "통곡의 동굴 위 산 꼭대기 텐트에서",
    ["In his chest in the North Common Hall, outside the instance"] = "북공동회관 가슴팍, 인스턴스 외부",
    ["In the Black Vault: open all 12 lockers with Relic Coffer Keys (they drop in Blackrock Depths) and Watchman Doomgrip appears. Defeat him and the Secret Safe opens; it holds one of these."] = "검은 금고에서: 유물 금고 키(검은바위 나락에 드롭됨)로 12개의 사물함을 모두 열면 보초 둠그립가 나타납니다. 그를 물리치면 비밀 금고가 열립니다. 이 중 하나를 보유하고 있습니다.\n블랙 포지의",
    ["In the Conspicuous Urn in the room with Baelog, Olaf and Eric"] = "밸로그·올라프·에릭이 있는 방의 특이한 항아리 안",
    ["In the Dig Three area, past the Shadowforge dwarves."] = "세 번째 발굴지 지역에서 어둠괴철로 드워프를 지나세요.",
    ["In the Engineering Labs. Drops the Workshop Key."] = "기술 연구실에 있습니다. 작업장 열쇠를 획득할 수 있습니다.",
    ["In the Foulspore Cavern, past Celebras."] = "오염포자 동굴에서 셀레브라스를 지나세요.",
    ["In the Hall of Secrets; splits into illusions. Drops Krastinov's Bag of Horrors."] = "비밀의 전당에 있으며 환영으로 분열합니다. 소름끼치는 크라스티노브의 가방을 획득할 수 있습니다.",
    ["In the Launch Bay arena."] = "런치베이 경기장.",
    ["In the Map Chamber beyond Archaedas, inside Uldaman"] = "아카에다스 너머 울다만 내부 지도실",
    ["In the Map Chamber. Use the Staff of Prehistoria on the altar to open her door."] = "지도실에 있습니다. 제단에 있는 잃어버린 역사의 지팡이를 사용하여 그녀의 문을 엽니다.",
    ["In the Name of the Light"] = "빛의 이름으로!",
    ["In the Scarlet Archive; burn the archive afterwards (The Archivist)."] = "붉은십자군 기록에서; 나중에 아카이브를 굽습니다(기록관).",
    ["In the Scarlet Bastion, past Timmy. Optional: next to him stands Malor's Strongbox with the Medallion of Faith for The Medallion of Faith (Aurius, at the start of the Undead side)."] = "티미를 지나 십자군 광장에 있습니다. 옆의 말로의 금고에서 '신념의 메달' 퀘스트에 필요한 신념의 메달을 얻을 수 있습니다. 퀘스트는 언데드 구역 입구의 아우리우스에게 받습니다.",
    ["In the Shadowforge Stash in Galgann Firehammer's room; opening it brings two enemies"] = "갈간 파이어해머 방의 어둠괴철로 비밀금고에 있습니다. 열면 적 2명이 나옵니다",
    ["In the Storehouse, guarded by Bloodaxe ogres."] = "창고에서 피도끼 오우거가 지키고 있습니다.",
    ["In the Temple Hall."] = "사원 홀에 있습니다.",
    ["In the Viewing Room, together with Vectus."] = "시청실에서 벡투스와 함께.",
    ["In the Viewing Room; Dawn's Gambit turns the students against him."] = "시청실에서; 여명의 계략는 학생들을 그에게 반대하게 만듭니다.",
    ["In the Wicked Grotto. After he dies, Celebras the Redeemed starts The Scepter of Celebras."] = "사악한 동굴에서. 그가 죽은 후 회복된 셀레브라스는 셀레브라스의 홀을 시작합니다.",
    ["In the basilisk pit at Sul'lithuz Sandcrawlers. Kill his servants when he calls them."] = "술리투즈 샌드크롤러의 바실리스크 구덩이에 있습니다. 그가 부르면 종들을 죽여라.",
    ["In the cave before Ironaya's chamber. Drops The Shaft of Tsol for Staff of Prehistoria."] = "이로나야의 방 앞 동굴에 있습니다. '잃어버린 역사의 지팡이'에 필요한 티솔의 자루를 획득할 수 있습니다.",
    ["In the cave up the ledge on the north wall, northeast of Freewind Post"] = "높새바람 봉우리 북동쪽 북쪽 벽 선반 위의 동굴",
    ["In the family chest in the South Common Hall, outside the instance"] = "남공동회관 가족상자, 인스턴스 외부",
    ["In the graveyard. Zombies rise from the graves when he is pulled."] = "묘지에 있습니다. 그를 끌어당기면 좀비가 무덤에서 일어납니다.",
    ["In the heart of Blackrock Spire you will find Mother Smolderweb. Engage her and get her to poison you. Return to Ragged John while poisoned so that he can 'milk' you."] = "검은바위 첨탑 중심부에서 여왕 불그물거미를 찾을 수 있습니다. 그녀와 교전하여 그녀가 당신을 독살하게 하세요. 중독된 상태에서 털보 존에게 돌아가면 그가 당신에게 '젖을 짜줄' 수 있습니다.",
    ["In the middle of the Sealed Hall, before the instance portal"] = "봉인의 전당 중앙, 인스턴스 포탈 앞",
    ["In the room with the bone pile and the floating skulls."] = "뼈더미와 떠다니는 해골이 있는 방.",
    ["In the vault with his pet Verek, after the six Dark Keepers."] = "여섯 명의 다크 키퍼 이후 애완 동물인 베렉과 함께 금고에 있습니다.",
    ["Incendic Bracers"] = "발연 팔보호구",
    ["Incendius!"] = "인센디우스!",
    ["Incomplete Banner of Provocation"] = "미완성된 도전의 깃발",
    ["Indoctrinated Choker"] = "세뇌된 초커",
    ["Inert Scourgestones"] = "마력을 잃은 스컬지석",
    ["Infernal Orb"] = "지옥의 보주",
    ["Infernal Trickster Leggings"] = "지옥마귀 다리보호구",
    ["Infiltrate Krol'dok Stronghold and return to Commander Brant with proof of their leader's demise."] = "크롤도크 보루에 침투하여 지도자의 죽음에 대한 증거를 가지고 브랜트 사령관에게 돌아가십시오.",
    ["Infiltrate Krol'dok Stronghold and return to Krom'rosh with proof of their leader's demise."] = "크롤도크 보루에 침투하여 리더의 죽음에 대한 증거를 가지고 크롬로쉬로 돌아갑니다.",
    ["Infurnus"] = "인푸르누스",
    ["Inquisitor's Shawl"] = "종교재판관의 어깨걸이",
    ["Insert a Grime-Encrusted Object into the Sparklematic 5200, with three silver coins to start the machine."] = "꼬질꼬질한 물건을 빤질빤질세척기 5200에 삽입하고 은화 3개를 사용하여 기계를 시작하세요.",
    ["Inside Alcaz Prison (who takes it is not known yet)"] = "내부 알카즈 감옥 (누가 복용하는지 아직 알려지지 않음)",
    ["Inside Alcaz Prison, once you learn what became of King Varian Wrynn"] = "알카즈 감옥 안에서 왕 바리안 린가 어떻게 되었는지 알게 되면",
    ["Inside Shaper's Terrace"] = "구체자의 정원 내부",
    ["Inside Uldaman"] = "울다만 내부",
    ["Inside a vault in the Reliquary of Kings (Durgen Dirgehammer's room)"] = "왕의 유물 보관소 내부(드루겐 더지해머의 방)",
    ["Inside the Scarlet Monastery courtyard; the Graveyard is the portal on the right"] = "붉은십자군 수도원 안뜰 내부; 묘지는 오른쪽에 있는 포털입니다.",
    ["Inside the Scarlet Monastery; the Armory door needs The Scarlet Key from the Library"] = "붉은십자군 수도원 내부; 무기고 문에는 도서관의 붉은십자군 열쇠가 필요합니다.",
    ["Inside the Scarlet Monastery; the Cathedral door needs The Scarlet Key from the Library"] = "붉은십자군 수도원 내부; 대성당 문을 열려면 도서관에서 붉은십자군 열쇠가 필요합니다.",
    ["Inside the Scarlet Monastery; the Library has its own portal door"] = "붉은십자군 수도원 내부; 도서관에는 자체 포털 문이 있습니다",
    ["Inside the building in Tarren Mill"] = "타렌 밀농장 건물 내부",
    ["Inside the instance, in the Dormitory."] = "인스턴스 내부, 기숙사.",
    ["Insightful Hood"] = "통찰력의 두건",
    ["Interact with the Skeletal Remains of Telmius Dreamseeker beside Lorekeeper Lydros in the Athenaeum. Unlocks Lydros's libram exchanges."] = "아테네움의 현자 리드로스 옆에 있는 텔미우스 드림시커의 유해와 상호작용하세요. 리드로스의 성서 교환을 잠금 해제합니다.",
    ["Interrogator Vishas"] = "심문관 비샤스",
    ["Into Fenris Keep"] = "펜리스 성채로",
    ["Into The Scarlet Monastery"] = "붉은십자군 수도원으로",
    ["Into The Temple of Atal'Hakkar"] = "아탈학카르 신전으로",
    ["Into the Depths"] = "심연의 늪",
    ["Intrepid Explorer's Chainmail"] = "용감무쌍한 탐험가의 사슬갑옷",
    ["Intricately Runed Shield"] = "룬매듭 방패",
    ["Introductory quest leading to Heart of Disruption and Starving Arcane."] = "분열의 심장 및 굶주린 비전으로 이어지는 입문 퀘스트입니다.",
    ["Introductory step leading to A Better Ingredient."] = "더욱 강력한 재료로 이어지는 입문 단계입니다.",
    ["Introductory step leading to Agmond's Fate."] = "아그몬드의 운명으로 이어지는 입문 단계입니다.",
    ["Introductory step leading to Blood of Morphaz."] = "몰파즈의 피로 이어지는 입문 단계입니다.",
    ["Introductory step leading to Destroy Morphaz."] = "몰파즈 처치로 이어지는 입문 단계입니다.",
    ["Introductory step leading to Doomrigger's Clasp."] = "파멸의 기념물로 이어지는 입문 단계입니다.",
    ["Introductory step leading to Forging the Mightstone."] = "퇴마석 만들기로 이어지는 입문 단계입니다.",
    ["Introductory step leading to Fragments of the Past."] = "과거의 조각으로 이어지는 입문 단계입니다.",
    ["Introductory step leading to Gahz'rilla."] = "가즈릴라로 이어지는 입문 단계입니다.",
    ["Introductory step leading to Hurley Blackbreath."] = "헐레이 블랙브레스로 이어지는 입문 단계입니다.",
    ["Introductory step leading to In the Name of the Light."] = "빛의 이름으로!로 이어지는 입문 단계.",
    ["Introductory step leading to Lethtendris's Web."] = "레스텐드리스의 그물로 이어지는 입문 단계입니다.",
    ["Introductory step leading to Lost Thunderbrew Recipe."] = "잃어버린 썬더브루 제조법으로 이어지는 입문 단계입니다.",
    ["Introductory step leading to Ramstein."] = "람스타인으로 이어지는 입문 단계입니다.",
    ["Introductory step leading to Researching the Corruption."] = "타락에 대한 연구로 이어지는 입문 단계입니다.",
    ["Introductory step leading to Ribbly Screwspigot."] = "리블리 스크류스피곳으로 이어지는 입문 단계입니다.",
    ["Introductory step leading to Scarab Shells."] = "왕쇠똥구리 껍질로 이어지는 입문 단계입니다.",
    ["Introductory step leading to The Azure Key."] = "하늘색 열쇠로 이어지는 입문 단계입니다.",
