    ["It would appear as if the charade is over. You know that the Amulet of Draconic Subversion that Myranda the Hag created for you will not function inside Blackrock Spire. Perhaps you should find Rexxar and explain your predicament. Show him the Dull Drakefire Amulet. Hopefully he will know what to do next."] = "마치 연극이 끝난 것처럼 보일 것입니다. 노파 미란다가 당신을 위해 만들어준 용족 파멸의 아뮬렛는 검은바위 첨탑 안에서는 작동하지 않는다는 걸 아시죠? 아마도 당신은 렉사르를 찾아 당신이 처한 상황을 설명해야 할 것입니다. 그에게 흐릿한 비룡불꽃 아뮬렛을 보여주세요. 그가 다음에 무엇을 해야 할지 알기를 바랍니다.",
