    ["Kill 15 Enraged Apparitions and 10 Tormented Souls, then put Anvilmar's spirit to rest."] = "분노한 유령 15명과 고통받는 영혼 10명을 처치하고 앤빌마의 영혼을 안식시키십시오.",
    ["Kill 15 Kurzen Jungle Fighters."] = "쿠르젠 정글 파이터 15명을 처치하십시오.",
    ["Kill 15 Mosshide Gnolls and 10 Mosshide Mongrels, then return to Rethiel the Greenwarden."] = "이끼가죽 놀 15마리와 이끼가죽 잡종 10마리를 처치한 다음 신록의수호자 레시엘에게 돌아가세요.",
    ["Kill 20 Plagued Hatchlings, then return to Betina Bigglezink at the Light's Hope Chapel."] = "역병 걸린 작은 새끼용 20명을 처치한 다음 희망의 빛 예배당에 있는 베티나 비글징크에게 돌아갑니다.",
    ["Kill 20 Plagued Hatchlings. After turning this in, hatchlings can drop Healthy Dragon Scales, which start a repeatable turn-in to Betina."] = "역병 걸린 작은 새끼용 20명을 처치하세요. 이것을 반납한 후, 새끼는 건강한 용 비늘을 떨어뜨릴 수 있으며, 이는 베티나에 반복적으로 반납을 시작합니다.",
    ["Kill 6 Dalaran Summoners and 12 Elemental Slaves, then return to Magus Wordeen Voidglare in Tarren Mill."] = "달라란 소환사 6명과 원소 노예 12명을 처치한 다음 타렌 밀농장의 학자 워딘 보이드글레어로 돌아갑니다.",
    ["Kill 7 Deviate Ravagers, 7 Deviate Vipers, 7 Deviate Shamblers and 7 Deviate Dreadfangs."] = "일탈 약탈자 7마리, 일탈 독사 7마리, 일탈 엉터리 7마리, 일탈 공포송곳니 7마리를 처치하십시오.",
    ["Kill 7 Helboar in the Blasted Lands and return to the Fallen Hero of the Horde."] = "저주받은 땅에서 헬멧돼지 7마리를 처치하고 호드 영웅의 넋으로 돌아가세요.",
    ["Kill 8 Bleeding Horrors and 8 Wandering Spirits, then report back to Linnea at her camp."] = "출혈하는 공포 8마리와 방황하는 영혼 8마리를 처치한 다음 캠프에 있는 리네아에게 다시 보고하세요.",
    ["Kill 8 Ragefire Troggs and 8 Ragefire Shamans inside Ragefire Chasm."] = "성난불길 협곡 안에 있는 성난불꽃 트로그 8명과 성난불꽃 주술사 8명을 처치하십시오.",
    ["Kill 8 Razorfen Battleguard, 8 Razorfen Thornweavers, and 8 Death's Head Cultists and return to Myriam Moonsinger near the entrance to Razorfen Downs."] = "가시덩굴일족 전투호위병 8명, 가시덩굴 가시술사 8명, 죽음의 머리 이교도 8명을 처치하고 가시덩굴 구릉 입구 근처에 있는 미리암 문싱어로 돌아갑니다.",
    ["Kill Alzzin the Wildshaper, pick up a Felvine Shard near the vine and seal it in the Reliquary of Purity."] = "칼날바람 알진을 죽이고, 덩굴 근처에서 악령덩굴 조각을 집어 정화의 성물함에 봉인합니다.",
    ["Kill Ambassador Infernus in Angor Fortress and bring proof of his death to Advisor Belgrum in Ironforge."] = "고통의 요새에서 사자 인페르누스를 처치하고 아이언포지에 있는 조언자 벨그룸에게 그의 죽음의 증거를 가져가세요.",
    ["Kill Archivist Galford in the Scarlet Bastion and burn the archives."] = "십자군 광장에서 기록관 갈포드를 처치하고 기록 보관소를 불태우세요.",
    ["Kill Archmage Arugal and bring his head to Dalar Dawnweaver."] = "대마법사 아루갈을 처치하고 그의 머리를 달라 던위버로 가져가세요.",
    ["Kill Bazil Thredd in The Stockade and bring his head back to Warden Thelwater."] = "스톰윈드 지하감옥에서 바질 스레드를 처치하고 그의 머리를 교도소장 델워터로 가져가세요.",
    ["Kill Bazzalan and Jergosh the Invoker inside Ragefire Chasm."] = "성난불길 협곡 안에서 바잘란과 기원사 제로쉬를 처치하세요.",
    ["Kill Dextren Ward in The Stockade and bring his hand to Councilman Millstipe."] = "스톰윈드 지하감옥에서 덱스트렌 워드를 처치하고 그의 손을 원으로 밀스타이프에게 가져옵니다.",
    ["Kill General Drakkisath at the end of UBRS."] = "검은바위 첨탑 상층 끝에서 사령관 드라키사스를 죽입니다.",
    ["Kill Golem Lord Argelmach for his head and collect 10 Intact Elemental Cores from the constructs guarding him."] = "그의 머리를 위해 골렘 군주 아젤마크를 처치하고 그를 지키고 있는 구조물에서 온전한 원소 코어 10개를 수집하세요.",
    ["Kill Halycon, the worg den mother. Be ready for Gizrul the Slavener, who comes for you right after."] = "늑대 굴 어미인 할리콘을 처치하세요. 바로 당신을 찾아올 흉포한 기즈룰을 맞이할 준비를 하세요.",
    ["Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Raleigh the Devout in Southshore."] = "종교재판관 화이트메인, 붉은십자군 사령관 모그레인, 헤로드, 붉은십자군 용사 및 사냥개조련사 록시를 죽인 다음 사우스쇼어에서 경건한 신자 랄레이에게 다시 보고하세요.",
    ["Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Varimathras in the Undercity."] = "종교재판관 화이트메인, 붉은십자군 사령관 모그레인, 헤로드, 붉은십자군 용사 및 사냥개조련사 록시를 처치한 다음 언더시티를 타고 바리마트라스에게 다시 보고하십시오.",
    ["Kill High Inquisitor Whitemane, 붉은십자군 사령관 모그레인, 헤로드, the Scarlet Champion and Houndmaster Loksey and then report back to Raleigh the Devout in Southshore."] = "종교재판관 화이트메인, 붉은십자군 사령관 모그레인, 헤로드, 붉은십자군 용사 및 사냥개조련사 록시를 죽인 다음 사우스쇼어에서 경건한 신자 랄레이에게 다시 보고하세요.",
    ["Kill High Inquisitor Whitemane, 붉은십자군 사령관 모그레인, 헤로드, the Scarlet Champion and Houndmaster Loksey and then report back to Varimathras in the Undercity."] = "종교재판관 화이트메인, 붉은십자군 사령관 모그레인, 헤로드, 붉은십자군 용사 및 사냥개조련사 록시를 처치한 다음 언더시티를 타고 바리마트라스에게 다시 보고하십시오.",
    ["Kill Kam Deepfury in The Stockade and bring his head to Motley Garmason."] = "스톰윈드 지하감옥에서 캄 딥퓨리를 처치하고 그의 머리를 모틀리 가마슨으로 가져가세요.",
    ["Kill Lord Incendius at the Black Anvil inside BRD and bring back the Tablet of Kurniya."] = "검은바위 나락 내부의 검은 모루에서 불의군주 인센디우스를 처치하고 쿠르니야의 서판을 가져옵니다.",
    ["Kill Lord Incendius at the Black Anvil inside BRD."] = "검은바위 나락 내부의 검은 모루에서 불의군주 인센디우스를 처치하세요.",
    ["Kill Mekgineer Thermaplugg and return to High Tinker Mekkatorque."] = "멕기니어 텔마플러그를 죽이고 땜장이왕 멕카토크로 돌아갑니다.",
    ["Kill Morphaz in the sunken temple of Atal'Hakkar, and return his blood to Greta Mosshoof in Felwood. The entrance to the sunken temple can be found in the Swamp of Sorrows."] = "아탈학카르의 가라앉은 사원에서 모르파즈를 처치하고 그의 피를 악령의 숲에서 그레타 모스후프에게 돌려주십시오. 가라앉은 사원의 입구는 슬픔의 늪에서 찾을 수 있습니다.",
    ["Kill Nar'gurk in Krol'dok Stronghold and recover any valuable information."] = "크롤도크 보루에서 나르구르크를 처치하고 중요한 정보를 복구하세요.",
    ["Kill Princess Theradras in the inner cavern."] = "내부 동굴에서 공주 테라드라스를 처치하세요.",
    ["Kill Qiaga the Keeper at the top of the Altar of Zul and loot the Sacred Mallet."] = "줄의 제단 꼭대기에서 문지기 퀴아가를 처치하고 신성한 나무망치를 약탈하세요.",
    ["Kill Rath'mael in Ruins of Lordaeron."] = "로데론의 폐허에서 라스마엘을 죽입니다.",
    ["Kill Riptear in north-east Tirisfal Glades and bring Riptear's Heart to Deathguard Linnea."] = "티리스팔 숲 북동쪽에서 너덜토막을 처치하고 너덜토막의 심장을 죽음의경비병 리니아로 가져옵니다.",
    ["Kill Targorr the Dread in The Stockade and bring his head to Guard Berton."] = "스톰윈드 지하감옥에서 흉악범 타고르를 처치하고 그의 머리를 경비병 베르턴으로 가져가세요.",
    ["Kill Var'Taka in the Drowned City."] = "익사한 도시에서 바르타카를 처치하세요.",
    ["Kill a Highland Horror within Excavation Sites and bring its root core to Rethiel the Greenwarden in the Wetlands."] = "발굴지에서 고원 공포괴물을 처치하고 그 뿌리 핵을 저습지의 신록의수호자 레시엘에게 가져가세요.",
    ["Kill mobs in the outer Gnomeregan area until a White Punch Card drops."] = "백색 천공 카드가 떨어질 때까지 놈리건 외곽 지역의 몹을 처치하세요.",
    ["Kill the Demon of the Orb, then speak with Tabetha."] = "보주의 악마를 처치하고 타베타와 대화하세요.",
    ["Kill the guardians of all five pylons, then Immol'thar, then Prince Tortheldrin. Return to the Ancient, take The Treasure of the Shen'dralar and open the chest under the library stairs for the reward."] = "다섯 개의 수정탑의 수호자를 모두 처치한 다음 이몰타르, 왕자 토르텔드린을 처치하세요. 고대로 돌아가서 셴드랄라의 보물을 가지고 도서관 계단 아래 상자를 열어 보상을 받으세요.",
    ["Kill the six troll guardians on the balconies to drop Jammal'an's barrier, then bring back his head."] = "발코니에 있는 트롤 수호자 여섯 명을 처치하여 잠말란의 방벽을 떨어뜨린 다음 그의 머리를 되찾으세요.",
    ["Kilt of the Atal'ai Prophet"] = "아탈라이 예언자의 킬트",
    ["Kin'weelay"] = "킨윌레이",
