    ["Living Root"] = "살아있는 뿌리",
    ["Locate Jandice Barov in the Scholomance and destroy her. From her corpse recover Krastinov's Bag of Horrors. Return the bag to Eva Sarkhoff."] = "스칼로맨스에서 잔다이스 바로브를 찾아 파괴하세요. 그녀의 시체에서 소름끼치는 크라스티노브의 가방을 회수하세요. 가방을 에바 사크호프에게 돌려주세요.",
    ["Locate Magister Kirandis inside the temple of Shen'dralas."] = "셴드랄라스의 사원 내부에서 마법학자 키란디스를 찾습니다.",
