    ["Lonebrow's Journal"] = "론브로우의 일지",
    ["Long rumored to hold high-ranking prisoners, including King Varian Wrynn, the prison on Alcaz Island has been out of reach until now. Inside, the Defias Brotherhood and the naga are at war."] = "오랫동안 바리안 린 왕을 포함한 고위 포로들을 수용하고 있다는 소문이 돌았지만, 알카즈 섬의 감옥은 지금까지 손이 닿지 않는 곳이었습니다. 내부에서는 데피아즈단과 나가가 전쟁을 벌이고 있습니다.",
    ["Longshore"] = "기나긴 해안",
    ["Look for Dorin Songblade's brother, Daewyn, in Whelgar's Excavation Site."] = "웰가르 발굴지에서 도린 송블레이드의 동생 대윈을 찾으세요.",
    ["Look for King Varian Wrynn in Alcaz Prison."] = "알카즈 감옥에서 왕 바리안 린을 찾으세요.",
    ["Look for a valuable necklace within the Uldaman dig site and bring it back to Dran Droffers in Orgrimmar. The necklace may be damaged."] = "울다만 발굴 현장에서 귀중한 목걸이를 찾아 오그리마에 있는 드란 드로퍼스에게 가져가세요. 목걸이가 파손될 수 있습니다.",
    ["Lookie's Spyglass"] = "루키의 망원경",
    ["Loomguard Armbraces"] = "절벽지기 손목보호대",
    ["Loose Floorboard"] = "느슨한 마루판",
    ["Loot Chest"] = "전리품 상자",
    ["Loot Lonebrow's Journal here"] = "전리품 론브로우의 일지 여기",
    ["Loot the Amulet of Spirits from the Nameless Prophet in the outer caves, then use it to fight the five Khans: three in the outer caves, one on the purple route and one on the orange route. Combine their gems with the amulet."] = "외부 동굴에 있는 이름 없는 예언자에게서 영혼의 아뮬렛을 약탈한 다음 이를 사용하여 5명의 칸(외부 동굴에 3개, 보라색 경로에 1개, 주황색 경로에 1개)과 싸우십시오. 보석을 부적과 결합하세요.",
    ["Looted in Blackmaw Hold; specific drop source not yet confirmed"] = "는 검은아귀 요새에서 약탈되었습니다. 구체적인 드롭 소스는 아직 확인되지 않았습니다.",
    ["Looted inside Blackmaw Hold; everyone in the party can loot them (10 needed)"] = "검은아귀 요새 내부에서 약탈했습니다. 파티원 모두가 약탈할 수 있습니다(10개 필요).",
