    ["Ogre outrunners have been kidnapping travelers and raiding settlements across the Riverglades. Their trail leads to a fortress of workshops, encampments and guarded inner passages, where strange chanting is heard after nightfall."] = "오우거 아웃러너들은 여행자들을 납치하고 강물터 전역의 정착지를 습격해 왔습니다. 그들의 길은 작업장, 야영지, 그리고 해가 진 후에 이상한 노래가 들리는 내부 통로로 이루어진 요새로 이어집니다.",
    ["Ogreseer Fists"] = "오우거 현자 장갑",
