    ["On Alcaz Island, off north-east Dustwallow Marsh: from the dock take the path up the hill to the prison building at the north end; the portal is in its cellar"] = "북동쪽에 있는 알카즈 섬 먼지진흙 습지대: 부두에서 북쪽 끝에 있는 감옥 건물까지 언덕을 올라가는 길로 가세요. 포털은 지하실에 있어요",
    ["On Electrocutioner 6000's platform."] = "기계화 문지기 6000의 플랫폼.",
    ["On Market Row, in front of the Scarlet Bastion."] = "상가의 십자군 광장 앞.",
    ["On a bookshelf in the last hallway before Arcanist Doan, Scarlet Monastery Library"] = "신비술사 도안 앞 마지막 복도 책장, 붉은십자군 도서관",
    ["On a box at the abandoned camp"] = "버려진 캠프의 상자 위에\n버려진 캠프의 상자에 있는",
    ["On a round terrace in the streets after leaving the sewers. Casts Arcane Bolt and Focal Blast."] = "하수도를 나온 뒤 거리의 둥근 테라스에 있습니다. 비전 화살과 집중 폭발을 시전합니다.",
    ["On the carved heads of the dam, facing the Wetlands"] = "댐의 조각된 머리 위, 저습지를 향함",
    ["On the ground at Agmond's End, southern Badlands"] = "남쪽 아그몬드 엔드 지상 황야의 땅",
    ["On the ground in the Witherbark troll camps, The Hinterlands"] = "마른나무껍질 트롤 캠프 지상에 있는 동부 내륙지",
    ["On the hilltop east of the Crossroads, just south of Thorn Hill"] = "크로스로드 동쪽 언덕 꼭대기, 가시덩굴 언덕 바로 남쪽",
    ["On the path up the Downs, after Mordresh."] = "모드레쉬를 지나 가시덩굴 구릉 위쪽으로 올라가는 길에 있습니다.",
    ["On the wall in Kargath, Badlands"] = "카르가스 벽에, 황야의 땅",
    ["On the wall in Kargath, 황야의 땅"] = "카르가스 벽에, 황야의 땅",
    ["Once you reach Tirisfal Glades, follow the road toward Undercity. Once you enter Undercity, turn left and go upstairs, there's the dungeon entrance."] = "티리스팔 숲에 도달하면 언더시티 방향으로 도로를 따라 가세요. 언더시티에 들어가서 좌회전하여 위층으로 올라가면 던전 입구가 있습니다.",
    ["One crystal at each centaur camp in Desolace."] = "잊혀진 땅의 각 켄타우로스 캠프마다 크리스탈 1개.",
    ["One of the six bosses in the side rooms."] = "옆방에 있는 6명의 보스 중 한 명.",
    ["One of the six bosses in the side rooms. Drops a Barov deed."] = "곁방 여섯 곳에 있는 우두머리 중 하나입니다. 바로브 가문의 증서를 획득할 수 있습니다.",
    ["One of the six bosses in the side rooms; all six must die to summon Gandling."] = "옆방에 있는 6명의 보스 중 한 명. 간들링을 소환하려면 여섯 명 모두 죽어야 합니다.",
