    ["Outside Dalaran near Lordamere Lake"] = "로다미어 호수 근처 달라란 외부\n거리의 피를 위해 제공되는",
    ["Outside the instance: urns on both sides of the gate and under the tents before Dig One"] = "인스턴스 외부: 문 양쪽과 첫 번째 발굴지 앞 텐트 아래에 있는 항아리",
