    ["Ozzie"] = "오지",
    ["Ozzie Togglevolt"] = "오지 토글볼트",
    ["Ozzie Togglevolt — Kharanos"] = "오지 토글볼트 — 카라노스",
    ["Ozzie Togglevolt — 카라노스"] = "오지 토글볼트 — 카라노스",
    ["Ozzie Togglevolt, Kharanos, Dun Morogh"] = "오지 토글볼트, 카라노스, 던 모로",
    ["Ozzie Togglevolt, 카라노스, 던 모로"] = "오지 토글볼트, 카라노스, 던 모로",
    ["Padre's Trousers"] = "신부의 바지",
    ["Pads of the Dread Wolf"] = "사나운 늑대 발보호구",
    ["Painwalker Buckler"] = "고통방랑자 버클러",
    ["Painweaver Band"] = "아픔의 반지",
    ["Paladin charger quest. Clear Rattlegore's basement in the Great Ossuary, use the Divination Scryer and defeat the spirits and Death Knight Darkreaver."] = "팔라딘 차저 퀘스트. 대형 납골당에 있는 들창어금니의 지하실을 청소하고 예언의 탐지기를 사용하여 영혼과 죽음의 기사 다크리버를 처치하세요.",
    ["Paladin charger quest. Kill Tendris Warpwood, then feed the Ancient Equine Spirit and give it the Arcanite Barding. Bring the Manna-Enriched Horse Feed from Merideth Carlson in Southshore."] = "팔라딘 차저 퀘스트. 굽이나무 텐드리스를 죽인 다음 고대 준마의 영혼을 먹이고 아케이나이트 마갑을 줍니다. 사우스쇼어의 메리데스 칼슨에서 맛좋은 만나 사료를 가져옵니다.",
    ["Paladin class book. Click the book to start the quest."] = "성기사 클래스북. 책을 클릭하면 퀘스트가 시작됩니다.",
    ["Paladin class quest for humans and dwarves. In this dungeon: Jordan's Smithing Hammer is picked up from the object Jordan's Hammer in the courtyard. The other parts are Whitestone Oak Lumber (The Deadmines), the Kor Gem (Blackfathom Deeps) and Jordan's ore shipment (Loch Modan)."] = "인간과 드워프를 위한 성기사 클래스 퀘스트입니다. 이 던전에서는 조던의 대장장이 망치가 안뜰에 있는 조던의 망치 개체에서 획득됩니다. 다른 부품은 흰돌참나무 재목(죽음의 폐광), 코르석(검은심연 나락) 및 조던의 광석 선적(모단 호수)입니다.",
    ["Paladin class quest for humans and dwarves. In this dungeon: Whitestone Oak Lumber drops from Goblin Woodcarvers. The other parts are Jordan's Smithing Hammer (Shadowfang Keep), the Kor Gem (Blackfathom Deeps) and Jordan's ore shipment (Loch Modan)."] = "인간과 드워프를 위한 성기사 클래스 퀘스트입니다. 이 던전에서는 흰돌참나무 재목가 고블린 목공에게서 떨어집니다. 다른 부품은 조던의 대장장이 망치(그림자송곳니 성채), 코르석(검은심연 나락) 및 조던의 광석 선적(모단 호수)입니다.",
    ["Paladin class quest for humans and dwarves. In this dungeon: the Corrupted Kor Gem drops from Blackfathom Sea Witches inside, and from Blackfathom Tide Priestesses and Oracles at the entrance in Ashenvale. Thundris Windweaver in Auberdine purifies it. The other parts are Whitestone Oak Lumber (The Deadmines), Jordan's Smithing Hammer (Shadowfang Keep) and Jordan's ore shipment (Loch Modan)."] = "인간과 드워프를 위한 성기사 클래스 퀘스트입니다. 이 던전에서는 부정한 코르석가 내부의 검은심연 바다마녀와 잿빛 골짜기 입구의 검은심연 여사제 및 예언자에서 드롭됩니다. 아우버다인에 있는 툰드리스 윈드위버가 그것을 정화합니다. 다른 부품은 흰돌참나무 재목(죽음의 폐광), 조던의 대장장이 망치(그림자송곳니 성채) 및 조던의 광석 선적(모단 호수)입니다.",
    ["Paladin class quest for undead and tauren. In this dungeon: Whitestone Oak Lumber drops from Goblin Woodcarvers. The other parts are the Enchanted Silver Ingot (Shadowfang Keep) and the Purified Kor Gem (Blackfathom Deeps)."] = "언데드와 타우렌을 위한 성기사 클래스 퀘스트입니다. 이 던전에서는 흰돌참나무 재목가 고블린 목공에게서 떨어집니다. 다른 부품은 마력 깃든 은 주괴(그림자송곳니 성채)와 정화된 코르석(검은심연 나락)입니다.",
    ["Paladin class quest for undead and tauren. In this dungeon: the Corrupted Kor Gem drops from Blackfathom Sea Witches inside, and from Blackfathom Tide Priestesses and Oracles at the entrance in Ashenvale, once you have Seeking the Kor Gem from Ulric Frostveil at Zoram'gar Outpost. He purifies it. The other parts are Whitestone Oak Lumber (The Deadmines) and the Enchanted Silver Ingot (Shadowfang Keep)."] = "언데드와 타우렌을 위한 성기사 클래스 퀘스트입니다. 이 던전에서는 부정한 코르석가 내부의 검은심연 바다마녀에게서, 그리고 잿빛 골짜기 입구의 검은심연 여사제 및 예언자에서 드롭됩니다. 일단 조람가르 전초기지의 울릭 프로스트베일에게서 코르석을 찾아서를 얻으면 됩니다. 그는 그것을 정화합니다. 다른 부품은 흰돌참나무 재목(죽음의 폐광)와 마력 깃든 은 주괴(그림자송곳니 성채)입니다.",
    ["Paladin class quest for undead and tauren. In this dungeon: the Enchanted Silver Ingot lies on a table in Archmage Arugal's room, after you kill him. The other parts are Whitestone Oak Lumber (The Deadmines) and the Purified Kor Gem (Blackfathom Deeps)."] = "언데드와 타우렌을 위한 성기사 클래스 퀘스트입니다. 이 던전에서 마력 깃든 은 주괴는 대마법사 아루갈을 죽인 후 그의 방에 있는 테이블 위에 놓여 있습니다. 다른 부품은 흰돌참나무 재목(죽음의 폐광)와 정화된 코르석(검은심연 나락)입니다.",
    ["Paladin class quest. Needs 2 amber, 2 blue and 2 green Voodoo Feathers from the six troll guardians: Gasher, Mijan, Zolo, Hukku, Zul'Lor and Loro.\n\nOptional introductory quest:"] = "성기사 클래스 퀘스트입니다. 여섯 명의 트롤 수호자 게이셔, 마이잔, 졸로, 후쿠, 줄로 및 로로의 호박색 2개, 파란색 2개, 녹색 부두 깃털 2개가 필요합니다.\n\n선택적인 소개 퀘스트:",
    ["Pale Moon Cloak"] = "잿빛 달망토",
    ["Panic at the Digsite"] = "발굴 현장의 공황",
    ["Papal Fez"] = "교황의 페즈",
    ["Parqual Fintallas in Undercity"] = "언더시티의 파쿠알 핀탈라스",
    ["Part of Anthion Harmon's Dungeon Set 2 quests: the earlier ones unlock this step."] = "안시온 하몬 던전 세트 2 퀘스트의 일부: 이전 퀘스트는 이 단계를 잠금 해제합니다.",
    ["Part of the Horde Onyxia chain. Black Dragonspawn Eyes drop from the dragonspawn in UBRS."] = "호드 오닉시아 체인의 일부입니다. 검은용혈족 검은바위 첨탑 상층의 드래곤스폰에서 눈이 떨어집니다.",
    ["Part of the Onyxia attunement."] = "오닉시아 조율의 일부입니다.",
    ["Part of the chain that begins with The Unsent Letter from Edwin VanCleef in The Deadmines."] = "죽음의 폐광의 에드윈 밴클리프에서 부치지 않은 편지로 시작하는 체인의 일부입니다.",
