    ["Plant the banner before the normal challenger comes out. Theldren and his gladiators then fight you, and an Arena Spoils chest appears afterwards. You keep the banner (10 min cooldown) to summon him again."] = "일반 도전자가 나오기 전에 배너를 설치하세요. 텔드렌과 그의 검투사들이 당신과 싸우고, 이후 투기장 전리품 상자가 나타납니다. 배너를 유지하면(재사용 대기시간 10분) 그를 다시 소환할 수 있습니다.",
    ["Plant the explosives beside the forge, then meet Alba Fairmoon at the Deadmines exit."] = "대장간 옆에 폭발물을 설치한 후 죽음의 폐광 출구에서 알바 페어문을 만나세요.",
