    ["Read Mor'zul's Instructions. Summon a Xorothian Dreadsteed, defeat it, then bind its spirit to you."] = "모르줄의 지시서를 읽습니다. 소로시안 공포마를 소환하여 처치한 다음 그 영혼을 당신에게 결속시키세요.",
    ["Read Warosh's Scroll. Bring Warosh's Mojo to Warosh."] = "와로쉬의 두루마리를 읽습니다. 와로쉬의 모조를 와로쉬에게 가져가세요.",
