    ["Recipe: Twice-Spiced Raptor Slice"] = "조리법: 두 번 양념한 랩터 조각",
    ["Reclaimed Treasures"] = "보물 되찾기",
    ["Recover 20 Plagued Flesh Samples from Stratholme and return them to Betina Bigglezink. You suspect that any creature in Stratholme would have said flesh sample."] = "스트라솔름에서 역병에 걸린 살점 표본 20개를 회수하여 베티나 비글징크에게 가져가야 합니다. 당신은 스트라솔름에 있는 어떤 생명체라도 살점 샘플을 요구했을 것이라고 의심합니다.",
    ["Recover The Coldbringer's Eye from Razorfen Downs."] = "가시덩굴 구릉에서 콜드브링어의 눈을 복구하세요.",
    ["Recover The Founding of Dalaran and deliver it to Rexxie Copperclutch."] = "달라란의 건국을 회수해 렉시 코퍼클러치에게 전달하세요.",
    ["Recover Thistlenettle's Badge from Foreman Thistlenettle in the undead side tunnel."] = "언데드 측면 터널의 현장감독 시슬네틀에서 시슬네틀의 배지를 복구합니다.",
    ["Recover Zarla's Journal from the depths of Alcaz Prison."] = "알카즈 감옥 깊은 곳에서 자를라의 일지를 복구하세요.",
    ["Recover a Fragment of the Firelands from Blackrock Depths for Alaana Stormwalker in Mulgore."] = "멀고어의 알라나 스톰워커를 위해 검은바위 나락에서 불의 땅 조각을 복구하세요.",
    ["Recover all three gems and a power source for the necklace from Uldaman, and then bring them to Jarkal Mossmeld in Kargath. Jarkal believes a power source might be found on the strongest construct present in Uldaman."] = "울다만에게서 세 개의 보석과 목걸이의 동력원을 모두 회수한 다음 카르가스에 있는 자칼 모스멜드에게 가져가세요. 자르칼은 울다만에 있는 가장 강력한 구조물에서 동력원을 찾을 수 있을 것이라고 믿습니다.",
    ["Recover an Ancient Gurubashi Idol from the Drowned City."] = "익사한 도시에서 고대 구루바시 우상을 회수하세요.",
    ["Recover shards and fragments of the pylons, found guarded at the Magram and Gelkis villages. Return them to Mordent Evenshade."] = "마그람(마그람) 마을과 겔키스(겔키스) 마을에서 보호되고 있는 철탑의 파편과 파편을 회수하세요. 모르덴트 이븐셰이드에게 돌려주세요.",
    ["Recover the Alcaz Shackle Key from The Questioner in Alcaz Prison."] = "알카즈 감옥의 심문관에서 알카즈 족쇄 열쇠를 복구합니다.",
    ["Recover the Fathom Core from the Fathom Stone in Blackfathom Deeps."] = "검은심연 나락의 심연의 돌에서 심연의 핵을 복구합니다.",
    ["Recover the Gnoam Sprecklesprocket from Sneed's Shredder."] = "스니드의 벌목기에서 노암 톱니구동장치를 복구합니다.",
    ["Recover the Lorgalis Manuscript from Blackfathom Deeps."] = "검은심연 나락에서 로르갈리스 초본을 복구합니다.",
    ["Recover the Tome of Twilight from Krol'dok Stronghold."] = "크롤도크 보루에게서 황혼의 고서를 회수하세요.",
    ["Recover the crystal known as An'she's Radiance from Maraudon and return it to Olana Brighthoof in Mulgore."] = "마라우돈에게서 안쉬의 광채라는 수정을 회수하여 멀고어에 있는 올라나 브라이트후프에게 가져가세요.",
    ["Recover the two parts of the Scepter of Celebras: the Celebrian Rod and the Celebrian Diamond. Find a way to speak with Celebras."] = "셀레브라스의 홀의 두 부분인 셀레브리안 마법봉과 셀레브리안 다이아몬드를 복구합니다. 셀레브라스와 대화할 방법을 찾으세요.",
    ["Recruit 5 Ogre Miners."] = "오우거 광부 5명을 모집하세요.",
    ["Red Punch Card"] = "적색 천공 카드",
    ["Red Punch Card (Punchograph 3005-C)"] = "적색 천공 카드 (펀치그래프 3005-C)",
    ["Red Silk Bandanas"] = "붉은 비단 복면",
    ["Red Wool Cloak"] = "붉은 양모 망토",
    ["Redemption"] = "구원의 지팡이",
    ["Redoubt Cloak"] = "사각보루 망토",
    ["Reed-woven Heart"] = "갈대로 엮은 심장",
    ["Reed-woven Heart를 메네실 항구의 Caitlin Grassman에게 가져가세요."] = "갈대로 엮은 심장을 메네실 항구의 케이틀린 그라스만에게 가져가세요.",
    ["Reef Axe"] = "모래톱 도끼",
    ["Refractory Scaleguards"] = "내화 스케일가드",
    ["Regal Direhorn Drape"] = "제왕의 공포뿔 외투",
    ["Reginald Windsor"] = "레지널드 윈저",
    ["Reginald Windsor — Elwynn Forest"] = "레지널드 윈저 — 엘윈 숲",
    ["Reginald Windsor, Elwynn Forest"] = "레지널드 윈저, 엘윈 숲",
    ["Regurgitated Seed Pod"] = "역류된 씨앗 꼬투리",
    ["Reinforced Muck Protectors"] = "강화된 진흙 보호 장치",
    ["Reiver Claws"] = "약탈의 발톱",
    ["Rekindle"] = "다시 불붙이기",
    ["Related lead-in: Dragonmaw Rumors. The Dragonmaw Dispatch is recovered from the Dragonmaw forces inside the dungeon."] = "선행 퀘스트: 용아귀 소문. 용아귀 전갈는 던전 안의 용아귀 병력에게서 얻습니다.",
    ["Relentless Chain"] = "가혹의 사슬 갑옷",
    ["Relentless Scythe"] = "무자비의 낫",
    ["Relic Guardian"] = "유물 수호자",
    ["Relic, Idol"] = "유물, 아이돌",
    ["Relic, Libram"] = "유물, 성서",
    ["Relic, Totem"] = "유물, 토템",
    ["Reliquary Key"] = "성물함 열쇠",
    ["Reliquary Mantle"] = "성물함 어깨덧옷",
    ["Remains of a Paladin"] = "성기사의 유해",
    ["Remains of a Paladin, Uldaman"] = "성기사의 유해, 울다만",
    ["Remains of a Paladin, 울다만"] = "성기사의 유해, 울다만",
    ["Remember That I Love You"] = "내가 사랑한다는 걸 기억해",
    ["Remembrance Armor"] = "기억의 갑옷",
    ["Rend"] = "렌드",
    ["Renewing Footpads"] = "리뉴얼 풋패드",
    ["Repairman's Cape"] = "수리공의 단망토",
    ["Repeatable, after the first Blackmaw Pouches."] = "첫 번째 검은아귀 파우치 이후 반복 가능합니다.",
    ["Repeatable. Needs your faction's Elven Legends turned in first."] = "반복 가능. 먼저 소속 진영의 엘프의 전설을 제출해야 합니다.",
    ["Repeatable. The quest text sends you after the Legashi satyrs. Who gives it isn't known yet; please report it on Discord."] = "반복 가능. 퀘스트 텍스트는 레가쉬 사티로스 이후에 당신을 보냅니다. 누가 주는지는 아직 알려지지 않았습니다. 디스코드에 신고해주세요.",
    ["Report Daewyn's fate to Dorin Songblade in Lakeshire."] = "대윈의 운명을 호숫가 마을의 도린 송블레이드에게 알리세요.",
    ["Report to Krom'rosh in Rog'mar."] = "로그마르에 있는 크롬로쉬에게 보고하세요.",
    ["Report to the Image of Archmage Modera near the City of Dalaran."] = "달라란 근처의 대마법사 모데라의 환영에게 보고하세요.",
    ["Repurposed Rack"] = "재활용 선반",
    ["Required before Gnomer-gooooone!"] = "놈리건은 이제 그만 전에 필요합니다!",
    ["Required before Highland Hides. Daily Delivery is not required in Forever."] = "고지대 가죽 이전에 필요합니다. 포에버에는 가죽 배달가 필요하지 않습니다.",
    ["Required before Open the Maw."] = "아가리 열기 이전에 필요합니다.",
    ["Required before Red Silk Bandanas."] = "붉은 비단 복면 이전에 필요합니다.",
    ["Required before Smart Drinks becomes available."] = "영리해지는 음료를 사용할 수 있게 되기 전에 필요합니다.",
    ["Required before The Crone of the Kraul."] = "가시덩굴 우리의 대모 이전에 필요합니다.",
    ["Required before The Only Cure is More Green Glow."] = "유일한 치료법 이전에 필요합니다.",
    ["Requires Blacksmithing (300)"] = "대장기술 필요 (300)",
    ["Requires Level 30"] = "요구 레벨 30",
    ["Requires Level 42"] = "요구 레벨 42",
    ["Requires Level 43"] = "요구 레벨 43",
    ["Requires Level 47"] = "요구 레벨 47",
    ["Requires Level 49"] = "요구 레벨 49",
    ["Requires Level 50"] = "요구 레벨 50",
    ["Requires Level 52"] = "요구 레벨 52",
    ["Requires Level 53"] = "요구 레벨 53",
    ["Requires Level 54"] = "요구 레벨 54",
    ["Requires Level 55"] = "요구 레벨 55",
    ["Requires Level 56"] = "요구 레벨 56",
    ["Requires Level 57"] = "요구 레벨 57",
    ["Requires Level 58"] = "요구 레벨 58",
    ["Requires Magus Wordeen Voidglare's Dalaran quests. Stone Tokens and Bracers of Binding from Keeper Bel'varil are optional and are not required for attunement."] = "학자 워딘 보이드글레어의 달라란 퀘스트를 완료해야 합니다. 관리인 벨바릴의 '징표의 돌'과 '결속의 팔보호구'는 선택 퀘스트이며 입장 조건에는 포함되지 않습니다.",
    ["Requires The Dark Iron War before this quest becomes available."] = "이 퀘스트를 사용할 수 있으려면 검은무쇠단과의 전투가 필요합니다.",
    ["Requires the Barrens oasis quest chain. Complete The Barrens Oases, The Forgotten Pools, The Stagnant Oasis and Altered Beings, then Hamuul Runetotem and Nara Wildmane before Leaders of the Fang becomes available."] = "불모의 땅 오아시스 퀘스트 체인이 필요합니다. 송곳니의 드루이드 우두머리를 사용할 수 있게 되기 전에 불모의 땅 오아시스, 잊혀진 웅덩이, 죽은 오아시스 및 변화된 생물을 완료한 다음 하뮬 룬토템 및 나라 와일드메인을 완료하세요.",
    ["Requires the Defias Brotherhood escort step."] = "데피아즈단 호위 단계가 필요합니다.",
    ["Requires the earlier Hidden Enemies chain steps in Orgrimmar. The next Hidden Enemies step later offers:"] = "오그리마의 이전 내부의 배신자 체인 단계가 필요합니다. 이후의 다음 내부의 배신자 단계는 다음을 제공합니다.",
    ["Rescue 5 Farholde Scouts within the Twilight's Shroud for Sergeant Riftan."] = "하사관 리프탄을 위해 황혼의 장막 안에 있는 파홀데 정찰병 5명을 구출하세요.",
    ["Rescue 5 Rog'mar Scouts within the Twilight's Shroud for Da'grosh."] = "다그로쉬를 위해 황혼의 장막 안에 있는 로그마르 정찰병 5명을 구출하세요.",
    ["Researching the Corruption"] = "타락에 대한 연구",
    ["Resistance Breaker Spaulder"] = "저항 차단기 어깨덮개",
    ["Resplendent Guardian"] = "빛나는 수호버클러",
    ["Restorative Potion"] = "복원의 물약",
    ["Restorer's Fine Gloves"] = "복원자의 고급 장갑",
    ["Restoring the Necklace"] = "목걸이 복원",
    ["Resurgence Rod"] = "회생의 마법막대",
    ["Rethiel the Greenwarden"] = "신록의수호자 레시엘",
    ["Rethiel the Greenwarden — Wetlands"] = "신록의수호자 레시엘 — 저습지",
    ["Rethiel the Greenwarden — 저습지"] = "신록의수호자 레시엘 — 저습지",
    ["Rethiel the Greenwarden, The Green Belt, Wetlands"] = "신록의수호자 레시엘, 그린 벨트, 저습지",
    ["Rethiel the Greenwarden, The Green Belt, 저습지"] = "신록의수호자 레시엘, 그린 벨트, 저습지",
    ["Rethiel the Greenwarden, Wetlands"] = "신록의수호자 레시엘, 저습지",
    ["Rethiel the Greenwarden, 저습지"] = "신록의수호자 레시엘, 저습지",
    ["Rethilgore"] = "레실고어",
    ["Retrieve 20 Enriched Manna Biscuits - the key ingredient in making Manna-Enriched Horse Feed - for Merideth Carlson at Southshore in the Hillsbrad Foothills. The Argent Dawn is known as the sole purveyor of the biscuits. You also need to give her 50 gold to soothe her ruffled sensibilities."] = "힐스브래드 구릉지의 사우스쇼어에서 메리데스 칼슨을 위해 맛좋은 만나 사료를 만드는 핵심 재료인 농축 만나 비스킷 20개를 가져옵니다. 은빛 여명회는 비스킷의 유일한 납품업자로 알려져 있습니다. 그녀의 예민한 감정을 달래기 위해서는 그녀에게 50골드를 주어야 합니다.",
    ["Retrieve 25 Twilight Charms from Twilight Shadowmancers and Twilight Neophytes in Sunnyglade for Ashe Amberhall in Farholde Keep."] = "파홀드 성채에 있는 애쉬 앰버홀을 위해 햇살숲에 있는 황혼 암흑술사와 황혼 신도로부터 황혼의 부적 25개를 회수하세요.",
    ["Retrieve Apothecary Berard's journal from Pyrewood Village and take it to Apothecary Renferrel at the Sepulcher."] = "장작나무 마을에게서 연금술사 베랄드의 일지를 회수하여 공동묘지에 있는 연금술사 렌퍼럴에게 가져가세요.",
    ["Retrieve Mythology of the Titans from the Monastery and bring it to Librarian Mae Paledust in Ironforge."] = "수도원에서 티탄 신화를 회수하여 아이언포지에 있는 사서 메이 페일더스트에게 가져가세요.",
    ["Retrieve The Lost Magic of the Runemasters from the Scarlet Monastery."] = "붉은십자군 수도원에서 잃어버린 룬술사의 마법을 회수하세요.",
    ["Retrieve a Fel Infused Blossom from Dalaran's central garden."] = "달라란 중앙 정원에서 지옥 마력이 깃든 꽃을 구해 오세요.",
    ["Retrieve a Putrid Vine from the guardian at the bottom of the Sunken Temple and return to Torwa Pathfinder."] = "가라앉은 사원 하단의 가디언에게서 썩은 덩굴을 회수하고 토르와 패스파인더로 돌아옵니다.",
    ["Retrieve an Obsidian Power Source and bring it to Tabetha in Dustwallow Marsh."] = "흑요석 마력원천을 검색하여 먼지진흙 습지대에 있는 타베사에게 가져가세요.",
    ["Retrieve the 99-Year-Old Port from Mad Magglish in Wailing Caverns."] = "통곡의 동굴의 광기의 매글리시에서 99년 숙성된 포트 와인을 검색합니다.",
    ["Retrieve the Arcane Shard from Morphaz and return to Archmage Xylem."] = "몰파즈에서 신비의 결정을 검색하고 대마법사 실렘으로 돌아갑니다.",
    ["Retrieve the Compendium of the Fallen from the Monastery and return to Sage Truthseeker in Thunder Bluff."] = "수도원에서 타락의 개요를 회수하고 썬더 블러프에 있는 현자 트루스시커에게 돌아갑니다.",
    ["Retrieve the Fenris Isle Key from the Rot Hide Gnolls and use it to free Lumina Windsinger."] = "썩은가죽 놀에게서 펜리스 섬 열쇠를 구하여 루미나 윈드싱어를 풀어주세요.",
    ["Retrieve the Medallion of Faith from Malor the Zealous in the Scarlet Bastion and bring it back to Aurius."] = "붉은십자군 요새에 있는 광신자 말로에게서 신념의 메달을 회수하여 아우리우스에게 가져가세요.",
    ["Retrieve the Rig Blueprints and Thermaplugg's Safe Combination and bring them to Nogg in Orgrimmar."] = "장치 설계도 및 텔마플러그의 금고 암호를 회수하여 오그리마에 있는 노그에게 가져가세요.",
    ["Retrieve the Sealed Azure Bag from the Timbermaw Shaman in Azshara. Then take the bag to Archmage Xylem, also found in Azshara."] = "아즈샤라의 나무구렁일족 주술사에서 봉인된 하늘색 자루를 검색합니다. 그런 다음 아즈샤라에서도 찾을 수 있는 대마법사 실렘에게 가방을 가져가세요.",
    ["Retrieve the Stone Circle from Marvon Rivetseeker's workshop in Ratchet."] = "톱니항에 있는 마본 리벳시커의 작업장에서 돌무리를 검색하세요.",
    ["Return Marshal Windsor's Lost Information. Marshal Windsor believes that the information is being held by Golem Lord Argelmach and General Angerforge."] = "치안대장 윈저의 잃어버린 정보를 반환합니다. 치안대장 윈저는 해당 정보가 골렘 군주 아젤마크 및 사령관 앵거포지에 의해 보유되고 있다고 믿습니다.",
    ["Return Nostro's Compendium of Dragon Slaying to the Athenaeum."] = "노스트로의 용사냥 개론을 아테네움으로 돌려보내세요.",
    ["Return Vorrel Sengutz's wedding ring (from Nancy Vishas) to Monika Sengutz in Tarren Mill."] = "보렐 센구츠의 결혼 반지(낸시 비샤스에서)를 타렌 밀농장의 모니카 센구츠에 반환합니다.",
    ["Return of the Ring"] = "반지의 귀환",
    ["Return the Azure Key to Lord Jorach Ravenholdt."] = "하늘색 열쇠를 조라크 라벤홀트 경으로 반환합니다.",
    ["Return the Crest of Lordaeron to Stormwind."] = "로데론의 문장을 스톰윈드로 반환합니다.",
    ["Return the Exorcism Censer to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."] = "스톰윈드 대성당 구역에 있는 그레이슨 섀도브레이커 경에게 퇴마 향로를 돌려주세요.",
    ["Return the book to its rightful owners."] = "책을 정당한 소유자에게 돌려주십시오.",
    ["Return to Alba Fairmoon at the Sentinel Hill inn in Westfall with the completed explosives."] = "완성된 폭발물을 가지고 서부 몰락지대의 감시의 언덕 여관에 있는 알바 페어문에게 돌아가세요.",
    ["Return to Ashe Amberhall in Farholde Keep."] = "파홀드 성채에 있는 애쉬 앰버홀로 돌아갑니다.",
    ["Return to Blackrock Depths and rescue Princess Moira Bronzebeard from the evil clutches of Emperor Dagran Thaurissan."] = "검은바위 나락으로 돌아가 제왕 다그란 타우릿산의 사악한 손아귀에서 공주 모이라 브론즈비어드를 구출하세요.",
    ["Return to Fel'Zerul"] = "펠제룰에게 돌아가기",
    ["Return to Fel'Zerul in Stonard."] = "펠제룰에게 돌아가기.",
    ["Return to Ironforge and deliver the bad news to King Magni Bronzebeard."] = "아이언포지로의 귀환을 보고 나쁜 소식을 국왕 마그니 브론즈비어드에게 전달하세요.",
    ["Return to Magistrate Marduke in Caer Darrow. Show him the Soulbound Keepsake."] = "카엘 다로우에 있는 집정관 마르듀크에게 돌아가세요. 그에게 영혼이 씌인 유품을 보여주세요.",
    ["Return to Nathanos Blightcaller."] = "나타노스 블라이트콜러에게 돌아가세요.",
    ["Return to Sully McCleary in Dustwallow Marsh."] = "먼지진흙 습지대의 설리 맥클리어리로 돌아갑니다.",
    ["Return to Tinkee"] = "팅키에게 돌아가는 길",
    ["Return to the Scholomance with the Blood of Innocents. Find the porch and place the Blood of Innocents in the brazier. Kirtonos will come to feast upon your soul. Fight valiantly, do not give an inch! Destroy Kirtonos and return to Eva Sarkhoff."] = "순결한 피를 타고 스칼로맨스로 돌아가세요. 현관을 찾아 순결한 피를 화로에 넣으세요. 키르토노스는 당신의 영혼을 먹어치우러 올 것입니다. 용감하게 싸우십시오. 한 치도 양보하지 마십시오! 키르토노스를 파괴하고 에바 사크호프로 돌아가세요.",
    ["Return with the Blessed Arcanite Barding to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."] = "스톰윈드 대성당 지구에 있는 축복받은 아케이나이트 마갑을 가지고 그레이슨 섀도브레이커 경으로 돌아갑니다.",
    ["Returning the Lost Satchel"] = "잃어버린 가방 돌려주기",
    ["Returns Shaw's findings about Edwin VanCleef to Gryan."] = "에드윈 밴클리프에 대한 쇼의 조사 결과를 그라이언에게 반환합니다.",
    ["Returns the remote detonator to the engineer."] = "원격 기폭 장치를 엔지니어에게 반환합니다.",
