    ["Reward from the quest Bailor's Ore Shipment: Bailor Stonehand, Thelsamar, Loch Modan"] = "퀘스트 조던의 광석 상자 보상: 베일러 스톤핸드, 텔사마, 모단 호수",
    ["Reward from the quest Seeking the Kor Gem: Thundris Windweaver, Auberdine, Darkshore. The Corrupted Kor Gem he asks for drops from Blackfathom Tide Priestesses and Oracles at the Blackfathom Deeps entrance and from Blackfathom Sea Witches inside."] = "퀘스트 코르석을 찾아서 보상: 툰드리스 윈드위버, 아우버다인, 어둠의 해안. 필요한 부정한 코르석은 검은심연 나락 입구의 검은심연의 바다여사제와 예언자, 내부의 검은심연의 바다마녀가 드롭합니다.",
    ["Reward from the quest Seeking the Kor Gem: Ulric Frostveil, Zoram'gar Outpost, Ashenvale. The Corrupted Kor Gem he asks for drops from Blackfathom Tide Priestesses and Oracles at the Blackfathom Deeps entrance and from Blackfathom Sea Witches inside, once you have his quest."] = "코르석을 찾아서 퀘스트 보상: 울릭 프로스트베일, 조람가르 전초기지, 잿빛 골짜기. 부정한 코르석 그는 일단 퀘스트를 완료하면 검은심연 나락 입구에 있는 검은심연 여사제 및 예언자와 내부의 검은심연 바다마녀로부터 드롭을 요청합니다.",
