    ["Rogue class book. Click the book to start the quest."] = "도적 직업 책입니다. 책을 클릭하면 퀘스트가 시작됩니다.",
    ["Rogue class quest after The Horn of Xelthos; C's next letter (around level 30) sends you back to the Dead Drop. Wear the Scarlet Initiate's Uniform in every wing: stealth or attacking removes it."] = "'젤토스의 뿔' 이후 이어지는 도적 직업 퀘스트입니다. 약 30레벨에 도착하는 C의 다음 편지를 읽고 비밀 접선 지점으로 돌아가세요. 모든 구역에서 붉은십자군 신도 제복을 착용해야 하며, 은신하거나 공격하면 변장이 해제됩니다.",
    ["Rogue class quest. C's letter arrives at level 20 in a capital city; take the job at the Dead Drop near Pyrewood Village. Keep a bag slot free."] = "도적 클래스 퀘스트. C의 편지는 수도의 레벨 20에 도착합니다. 장작나무 마를 근처의 비밀 접선 지점에서 일을 구하세요. 가방 수납칸을 비워두세요.",
    ["Rogue class quest. The Azure Key drops from Morphaz.\n\nOptional introductory quest:"] = "도적 클래스 퀘스트. 하늘색 열쇠는 몰파즈에서 드랍됩니다.\n\n선택적인 소개 퀘스트:",
