    ["Search Dire Maul for Kariel Winthalus. Report back to Scholar Runethorn at Feathermoon with whatever information that you may find."] = "카리엘 윈탈루스를 위해 혈투의 전장을 검색하세요. 발견한 정보를 가지고 페더문에 있는 학자 룬쏜에게 다시 보고하세요.",
    ["Search for clues as to the current disposition of Talvash's necklace within Uldaman. The slain paladin he mentioned was the person who has it last."] = "울다만 내에서 탈바쉬의 목걸이의 현재 처분에 대한 단서를 검색하세요. 그가 언급한 살해된 성기사는 그것을 마지막으로 갖고 있는 사람이었습니다.",
    ["Search for the original creator of the shattered necklace to learn of its potential value."] = "부서진 목걸이의 원래 제작자를 찾아 그 잠재적 가치를 알아보세요.",
