    ["Seek out Rexxar. The Warchief has instructed you as to his whereabouts. Search the paths of Desolace, between the Stonetalon Mountains and Feralas."] = "렉사르를 찾아보세요. 대족장이 당신에게 그의 행방을 알려 주었습니다. 돌발톱 산맥과 페랄라스 사이에서 잊혀진 땅의 경로를 검색합니다.",
    ["Seek out Rhapsody Shindigger in The Hinterlands."] = "동부 내륙지에서 랩소디 신디거를 찾아보세요.",
    ["Seek out Sanath Lim-yo and gain passage to see Archmage Xylem."] = "사나스 림요를 찾아 대마법사 실렘을 볼 수 있는 통로를 확보하세요.",
