    ["Shadowshard elementals in the outer purple-crystal caves. It can be done without entering the instance."] = "외부 보라색 수정 동굴에 있는 그림자조각 정령들. 인스턴스에 들어가지 않고도 가능합니다.",
    ["Shadowsworn"] = "어둠의혈맹",
    ["Shadowy Laced Handwraps"] = "어둠매듭 장갑",
