    ["Shady Saltseers"] = "수상한 소금예언자들",
    ["Shaggy Leggings"] = "수풀나무 다리보호구",
    ["Shalehusk Boots"] = "혈암깍지 장화",
    ["Shaman class book. Click the book to start the quest."] = "주술사 직업 책입니다. 책을 클릭하면 퀘스트가 시작됩니다.",
    ["Shaman class quest from level 30, unlocked by Call of Air (the Air Totem quest). In this dungeon: Elemental Aid. Kill Charlga Razorflank and loot the Tattered Note; every Shaman on the quest gets one. After that: 20 Twisted Totems from four zones and the elite Heed My Call ritual in Thousand Needles."] = "레벨 30의 주술사 클래스 퀘스트, 바람의 부름(바람의 토템 퀘스트)로 잠금 해제됩니다. 이 던전에서는: 정령의 도움. 서슬깃 차를가를 처치하고 너덜너덜한 쪽지를 약탈하세요. 퀘스트를 수행하는 모든 주술사는 하나를 얻습니다. 그 후: 4개 구역의 뒤틀린 토템 20개 및 버섯구름 봉우리의 엘리트 내 부름에 응답 의식.",
    ["Shaman class quest from level 30, unlocked by Call of Air (the Air Totem quest). In this dungeon: Elemental Aid. Kill Charlga Razorflank and loot the Tattered Note; every Shaman on the quest gets one. After that: 20 Twisted Totems from four zones and the elite Heed My Call ritual in Thousand Needles. Horde quest givers after the dungeon aren't confirmed yet (Prate Cloudseer or Rau Cliffrunner): follow your quest log."] = "'바람의 부름'을 마친 30레벨 주술사가 진행하는 직업 퀘스트입니다. 이 던전에서는 '정령의 도움'을 수행합니다. 서슬깃 차를가를 처치하면 퀘스트 중인 모든 주술사가 너덜너덜한 쪽지를 획득합니다. 이후 네 지역에서 뒤틀린 토템 20개를 모으고 버섯구름 봉우리에서 정예 퀘스트 '나의 부름에 응하라' 의식을 진행합니다. 던전 이후 호드 퀘스트 제공자가 프레이트 클라우드시어인지 라우 클리프러너인지는 아직 확인되지 않았으므로 퀘스트 목록의 안내를 따르세요.",
    ["Shaman class quest. Needs 2 amber, 2 blue and 2 green Voodoo Feathers from the six troll guardians: Gasher, Mijan, Zolo, Hukku, Zul'Lor and Loro."] = "주술사 클래스 퀘스트입니다. 여섯 명의 트롤 수호자 게이셔, 마이잔, 졸로, 후쿠, 줄로 및 로로의 호박색 2개, 파란색 2개, 녹색 부두 깃털 2개가 필요합니다.",
    ["Shaman quest Elemental Aid"] = "주술사 퀘스트 원소의 원조",
    ["Shaman quest. Clear Rattlegore's basement, use the scryer and defeat Death Knight Darkreaver; return his head."] = "주술사 퀘스트입니다. 들창어금니의 지하실을 정리하고 점술어를 사용해 죽음의 기사 다크리버를 처치하세요. 그의 머리를 돌려주세요.",
