    ["Show Cyrus a Black Dragonflight Molt first (A Taste of Flame, or kill the drake he summons). Then kill Bael'Gar and use the Altered Black Dragonflight Molt on his remains to collect the Encased Fiery Essence."] = "사이러스에게 검은용군단 허물을 먼저 보여주세요(화염의 맛 또는 그가 소환한 드레이크를 죽이세요). 그런 다음 밸가르를 처치하고 그의 유해에 변형된 검은용군단 허물을 사용하여 담겨진 불의 정수를 수집하세요.",
    ["Show Them How It's Done"] = "본때를 보여줘라",
