    ["Slain Baron's Signet"] = "살해당한 남작의 인장",
    ["Slamshot Shoulders"] = "돌진의 어깨보호대",
    ["Slashclaw Bracers"] = "칼날발톱 팔보호구",
    ["Slaughter the Shadowsworn in the Blasted Lands and return to the Fallen Hero of the Horde."] = "저주받은 땅에서 어둠의혈맹을 학살하고 호드 영웅의 넋으로 돌아가세요.",
    ["Slavecrusher Grox"] = "노예분쇄자 그록스",
    ["Slavecrusher Scepter"] = "노예분쇄자 홀",
    ["Slavedriver's Cane"] = "노예감독의 지팡이",
    ["Slavering Hound / Strashaz Soldier / Alcaz Jailer"] = "침 흘리는 사냥개 / 스트라샤즈 병사 / 알카즈 간수",
    ["Slay 15 Black Broodlings, 10 Black Dragonspawn, 4 Black Wyrmkin and 1 Black Drake. Return to Helendis Riverhorn when the task is complete."] = "검은 공생충 15마리, 검은용혈족 10마리, 검은고룡족 4마리, 검은 비룡 1마리를 처치하세요. 작업이 완료되면 헬렌디스 리버혼으로 돌아갑니다.",
    ["Slay 20 Noxious Plaguebats and 10 Monstrous Plaguebats. Return to Nathanos Blightcaller when you are finished."] = "유독한 역병박쥐 20마리와 괴물같은 역병박쥐 10마리를 처치하세요. 완료되면 나타노스에게 돌아가기 블라이트콜러입니다.",
    ["Slay 20 Plaguehound Runts, 5 Plaguehounds and 5 Frenzied Plaguehounds. Return to Tirion Fordring when the task is complete."] = "꼬마 역병사냥개 20마리, 역병사냥개 5마리, 광포한 역병사냥개 5마리를 처치하세요. 작업이 완료되면 티리온 폴드링으로 돌아갑니다.",
    ["Slay 30 Plaguebats and return to Tirion Fordring."] = "역병박쥐 30마리를 처치하고 티리온 폴드링에게 돌아가세요.",
    ["Slay 4 Kobold Diggers in Jangolode Mine and 6 Riverpaw Miners in Gold Coast Quarry."] = "장고로데 광산에서 코볼트 굴착기 4명을 처치하고 골드 코스트 채석장에서 리버포우 광부 6명을 처치하세요.",
    ["Slay 8 Farholde Priests and 12 Farholde Scouts south of the river."] = "강 남쪽에서 파홀데 사제 8명과 파홀데 정찰병 12명을 처치해야 합니다.",
    ["Slay Agmond's killer, Murdaloc. Slay 12 Stonevault Bonesnappers. Report to Prospector Ironband in Loch Modan."] = "아그몬드의 살인자 머달록을 처치하세요. 바위동굴 뼈다귀망치일족 12마리를 처치해야 합니다. 모단 호수에 있는 발굴조사단장 아이언밴드에게 보고하세요.",
    ["Slay Arcanic Enigma, the Mana Elemental in the City of Dalaran, and return to High Sorcerer Andromath in Stormwind City."] = "달라란의 마나 정령 신비한 수수께끼를 처치하고 스톰윈드의 고위마술사 안드로매스에게 돌아가세요.",
    ["Slay Captain Dreadrise and 3 Saltseer Coroners in the Drowned City."] = "익사한 도시에서 선장 드레드라이즈와 소금 예견자 검시관 3명을 처치하세요.",
    ["Slay Emperor Dagran Thaurissan and free Princess Moira Bronzebeard from his evil spell."] = "제왕 다그란 타우릿산을 처치하고 그의 사악한 주문으로부터 공주 모이라 브론즈비어드를 구출하세요.",
    ["Slay Fineous Darkvire and recover the great hammer, Ironfel. Take Ironfel to the Shrine of Thaurissan and place it on the statue of Franclorn Forgewright."] = "파이너스 다크바이어를 처치하고 거대한 망치인 아이언펠을 되찾으세요. 무쇠지옥을 타우릿산의 제단으로 가져가서 프랑클론 포지라이트의 조각상 위에 올려놓으세요.",
    ["Slay Halycon, pack mistress of the Bloodaxe worg."] = "피도끼 검은늑대 무리를 이끄는 할리콘을 처치하세요.",
    ["Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished."] = "대군주 오모크, 대장군 부네, 대군주 웜타라크를 처치하세요. 중요한 검은바위 문서를 복구하세요. 임무가 완료되면 카르가스에 있는 장군 고어투스에게 돌아가세요.",
    ["Slay Highlord Omokk, 대장군 부네, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished."] = "대군주 오모크, 대장군 부네, 대군주 웜타라크를 처치하세요. 중요한 검은바위 문서를 복구하세요. 임무가 완료되면 카르가스에 있는 장군 고어투스에게 돌아가세요.",
    ["Slay Overmaster Pyron and return to Jalinda Sprig. You recall Jalinda talking about Pyron guarding the quarry. Perhaps you should search there?"] = "멸망의 파이론을 처치하고 잘린다 스프리그에게 돌아갑니다. 당신은 잘린다가 채석장을 지키는 파이론에 대해 이야기했던 것을 기억합니다. 아마도 거기에서 검색해야할까요?",
    ["Slay Princess Theradras and return to Keeper Marandis at Nijel's Point in Desolace."] = "공주 테라드라스를 처치하고 잊혀진 땅의 나이젤의 야영지에 있는 수호자 마란디스에게 돌아갑니다.",
    ["Slay Princess Theradras and return to Selendra near Shadowprey Village in Desolace."] = "공주 테라드라스를 처치하고 잊혀진 땅에 있는 그늘수렵 마를 근처의 셀렌드라에게 돌아가세요.",
    ["Slay Taragaman the Hungerer and recover Taragaman the Hungerer's Heart."] = "욕망의 타라가만을 처치하고 타라가만의 심장을 복구하세요.",
    ["Slay Venomridge, 6 Ravasaur Matriarchs and 8 Ironhide Ravasaurs in Shaper's Terrace."] = "구체자의 정원에서 맹독등, 라바사우루스 대모 6마리, 무쇠가죽 라바사우루스 8마리를 처치하세요.",
    ["Slay Witch Doctor Zum'rah and bring Zum'rah's Head to Archmage Lan'dalock in Dalaran."] = "의술사 줌라를 처치하고 달라란에 있는 대마법사 랜달록에게 줌라의 머리를 가져가세요.",
    ["Slay Witch Doctor Zum'rah and bring Zum'rah's Head to Mazu'kon in Mulgore."] = "의술사 줌라를 처치하고 멀고어에 있는 마주콘에게 줌라의 머리를 가져가세요.",
    ["Slaying the Beast"] = "야수 처단",
