    ["Small Sack of Gems\n9,750 XP"] = "소형 보석 주머니\n9,750경험치",
    ["Small Scroll"] = "작은 두루마리",
    ["Small Scroll, dropped by Charlga Razorflank"] = "작은 두루마리, 서슬깃 차를가가 떨어뜨림",
    ["Smart Drinks"] = "영리해지는 음료",
    ["Smelted from Iron Ore: mining, trade or the auction house (12 needed)"] = "철 광석에서 제련됨: 채광, 무역 또는 경매장(12개 필요)",
    ["Smelted from Silver Ore: mining, trade or the auction house (5 needed)"] = "은 광석에서 제련됨: 채굴, 무역 또는 경매장(5개 필요)",
    ["Smelting Pants"] = "제련용 바지",
    ["Smite's Mighty Hammer"] = "스마이트의 거대한 해머",
    ["Smite's Reaver"] = "스마이트의 약탈도끼",
    ["Smokey LaRue"] = "스모키 라루",
    ["Smokey LaRue — Eastern Plaguelands"] = "스모키 라루 — 동부 역병지대",
    ["Smokey LaRue, Light's Hope Chapel, Eastern Plaguelands"] = "스모키 라루, 희망의 빛 예배당, 동부 역병지대",
    ["Smokey's Lighter"] = "스모키의 라이터",
    ["Smoky Iron Ingot"] = "연기나는 철제 주괴",
    ["Smoldering Claw"] = "이글거리는 발톱",
    ["Smolderthorn"] = "가시불꽃",
    ["Smolderthorn troll leader in Mok'Doom. Drops the Gemstone of Smolderthorn."] = "모크둠에 있는 가시불꽃 트롤 우두머리입니다. 가시불꽃부족 보석을 획득할 수 있습니다.",
    ["Smolderthorn troll shadow hunter on the way to Voone."] = "부네로 가는 길에 가시불꽃 트롤 그림자 사냥꾼이 있습니다.",
    ["Smolderweb Carrier"] = "불그물거미 알주머니",
    ["Smolderweb's Eye"] = "불그물거미 눈",
    ["Snake Eye Kaleidoscope"] = "뱀눈 만화경",
    ["Snake Hoop"] = "뱀고리",
    ["Snakeskin Bag"] = "뱀가죽 자루",
    ["Sneed"] = "스니드",
    ["Sneed's Shredder"] = "스니드의 벌목기",
    ["Snowtalon"] = "눈갈퀴",
    ["Solid Shortblade"] = "튼튼한 쇼트소드",
    ["Solo job: you must do it alone, outside any group."] = "솔로 직업: 그룹 밖에서는 반드시 혼자 해야 합니다.",
    ["Solution to Doom"] = "멸망의 해결책",
    ["Somber News"] = "침통한 소식",
    ["Someone has broken into the royal dwarven burial chamber beneath Ironforge."] = "아이언포지 아래에 있는 왕족 드워프 묘실에 누군가가 침입했습니다.",
    ["Songbird Blouse"] = "꾀꼬리 블라우스",
    ["Songblade Stabilizer"] = "송블레이드 안정기",
    ["Songstone of Ironforge"] = "아이언포지의 노랫돌",
    ["Soot Encrusted Footwear"] = "검게 그을린 신발",
    ["Soothsayer's Headdress"] = "예언자의 머리장식",
    ["Sorcerer Collar"] = "마술사 목줄",
    ["Soul Breaker"] = "영혼의 파괴자",
    ["Soul Harvester"] = "영혼 수확기",
    ["Soulbound Keepsake"] = "영혼이 씌인 유품",
    ["Soulstealer Mantle"] = "영혼강탈자 어깨보호대",
    ["South Seas Shroud"] = "남해 덮개",
    ["Southern"] = "남쪽",
    ["Southern Azshara (giver not known yet)"] = "남쪽 아즈샤라 (제공자 아직 알려지지 않음)",
    ["Southern Barrens, at the end of the thorny corridor"] = "가시나무 복도 끝에 있는 남부 불모의 땅",
    ["Southshore"] = "사우스쇼어",
    ["Southwind Village"] = "마파람 마을",
    ["Sovik — Valley of Honor, Orgrimmar"] = "소빅 — 명예의 계곡, 오그리마",
    ["Sovik — Valley of Honor, 오그리마"] = "소빅 — 명예의 계곡, 오그리마",
    ["Sovik, Valley of Honor, Orgrimmar"] = "소빅, 명예의 계곡, 오그리마",
    ["Sovik, Valley of Honor, 오그리마"] = "소빅, 명예의 계곡, 오그리마",
    ["Spare Part Bindings"] = "예비 부품 바인딩",
    ["Sparklance Wand"] = "불꽃창 지팡이",
    ["Sparklematic"] = "빤질빤질세척기",
    ["Sparklematic-Wrapped Box"] = "삐까뻔쩍세척기 포장 상자",
    ["Spaulders of Valor"] = "용맹의 어깨갑옷",
    ["Spaulders of a Lost Age"] = "잃어버린 시대의 어깨갑옷",
    ["Speak to Commander Ashlam Valorfist at Chillwind Point."] = "서리바람 거점으로에서 사령관 아쉬람 발러피스트와 대화하세요.",
    ["Speak to Dorn Plainstalker in Thousand Needles."] = "버섯구름 봉우리의 도른 플레인스토커와 대화하세요.",
    ["Speak to Duthorian Rall in Stormwind."] = "스톰윈드에 있는 두소리안 랄과 대화하세요.",
    ["Speak to Franclorn's ghost while dead. Kill Fineous Darkvire for Ironfel and place it on Franclorn's monument by the Ring of Law. The Shadowforge Key opens shortcuts inside BRD."] = "죽은 상태에서 프랑클론의 유령과 대화하세요. 무쇠지옥을 위해 파이너스 다크바이어를 처치하고 법의 반지 옆에 있는 프랑클론의 기념비에 놓으십시오. 어둠괴철로단 열쇠는 검은바위 나락 내부의 바로가기를 엽니다.",
    ["Speak to Historian Karnik."] = "역사학자 카르닉과 대화하세요.",
    ["Speak to Je'neu Sancrea in Ashenvale."] = "잿빛 골짜기에 있는 제네우 생크리와 대화하세요.",
    ["Speak to Jordan Stilwell in Ironforge."] = "아이언포지에 있는 조던 스틸웰과 대화하세요.",
    ["Speak to Ogtinc in Azshara."] = "아즈샤라에 있는 오그틴크와 대화하세요.",
    ["Speak with Brother Anton in Desolace."] = "잊혀진 땅에 있는 수사 안톤과 대화하세요.",
    ["Speak with Deathguard Baldren about the mysterious Earthen Ring travelers who recently passed through The Sepulcher."] = "죽음경비병 발드렌과 최근 공동묘지를 지나간 수상한 대지 고리회 여행자들에 관해 대화하세요.",
    ["Speak with Eitrigg in Orgrimmar. When you have discussed matters with Eitrigg, seek council from Thrall. You recall having seen Eitrigg in Thrall's chamber."] = "오그리마에 있는 아이트리그와 대화하세요. 아이트리그와 문제를 논의한 후 스랄에게 조언을 구하십시오. 당신은 스랄의 방에서 아이트리그를 본 것을 기억합니다.",
    ["Speak with Franclorn Forgewright if you are interested in obtaining a key to the city major."] = "도시 주요 열쇠를 얻고 싶다면 프랑클론 포지라이트와 대화하세요.",
    ["Speak with Grimand Elmore in Stormwind's Dwarven District."] = "스톰윈드의 드워프 지구에서 그리만트 엘모어와 대화하세요.",
    ["Speak with Gryphon Master Talonaxe inside the Aerie Peak Aviary."] = "맹금의 봉우리 새장에서 그리핀 조련사 탈론액스와 대화하세요.",
    ["Speak with Hamuul Runetotem on Elder Rise in Thunder Bluff."] = "썬더 블러프의 원로의 언덕에서 하뮬 룬토템과 대화하세요.",
    ["Speak with High Thane Falstad Wildhammer at Aerie Peak in the Hinterlands."] = "동부 내륙지의 맹금봉우리에 있는 대영주 폴스타트 와일드해머와 대화하세요.",
    ["Speak with Highlord Bolvar Fordragon after speaking with Lady Katrana Prestor."] = "여군주 카트라나 프레스톨과 대화한 후 대영주 볼바르 폴드라곤과 대화하세요.",
    ["Speak with Jaron Stoneshaper in Starfall Village."] = "별똥별 마을에 있는 야론 스톤셰이퍼와 대화하세요.",
    ["Speak with Kharan Mighthammer and gather information about Princess Moira Bronzebeard's kidnapping. Take that information to Thrall in Orgrimmar. You recall Gor'shak mentioning that Kharan is being held in a cell nearby."] = "카란 마이트해머와 대화하여 공주 모이라 브론즈비어드의 납치에 대한 정보를 수집하세요. 해당 정보를 오그리마에 있는 스랄에게 가져가세요. 고르샤크가 카란이 근처 감방에 갇혀 있다고 언급한 것을 기억하시나요?",
    ["Speak with Latronicus Moonspear at the Feathermoon Stronghold in Feralas."] = "페랄라스의 페더문 요새에 있는 라트로니쿠스 문스피어와 대화하세요.",
    ["Speak with Lord Jorach Ravenholdt in Ravenholdt Manor."] = "라벤홀트 저택에 있는 조라크 라벤홀트 경과 대화하세요.",
    ["Speak with Lumina Windsinger in the Sepulcher."] = "무덤에 있는 루미나 윈드싱어와 대화하세요.",
    ["Speak with Magus Tirth in the Shimmering Flats."] = "소금 평원에 있는 학자 틸스와 대화하세요.",
    ["Speak with Marshal Maxwell in the Burning Steppes."] = "불타는 평원에 있는 치안대장 맥스웰과 대화하세요.",
    ["Speak with Master Gadrin in Sen'jin Village."] = "센진 마을에 있는 장으로 가드린과 대화하세요.",
    ["Speak with Mathrengyl Bearwalker in the Cenarion Enclave in Darnassus."] = "다르나서스의 세나리온 거주지에 있는 마스렌길 베어워커와 대화하세요.",
    ["Speak with Mayara Brightwing in the Burning Steppes."] = "불타는 평원에 있는 마야라 브라이트윙과 대화하세요.",
    ["Speak with Mordent Evenshade in Shen'dralas for information about the crystals you repaired."] = "셴드랄라스에 있는 모르덴트 이븐셰이드와 대화하여 수리한 수정에 대한 정보를 알아보세요.",
    ["Speak with Nara Wildmane in Thunder Bluff."] = "썬더 블러프에 있는 나라 와일드메인과 대화하세요.",
    ["Speak with Nara Wildmane on Elder Rise in Thunder Bluff."] = "썬더 블러프의 원로의 언덕에서 나라 와일드메인과 대화하세요.",
    ["Speak with Nathanos Blightcaller in the Eastern Plaguelands. He is said to have taken up residence at the Marris Stead."] = "동부 역병지대에서 나타노스 블라이트콜러와 대화하세요. 그는 메리스 농장에 거주했다고합니다.",
    ["Speak with Nazeer Bloodspike in Brackenwall Village."] = "담쟁이 마을에 있는 나지르 블러드스파이크와 대화하세요.",
    ["Speak with Neeru Fireblade in the Cleft of Shadow, then return to Thrall."] = "어둠의 틈에서 네루 파이어블레이드와 대화한 후 스랄에게 돌아갑니다.",
    ["Speak with Ott and ask him to forge your blade."] = "오트와 대화하여 칼날을 제작해 달라고 부탁하세요.",
    ["Speak with Prate Cloudseer in Thousand Needles."] = "버섯구름 봉우리에 있는 프레이트 클라우드시어와 대화하세요.",
    ["Speak with Prospector Ironband at Ironband's Excavation Site in Loch Modan."] = "모단 호수의 아이언밴드의 발굴 현장 현장에서 발굴조사단장 아이언밴드와 대화하세요.",
    ["Speak with Ragged John to learn of Marshal Windsor's fate and return to Marshal Maxwell when you have completed this task. You recall Marshal Maxwell telling you to search for him in a cave to the north."] = "털보 존과 대화하여 치안대장 윈저의 운명에 대해 알아보고 이 작업을 완료하면 치안대장 맥스웰로 돌아갑니다. 치안대장 맥스웰가 북쪽 동굴에서 그를 찾으라고 말한 것을 기억합니다.",
    ["Speak with Ragnar Thunderbrew."] = "라그나르 썬더브루와 대화하세요.",
    ["Speak with Scooty in Booty Bay."] = "무법항에 있는 스쿠티와 대화하세요.",
    ["Speak with Sergeant Ulka to learn more about the situation on Alcaz Isle."] = "하사관 울카와 대화하여 알카즈 섬의 상황에 대해 자세히 알아보세요.",
    ["Speak with Shadowmage Vivian Lagrave in Kargath."] = "카르가스에 있는 어둠마법사 비비안 라그레이브와 대화하세요.",
    ["Speak with Shadowmage Vivian Lagrave."] = "어둠마법사 비비안 라그레이브와 대화하세요.",
    ["Speak with Shoni the Shilent in Stormwind."] = "쇼니와의 대화 스톰윈드의 샤일런트.",
    ["Speak with Sputtervalve in Ratchet about the Glowing Shard, then deliver it to Falla Sagewind on top of the mountain above Wailing Caverns."] = "톱니항에 있는 스퍼터밸브와 빛나는 조각에 대해 대화한 다음 통곡의 동굴 위 산 꼭대기에 있는 팔라 세이지윈드에게 전달하세요.",
    ["Speak with Tabetha in Dustwallow Marsh."] = "먼지진흙 습지대에 있는 타베사와 대화하세요.",
    ["Speak with Talo Thornhoof at Camp Mojache in Feralas."] = "페랄라스의 모자케 야영지에서 탈로 쏜후프와 대화하세요.",
    ["Speak with Thrall if you are prepared to take on the mission he has planned."] = "스랄이 계획한 임무를 수행할 준비가 되었으면 스랄과 대화하세요.",
    ["Speak with Thun'grim"] = "툰그림과의 대화",
    ["Speak with Thun'grim Firegaze in the Barrens."] = "툰그림과의 대화 불모의 땅에 있는 파이어게이즈입니다.",
    ["Speak with Tinkee Steamboil."] = "팅키 스팀보일과 대화하세요.",
    ["Speak with Torwa Pathfinder in Un'Goro Crater."] = "운고로 분화구에서 토르와 패스파인더와 대화하세요.",
    ["Speak with Tran'rek in Gadgetzan."] = "가젯잔에 있는 트란렉과 대화하세요.",
    ["Speak with Trevan Rol in the Sepulcher and bring him the materials he requires."] = "공동묘지에 있는 트레반 롤과 대화하고 필요한 재료를 가져오세요.",
    ["Speak with Warden Thelwater outside The Stockade."] = "스톰윈드 지하감옥 밖에서 교도소장 델워터와 대화하세요.",
    ["Speak with Wizzle Brassbolts in the Shimmering Flats."] = "소금 평원에서 위즐 브라스볼츠와 대화하세요.",
    ["Speak with Yuka Screwspigot in the Burning Steppes."] = "불타는 평원에 있는 유카 스크류스피곳과 대화하세요.",
    ["Speak with stone watcher and learn what ancient lore it keeps. Once you have learned what lore it has to offer, activate the Discs of Norgannon."] = "돌감시자와 대화하여 그것이 간직하고 있는 고대 전설이 무엇인지 알아보세요. 그것이 제공하는 지식이 무엇인지 알게 되면 노르간논의 디스크를 활성화하십시오.",
    ["Speak with the Fallen Hero of the Horde at the entrance to the Blasted Lands."] = "저주받은 땅 입구에 있는 호드 영웅의 넋과 대화하세요.",
    ["Speak with the Stone Watcher and activate the discs first. Then hand the reward voucher to Bena Winterhoof in Thunder Bluff and choose your reward."] = "바위 감시자와 대화하고 먼저 디스크를 활성화하세요. 그런 다음 썬더 블러프에 있는 베나 윈터후프에게 보상 바우처를 건네주고 보상을 선택하세요.",
    ["Speak with the Stone Watcher and activate the discs first. Then hand the reward voucher to Dinita Stonemantle in the Ironforge vault and choose your reward."] = "바위 감시자와 대화하고 먼저 디스크를 활성화하세요. 그런 다음 아이언포지 금고에 있는 디니타 스톤맨틀에게 보상 바우처를 건네주고 보상을 선택하세요.",
