    ["Summon a Twilight's Thrall from a conduit within the Twilight's Shroud and capture it with Amberhall's Soulstone."] = "황혼의 장막 내부의 도관에서 황혼의 노예를 소환하고 호박홀의 영혼석으로 포획하세요.",
    ["Summoned at his pike with Warosh's quest items, along with waves of ogres."] = "오우거의 파도와 함께 와로쉬의 퀘스트 아이템을 가지고 그의 파이크에 소환되었습니다.",
    ["Summoned at the Gong of Zul'Farrak with the Mallet of Zul'Farrak. Drops the Electrified Scale for Gahz'rilla."] = "줄파락의 나무망치로 줄파락 징에서 소환됩니다. 가즈릴라의 전기 비늘을 떨어뜨립니다.",
    ["Summoned at the central altar with the Filled Egg of Hakkar (The God Hakkar)."] = "충만한 학카르의 알(학카르의 화신)로 중앙 제단에 소환됩니다.",
    ["Summoned by opening the three mailboxes with the Key to the City."] = "도시로 통하는 열쇠로 우편함 3개를 열어 소환합니다.",
    ["Summoned by warlocks in the pentagram near Immol'thar (Dreadsteed of Xoroth)."] = "이몰타르(소로스의 공포마) 근처 오각형의 흑마법사에 의해 소환됩니다.",
    ["Summoned in the statue circle on the upper level (Secret of the Circle)."] = "상층의 조각상 원형(돌무리의 비밀)에서 소환됩니다.",
    ["Summoned on the porch with the Blood of Innocents (Kirtonos the Herald)."] = "순결한 피(사자 키르토노스)로 현관에 소환됩니다.",
    ["Summoned with the Brazier of Beckoning from the Dungeon Set 2 quests."] = "던전 세트 2 퀘스트에서 부름의 화로로 소환됩니다.",
    ["Summoners' Tomb: talk to Doom'rel and defeat the seven dwarf spirits one after another. Loot is in the Chest of The Seven."] = "소환사의 무덤: 운명의 문지기와 대화하여 일곱 난쟁이 영혼을 차례로 처치하세요. 전리품은 일곱 현자의 궤짝에 있습니다.",
