    ["Sutara Plainstalker"] = "수타라 평원추적자",
    ["Sutara Plainstalker of the Earthen Ring, north-west Mulgore"] = "대지 고리회의 수타라 평원추적자, 북서쪽 멀고어",
    ["Sutara Plainstalker — Mulgore"] = "수타라 평원추적자 — 멀고어",
    ["Sutara Plainstalker — 멀고어"] = "수타라 평원추적자 — 멀고어",
    ["Sutara Plainstalker, Skywatcher Plateau, Mulgore"] = "수타라 평원추적자, 스카이워처 고원, 멀고어",
    ["Sutara Plainstalker, Skywatcher Plateau, 멀고어"] = "수타라 평원추적자, 스카이워처 고원, 멀고어",
    ["Swamp of Sorrows"] = "슬픔의 늪",
    ["Swamp of Sorrows: dive into the Pool of Tears and follow the stairs down to the temple door"] = "슬픔의 늪: 눈물의 연못으로 뛰어들어 계단을 따라 사원 문까지 내려갑니다.",
    ["Swiftdart Battleboots"] = "날쌘화살 전투장화",
    ["Swiftfoot Treads"] = "날쌘발 장화",
    ["Swiftness Potion"] = "신속의 물약",
    ["Swiftwalker Boots"] = "빠른걸음 장화",
    ["Swim north across Lordamere Lake, passing from the Silverpine area into Tirisfal Glades."] = "로다미어 호수를 건너 북쪽으로 수영하여 은빛소나무 숲 지역에서 티리스팔 숲으로 이동합니다.",
    ["Swim north through Lordamere Lake"] = "로다미어 호수를 통해 북쪽으로 수영",
    ["Swine Fists"] = "멧돼지 건틀릿",
    ["Swinetusk Shank"] = "멧돼지어금니 단도",
    ["Sword"] = "도검",
    ["Sword of Decay"] = "쇠퇴의 검",
    ["Sword of Dismemberment"] = "절단의 검",
    ["Sword of Omen"] = "징조의 검",
    ["Sword of Serenity"] = "평온의 검",
    ["Sword of the Fallen"] = "쓰러진 자의 검",
    ["TBD"] = "확인 중",
    ["Tabetha"] = "타베사",
    ["Tabetha — Dustwallow Marsh"] = "타베타 — 먼지진흙 습지대",
    ["Tabetha's Task"] = "타베사의 임무",
    ["Tabetha, Dustwallow Marsh"] = "타베타, 먼지진흙 습지대",
    ["Tabitha Heartweaver — The Sepulcher"] = "타비사 하트위버 — 무덤",
    ["Tabitha Heartweaver, Silverpine Forest / The Sepulcher"] = "타비사 하트위버, 은빛소나무 숲 / 무덤",
    ["Tabitha Heartweaver, The Sepulcher, Silverpine Forest"] = "타비사 하트위버, 무덤, 은빛소나무 숲",
    ["Tabitha Heartweaver, The Sepulcher, 은빛소나무 숲"] = "타비사 하트위버, 무덤, 은빛소나무 숲",
    ["Tabitha's Cuffs"] = "감성의 소맷부리",
    ["Tablet Shard"] = "서판 조각",
    ["Tablet of Ryun'eh"] = "류네의 서판",
    ["Tablet of Will"] = "결의의 서판",
    ["Tail Spike"] = "꼬리 가시",
    ["Take An Unsent Letter from Edwin VanCleef to Baros Alexston in Stormwind."] = "에드윈 밴클리프에서 스톰윈드의 바로스 알렉스턴으로 부치지 않은 편지를 가져옵니다.",
    ["Take Bolvar's Decree to Magistrate Solomon in Lakeshire."] = "볼바르의 명령서를 레이크샤이어에 있는 집정관 솔로몬으로 가져가세요.",
    ["Take Brother Anton's Letter of Commendation to Raleigh the Devout in Southshore."] = "수사 안톤의 추천서를 사우스쇼어의 경건한 신자 랄레이로 가져갑니다.",
    ["Take Dibbs' I'lalai Translations to Historian Karnik in Ironforge."] = "디브의 일랄라이 번역을 아이언포지의 역사학자 카르닉으로 가져옵니다.",
    ["Take General Drakkisath's Command to Marshal Maxwell in Burning Steppes."] = "불타는 평원에 있는 사령관 드라키사스의 명령서를 치안대장 맥스웰로 가져가세요.",
    ["Take Hammertoe's Amulet to Historian Karnik in Ironforge."] = "해머토의 아뮬렛을 아이언포지의 역사학자 카르닉으로 가져갑니다.",
    ["Take Hammertoe's Amulet to Prospector Ryedol in the Badlands."] = "황야의 땅에서 해머토의 아뮬렛을 발굴조사단장 라이돌로 가져갑니다.",
    ["Take Shaw's Report to Gryan Stoutmantle in Westfall."] = "쇼의 보고서를 서부 몰락지대의 그라이언 스타우트맨틀로 가져갑니다.",
    ["Take Two With Water"] = "물과 함께 두 알",
    ["Take Wiley's Note back to Gryan Stoutmantle in Westfall."] = "와일리의 쪽지를 서부 몰락지대의 그라이언 스타우트맨틀로 다시 가져옵니다.",
    ["Take Wiley's Note to Master Mathias Shaw in Stormwind."] = "스톰윈드에서 와일리의 쪽지를 단장 마티아스 쇼로 가져갑니다.",
    ["Take a Bloodpetal to Gregan Brewspewer in Feralas."] = "페랄라스에 있는 그레간 브루스퓨에게 붉은꽃잎을 가져가세요.",
    ["Take a hundred paces due north of the camp and find the Mound of Dirt below the cliff."] = "캠프 정북쪽으로 100보 정도 가서 절벽 아래에서 흙무더기를 찾으세요.",
    ["Take off your gear. Guards will likely kill you a few times, and unequipped gear takes no durability damage."] = "장비를 벗으세요. 경비원은 당신을 몇 번 죽일 가능성이 높으며, 장착되지 않은 장비는 내구도 손상을 입지 않습니다.",
    ["Take the Arcanite Barding to Lord Grayson Shadowbreaker in Stormwind's Cathedral District for his inspection."] = "검사를 위해 아케이나이트 마갑을 스톰윈드의 대성당 구역에 있는 그레이슨 섀도브레이커 경으로 가져가세요.",
    ["Take the Brilliant Gold Ring to Nogg in Orgrimmar."] = "반짝이는 금반지를 오그리마에 있는 노그에게 가져가세요.",
    ["Take the Brilliant Gold Ring to Talvash del Kissel in Ironforge."] = "반짝이는 금반지를 아이언포지의 탈바쉬 델 키젤로 가져가세요.",
    ["Take the Dried Seeds to the Stagnant Oasis and test them at the fissure, then return to Tonga."] = "말라버린 씨앗을 죽은 오아시스로 가져가 균열에서 테스트한 다음 통가로 돌아갑니다.",
    ["Take the Elemental Shard Sample to Lotwil Veriatus. You recall Theodora saying that Lotwil was stationed in a camp to the east."] = "원소 파편 견본을 로트윌 베리아투스로 가져가세요. 당신은 테오도라가 로트윌이 동쪽 캠프에 주둔하고 있다고 말한 것을 기억합니다.",
    ["Take the Grimtotem Satchel to Rahauro in Thunder Bluff."] = "그림토템 가방을 썬더 블러프에 있는 라하우로에게 가져가세요.",
    ["Take the Head of Balnazzar to Duke Nicholas Zverenhoff in the Eastern Plaguelands."] = "발나자르의 혼을 동부 역병지대의 공작 니콜라스 즈바른호프로 가져갑니다.",
    ["Take the I'lalai Fetish to Abra Cadabra in Dalaran."] = "달라란에 있는 아브라카다브라에게 일랄라이 주물을 가져가세요.",
    ["Take the Reed-woven Heart back to Caitlin Grassman in Menethil Harbor."] = "갈대로 엮은 심장을 메네실 항구의 케이틀린 그라스만에게 가져가세요.",
    ["Take the Savage Coast Report Bundle (the fetishes, the troll legends and the scouting report) to Loremaster Dibbs in Southshore."] = "폭풍 해안 보고서 묶음(주물, 트롤 전설, 정찰 보고서)을 사우스쇼어에 있는 현자 딥스에게 가져가세요.",
    ["Take the Small Scroll to Varimathras in the Undercity."] = "작은 두루마리를 언더시티를 타고 바리마트라스로 가져가세요.",
    ["Take the Soulbound Keepsake to Leonid Barthalomew in Eastern Plaguelands."] = "영혼이 씌인 유품을 동부 역병지대의 리어니드 바돌로매로 가져가세요.",
    ["Take the Titan Relic to the Elder Rise in Thunder Bluff and look for someone who can tell you more about it."] = "티탄 유물을 썬더 블러프의 원로의 언덕으로 가져가 이에 대해 더 알려줄 사람을 찾으세요.",
    ["Take the Unforged Seal and the Orb of Draconic Energy to Emberstrife in the Wyrmbog, Dustwallow Marsh. The forged seal opens the UBRS door."] = "위조되지 않은 인장과 용력의 보주를 웜보그에 있는 엠버스트라이프 먼지진흙 습지대에게 가져가세요. 단조 봉인이 검은바위 첨탑 상층 도어를 엽니다.",
    ["Take the elevator down in north-west Dun Morogh, then keep left through the tunnels to the portal"] = "북서쪽 던 모로에서 엘리베이터를 타고 내려간 후 터널을 통해 왼쪽으로 이동하여 포털로 이동하세요.",
    ["Take the elevator down; the terminal is in the first passage on the right."] = "엘리베이터를 타고 내려가세요. 터미널은 오른쪽 첫 번째 통로에 있습니다.",
    ["Take the incomplete Banner of Provocation to Falrin Treeshaper at the library in Dire Maul."] = "불완전한 도전의 깃발을 혈투의 전장의 도서관에 있는 팔린 트리셰이퍼에게 가져가세요.",
    ["Take the letter to the city architect in Stormwind."] = "스톰윈드에 있는 도시 건축가에게 편지를 가져가세요.",
    ["Take the miniature version of the Discs of Norgannon to the Explorers' League in Ironforge."] = "아이언포지에 있는 탐험가 연맹에 노르간논의 원반 미니어처 버전을 가져가세요.",
    ["Take the miniature version of the Discs of Norgannon to the one of the sages in Thunder Bluff."] = "썬더 블러프에 있는 현자 중 한 명에게 노르간논의 소형 원반을 가져가세요.",
    ["Take the painting hidden behind the twin-moons picture in Archivist Galford's room before you burn the archives."] = "기록을 불태우기 전에 기록관 갈포드의 방에 있는 쌍월 그림 뒤에 숨겨진 그림을 가져가세요.",
    ["Take the path north-east of Sun Rock Retreat (50.9, 52.3) up to the abandoned camp; the Pocket Litter lies on a box. Optional: light the Firepit in the middle of the camp with the Simple Wood and Flint and Tinder from this quest (Rekindle)."] = "해바위 야영지 북동쪽 길(50.9, 52.3)을 따라 버려진 야영지까지 올라가세요. 주머니 속 잡동사니는 상자 위에 있습니다. 선택 사항: 이 퀘스트에서 받은 장작과 부싯돌을 사용하여 야영지 중앙의 화덕에 다시 불을 붙일 수 있습니다.",
    ["Take the path-book-east of Sun Rock Retreat"] = "해바위 야영지 북동쪽 길로 이동하세요",
    ["Take the tablet etchings to Master Gadrin in Sen'jin Village in Durotar."] = "듀로타의 센진 마을에 있는 장으로 가드린에게 서판 에칭을 가져가세요.",
    ["Take your reward voucher to Dinita Stonemantle in the Vault of Ironforge."] = "아이언포지 금고에 있는 디니타 스톤맨틀에게 보상 바우처를 가져가세요.",
    ["Talbar Mantle"] = "탈바르 어깨보호대",
    ["Talendria"] = "탈렌드리아",
    ["Talendria — Desolace"] = "탈렌드리아 — 잊혀진 땅",
    ["Talendria, Nijel's Point, Desolace"] = "탈렌드리아, 나이젤 포인트, 잊혀진 땅",
    ["Talisman of Evasion"] = "도피의 부적",
    ["Talk to Goretooth to receive his Command item and click it to start the quest. The Important Blackrock Documents spawn near the three generals."] = "고어투스에게 말을 걸어 명령 아이템을 받고 클릭하면 퀘스트가 시작됩니다. 중요한 검은바위 문서는 세 명의 장군 근처에 생성됩니다.",
    ["Talk to Malyfous Darkhammer in Everlook."] = "눈망루 마을에 있는 말리퍼스 다크해머와 대화하세요.",
    ["Talk to Stormwind Intelligence about acquiring a remote detonator."] = "스톰윈드 정보부와 원격 기폭 장치 획득에 관해 대화하세요.",
    ["Talk to Wiley the Black in Lakeshire."] = "레이크샤이어에 있는 악당 와일리와 대화하세요.",
    ["Talk to a friendly Captain Kromcrush after you become the Gordok king. The Gauntlet of Gordok Might is in a chest near Prince Tortheldrin in Dire Maul West."] = "고르독 왕이 된 후 아군 대장 크롬크러쉬와 대화하세요. 권력의 고르독 건틀릿는 혈투의 전장 서쪽의 왕자 토르텔드린 근처 상자에 있습니다.",
    ["Talo Thornhoof"] = "탈로 쏜후프",
    ["Talo Thornhoof — Feralas"] = "탈로 쏜후프 — 페랄라스",
    ["Talo Thornhoof — 페랄라스"] = "탈로 쏜후프 — 페랄라스",
    ["Talo Thornhoof, Camp Mojache, Feralas"] = "탈로 쏜후프, 모자케 야영지, 페랄라스",
    ["Talo Thornhoof, Camp Mojache, 페랄라스"] = "탈로 쏜후프, 모자케 야영지, 페랄라스",
    ["Talon of Tor'Rel"] = "토르렐의 발톱",
    ["Talvash del Kissel"] = "탈바쉬 델 키젤",
    ["Talvash del Kissel (Phial of Scrying)"] = "탈바쉬 델 키젤 (수정점의 유리병)",
    ["Talvash del Kissel — Ironforge"] = "탈바쉬 델 키젤 — 아이언포지",
    ["Talvash del Kissel — Mystic Ward, Ironforge"] = "탈바쉬 델 키젤 — 신비한 와드, 아이언포지",
    ["Talvash del Kissel — Mystic Ward, 아이언포지"] = "탈바쉬 델 키젤 — 신비한 와드, 아이언포지",
    ["Talvash del Kissel — 아이언포지"] = "탈바쉬 델 키젤 — 아이언포지",
    ["Talvash del Kissel, Ironforge"] = "탈바쉬 델 키젤, 아이언포지",
    ["Talvash del Kissel, Mystic Ward, Ironforge"] = "탈바쉬 델 키젤, 미스틱 와드, 아이언포지",
    ["Talvash del Kissel, Mystic Ward, Ironforge (36.0, 4.0)"] = "탈바쉬 델 키젤, 미스틱 와드, 아이언포지 (36.0, 4.0)",
    ["Talvash del Kissel, Mystic Ward, 아이언포지"] = "탈바쉬 델 키젤, 미스틱 와드, 아이언포지",
    ["Talvash del Kissel, 아이언포지"] = "탈바쉬 델 키젤, 아이언포지",
    ["Talvash's Enhancing Necklace"] = "탈바쉬의 마법 목걸이",
    ["Talvash's Enhancing Necklace\n5,600 XP • Gnomeregan Exiles +200"] = "탈바쉬의 마법 목걸이\n5,600 경험치 • 놈리건 +200",
    ["Talvash's Gold Ring"] = "탈바쉬의 금반지",
    ["Talvash's Scrying Bowl, Uldaman"] = "탈바쉬의 수정점 그릇, 울다만",
    ["Talvash's Scrying Bowl, 울다만"] = "탈바쉬의 수정점 그릇, 울다만",
    ["Tanglemoss Leggings"] = "이끼덩굴 다리보호구",
