    ["Tecelão"] = "테셀랑",
    ["Technician's Bracers"] = "기술자의 팔보호구",
    ["Tell Commander Folkar what you found."] = "폴카르 사령관에게 무엇을 찾았는지 말해주세요.",
    ["Tempest Talisman"] = "돌개바람 부적",
