    ["Thadius Grimshade, Blasted Lands"] = "샤디우스 그림섀이드, 저주받은 땅",
    ["Thandol Span (Arathi Highlands / Wetlands border)"] = "탄돌 경간(아라시 고원 / 저습지 경계)",
