    ["The Capital Gardens and the Court of the Highborne, where the last Shen'dralar keep the demon Immol'thar imprisoned behind five pylons. Needs the Crescent Key from Pusillin."] = "마지막 셴드랄라가 5개의 철탑 뒤에 악마 이몰타르를 가두어 두는 굽이나무 지구 및 명가의 법원입니다. 푸실린의 초승달 열쇠가 필요합니다.",
    ["The Celebrian Rod drops from Noxxion and the Celebrian Diamond from Lord Vyletongue."] = "셀레브리안 마법봉는 녹시온에서, 셀레브리안 다이아몬드는 군주 바일텅에서 떨어집니다.",
