    ["The Razorfen Kraul step."] = "가시덩굴 우리 단계입니다.",
    ["The Razorfen Kraul step. After Call of Air, Prate Cloudseer sends you to Rau Cliffrunner. It can't be shared on the Horde side."] = "가시덩굴 우리 단계입니다. 바람의 부름 이후 프레이트 클라우드시어는 라우 클리프러너로 보냅니다. 호드 측에서는 공유할 수 없습니다.",
    ["The Razorfen Kraul step. Call of Air (from Eldrun Stormbreaker in Ironforge) sends you to Veyric. Alliance Shamans can share this quest."] = "가시덩굴 우리 단계입니다. 바람의 부름(아이언포지의 엘드룬 스톰브레이커에서)가 베이릭에게 보냅니다. 얼라이언스 주술사는 이 퀘스트를 공유할 수 있습니다.",
