    ["The Saltseer Captain"] = "소금예언자 선장",
    ["The Scarlet Key"] = "붉은십자군 열쇠",
    ["The Scarshield Quartermaster is in the hallway outside the Spire portal. Touch Drakkisath's Brand behind General Drakkisath; this unlocks the Orb of Command shortcut to Blackwing Lair."] = "방패부대 병참장교는 검은바위 첨탑 입구 바깥 복도에 있습니다. 사령관 드라키사스 뒤에 있는 드라키사스의 낙인을 만지면 지배의 보주를 통해 검은날개 둥지로 바로 들어갈 수 있습니다.",
