    ["The Spider God"] = "거미 신",
    ["The Spirit Healer is right outside the city, so each death means a short run back. Resurrect in quiet corners out of the guards' sight so you gain ground every time."] = "영혼의 치유사는 도시 바로 외곽에 있으므로 사망할 때마다 단기적으로 되돌아가게 됩니다. 경비원의 시야에서 벗어난 조용한 구석에서 부활하여 매번 기반을 확보하세요.",
