    ["The Tempest's Weapons"] = "폭풍의 무기",
    ["The Temple of Atal'Hakkar"] = "아탈학카르 신전",
    ["The Temple of Atal'Hakkar, sunk beneath the Pool of Tears in the Swamp of Sorrows. The Atal'ai trolls try to summon their blood god Hakkar here, while the green dragons of Eranikus guard the lower halls."] = "아탈학카르 신전는 슬픔의 늪의 눈물의 연못 아래에 가라앉았습니다. 아탈라이 트롤들은 자신들의 혈신 학카르를 이곳으로 소환하려고 하고, 에라니쿠스의 녹색용들은 아래층 홀을 지키고 있습니다.",
    ["The Test of Righteousness"] = "정의의 시험",
