    ["The Test of Skulls, Chronalis"] = "해골 시험 - 크로날리스",
    ["The Test of Skulls, Scryer"] = "해골 시험 - 스크라이어",
    ["The Test of Skulls, Somnus"] = "해골 시험 - 솜누스",
    ["The Testament of Rexxar"] = "렉사르의 유언",
    ["The Third Tablet of I'lalai"] = "이랄라이의 세 번째 서판",
    ["The Third Troll Legend"] = "트롤의 전설 3부",
    ["The Tiara drops from Hydromancer Velratha.\n\nOptional introductory quest:"] = "티아라는 유체술사 벨라타에서 드랍됩니다.\n\n선택적인 소개 퀘스트:",
    ["The Tome of Valor"] = "용맹의 고서",
    ["The Treaty of Understanding"] = "이해의 조약",
    ["The True Masters"] = "진정한 지도자",
    ["The Truth Comes Crashing Down"] = "밝혀지는 진실",
    ["The Twin Bears"] = "쌍둥이 곰",
    ["The Undercity zeppelin docks at the tower outside Orgrimmar. Ask Frezza if you're unsure which one it is."] = "언더시티 비행선은 오그리마 외부 타워에 정박합니다. 그것이 어느 것인지 확실하지 않으면 프레자에게 물어보세요.",
    ["The Unsent Letter"] = "부치지 않은 편지",
    ["The Vile Reef"] = "썩은내 산호초",
    ["The Wayward Warrior"] = "방황하는 전사",
    ["The Web of Magic"] = "마법의 그물",
    ["The Western Front"] = "서부 전선",
    ["The Windshaper's Wrath"] = "바람구체자의 분노",
    ["The Witch Doctor's Head"] = "의술사의 머리",
    ["The Work of Grimand Elmore"] = "그리만트 엘모어의 마갑",
    ["The Wrath of Rath'mael"] = "라스마엘의 격노",
    ["The Wrong Stuff"] = "인형 재료",
    ["The altar at the very top of Jintha'Alor"] = "진타알로 꼭대기에 있는 제단",
    ["The ancient burial grounds of the quilboar, now held by the Scourge. Amnennar the Coldbringer leads the undead from the top of the Downs."] = "현재는 스컬지가 차지하고 있는 가시멧돼지의 고대 묘지입니다. 혹한의 암네나르는 다운스 꼭대기에서 언데드들을 이끌고 있습니다.",
    ["The armory wing of the Scarlet Monastery, where the Crusade drills its recruits under the eye of Herod, the Scarlet Champion. The door is locked: you need The Scarlet Key from the Library."] = "십자군이 헤롯 붉은십자군 용사의 감독하에 신병들을 훈련시키는 붉은십자군 수도원의 병기동입니다. 문이 잠겨 있습니다. 도서관에서 붉은십자군 열쇠가 필요합니다.",
    ["The bag drops from Jandice Barov."] = "가방은 잔다이스 바로브에서 드랍됩니다.",
    ["The book is inside Scarlet Monastery: Library."] = "책은 붉은십자군 수도원: 도서관 안에 있습니다.",
    ["The burnt tower on the road south of Camp Taurajo"] = "캠프 타우라조 남쪽 도로에 있는 불탄 탑",
    ["The capital of the Dark Iron dwarves beneath Blackrock Mountain: the Detention Block, the Ring of Law, the Grim Guzzler and Shadowforge City, ruled by Emperor Dagran Thaurissan."] = "검은바위 산 아래에 있는 검은무쇠 드워프의 수도: 구금 구역, 법의 투기장, 음울한 술수병, 제왕 다그란 타우릿산가 통치하는 어둠괴철로 도시.",
    ["The cart wreckage at the Alexston Farmstead"] = "알렉스턴 농장의 카트 잔해\n알렉스턴 농장의 수레 잔해에 있는",
    ["The cave is in Sunken Hollow, underwater around 21, 28: the entrance to the Drowned City."] = "동굴은 21, 28쯤 수중의 가라앉은 동굴에 있습니다: 가라앉은 도시의 입구.",
    ["The chain begins by dropping Dark Iron Map from Dark Iron Spies in Dun Morogh."] = "체인은 던 모로의 검은무쇠 첩보원에게서 검은무쇠 지도를 떨어뜨리는 것으로 시작됩니다.",
    ["The current Forever quest data also lists Arcane Intellect as a learned reward."] = "현재 포에버 퀘스트 데이터에는 신비한 지능도 학습된 보상으로 나열되어 있습니다.",
    ["The direct quest has no item reward. Its follow-up, In Nightmares, later offers:"] = "직접 퀘스트에는 아이템 보상이 없습니다. 후속 제품인 악몽는 이후 다음을 제공합니다.",
    ["The discs are in the Map Chamber, past Ironaya."] = "디스크는 아이로나야를 지나 지도실에 있습니다.",
    ["The eastern quarter of the ruined Highborne city of Eldre'Thalas, overgrown by the Warpwood and ruled by the satyr Alzzin the Wildshaper. Pusillin carries the Crescent Key that opens the other wings."] = "폐허가 된 명가 도시 엘드레'탈라스의 동쪽 구역으로, 워프우드가 무성하고 사티로스 칼날바람 알진가 통치합니다. 푸실린은 다른 날개를 여는 초승달 열쇠를 운반합니다.",
    ["The fallen cart at Thoradin's Wall: climb it"] = "소라딘의 벽에 쓰러진 수레: 올라가세요",
    ["The fifth and sixth Mosh'aru tablets are in the Smolderthorn troll area. Continues with Confront Yeh'kinya and The Hand of Rastakhan."] = "다섯 번째와 여섯 번째 모쉬아루 서판은 가시불꽃 트롤 지역에 있습니다. 예킨야와의 대면 및 라스타칸의 대리인으로 계속됩니다.",
    ["The foreman is in the tunnels before the instance portal."] = "감독은 인스턴스 포털 앞 터널에 있습니다.",
    ["The four deeds: Southshore in the first large chamber, Tarren Mill before the hatchlings, Brill by Ras Frostwhisper, Caer Darrow by Lord Alexei Barov. The follow-up The Last Barov sends you to kill the rival brother."] = "네 가지 행위: 첫 번째 대형 챔버의 사우스쇼어, 부화 이전의 타렌 밀농장, 브릴 인근 라스 프로스트위스퍼, 카엘 다로우 인근 군주 알렉세이 바로브. 후속 최후의 바로브는 라이벌 형제를 죽이라고 당신을 보냅니다.",
    ["The glowing rune on the floor of Baron Rivendare's room, Stratholme (Undead side)"] = "남작 리븐데어의 방, 스트라솔름 바닥에 빛나는 룬(언데드 쪽)",
    ["The gong at Gahz'rilla's pool, inside Zul'Farrak: use the Mallet of Zul'Farrak there to summon Gahz'rilla."] = "줄파락 내부의 가즈릴라 웅덩이에 있는 징: 거기에서 줄파락의 나무망치를 사용하여 가즈릴라를 소환하세요.",
    ["The graveyard wing of the Scarlet Monastery, haunted by restless dead and Scarlet defenders."] = "붉은십자군 수도원의 묘지 건물로, 불안한 망자들과 붉은십자군 수비수들의 유령이 맴돌고 있습니다.",
    ["The heart of the Scarlet Monastery: the Chapel Gardens and the Crusader's Chapel, held by Scarlet Commander Mograine and High Inquisitor Whitemane. The door is locked: you need The Scarlet Key from the Library."] = "붉은십자군 수도원의 심장부: 예배당 정원과 십자군 예배당은 붉은십자군 사령관 모그레인 및 종교재판관 화이트메인가 보유하고 있습니다. 문이 잠겨 있습니다. 도서관에서 붉은십자군 열쇠가 필요합니다.",
    ["The hill path, west"] = "언덕길, 서쪽",
    ["The imp you chase through the Warpwood Quarter; he fights at the end and drops the Crescent Key."] = "굽이나무 지구에서 쫓는 임프입니다. 그는 마지막에 싸우고 초승달 열쇠를 떨어뜨립니다.",
    ["The irradiated underground city of the gnomes, overrun by troggs and Mekgineer Thermaplugg's forces."] = "방사능에 노출된 노움의 지하 도시는 트로그와 멕기니어 텔마플러그의 군대에 의해 점령당했습니다.",
    ["The item choice is awarded on the follow-up Unending Torment step in Undercity."] = "항목 선택은 언더시티의 후속 끝없는 고통 단계에서 부여됩니다.",
    ["The key from this quest unlocks the upper side of the dungeon."] = "이 퀘스트의 열쇠는 던전의 위쪽을 잠금 해제합니다.",
    ["The library wing of the Scarlet Monastery, home to the Houndmaster's kennels and Arcanist Doan's athenaeum."] = "사냥개조련사의 개집과 신비술사 도안의 아테네움이 있는 붉은십자군 수도원의 도서관 건물입니다.",
    ["The lower halls of Blackrock Spire, held by the Spirestone, Smolderthorn and Bloodaxe clans of the Dark Horde under Overlord Wyrmthalak."] = "대군주 웜타라크가 이끄는 검은 호드의 뾰족바위·가시불꽃·피도끼 부족이 장악한 검은바위 첨탑 하층입니다.",
    ["The main gate of Stratholme: the burning streets, the Scarlet Bastion and the Hall of Lights, where Grand Crusader Dathrohan reveals himself as the dreadlord Balnazzar."] = "스트라솔름의 정문: 불타는 거리, 붉은십자군 요새, 빛의 전당, 십자군사령관 다스로한가 공포의 군주 발나자르임을 드러냅니다.",
    ["The main road, north"] = "주요 도로, 북쪽",
    ["The medallion drops from Nekrum Gutchewer."] = "메달리온은 네크룸 거트츄어에서 드랍됩니다.",
    ["The messenger travels the roads between Moonbrook, Gold Coast Quarry and Jangolode Mine."] = "메신저는 문브룩, 황금해안 채석장 및 장고로드 광산 사이의 도로를 이동합니다.",
    ["The necklace's original Blackmaw owner (location not yet confirmed)"] = "목걸이의 원래 검은아귀 소유자(위치는 아직 확인되지 않음)",
    ["The next required oasis investigation after The Forgotten Pools."] = "잊혀진 웅덩이 이후에 필요한 다음 오아시스 조사입니다.",
    ["The only punchographs outside the instance: on the raised platform in the Train Depot and by the Workshop (back door) entrance."] = "인스턴스 밖의 천공기는 열차 보관소의 높은 단과 작업장 뒷문 입구 옆 두 곳에만 있습니다.",
    ["The other pylons: east at 73, 23 (more arcane elementals, you get dismounted there) and south at 47, 78 inside the big Shen'dralas building."] = "다른 철탑: 큰 셴드랄라스 건물 내부의 동쪽 73, 23(더 많은 신비한 정령이 있으면 그곳에서 내리게 됩니다)과 남쪽 47, 78에 있습니다.",
    ["The power source drops from Archaedas. Finishing it unlocks Talvash's Enhancing Necklace."] = "아카에다스에게서 동력원이 떨어집니다. 완료하면 탈바쉬의 마법 목걸이의 잠금이 해제됩니다.",
    ["The power stones drop from Shadowforge dwarves in the outer cave."] = "외부 동굴에 있는 어둠괴철로 드워프에게서 파워 스톤이 떨어집니다.",
    ["The questline starts at level 18 with Diplomatic Incident from Danitha Morr at Bandarion Keep, Tirisfal Glades. It takes you to Fenris Isle, where you free Lumina Windsinger from Fenris Keep."] = "퀘스트 라인은 레벨 18에서 다니타 모르의 반다리온 성채, 티리스팔 숲의 외교 사건으로 시작됩니다. 펜리스 요새에서 루미나 윈드싱어를 구출할 수 있는 펜리스 섬으로 이동합니다.",
    ["The restored mage city of Dalaran has become a new five-player dungeon in WoW Forever. Enter through the sewers and the Underbelly, then fight through the streets to the Violet Citadel."] = "복원된 마법사 도시 달라란가 와우 포에버의 새로운 5인 던전이 되었습니다. 하수구와 마법의 뒤안길을 통해 들어간 다음 거리를 통해 보랏빛 성채까지 싸워보세요.",
    ["The road into Stonetalon (round Honor's Stand)"] = "돌발톱으로 가는 길(명예의 격전지 라운드)",
    ["The road north, past Webwinder Path"] = "북쪽 도로, 웹와인더 경으로 지나",
    ["The road south"] = "남쪽으로 가는 길",
    ["The road south out of Stonetalon Peak"] = "돌발톱 봉우리 남쪽으로 가는 길",
    ["The road west out of the Barrens"] = "불모의 땅에서 서쪽으로 가는 길",
    ["The rod drops from Sergeant Bly after the pyramid event."] = "피라미드 이벤트 이후 하사관 블라이에서 로드가 드랍됩니다.",
    ["The ruined city of Lordaeron"] = "폐허가 된 도시 로데론",
    ["The sacred caverns of the centaur in Desolace, where Princess Theradras and her corrupted earth elementals rule beneath Zaetar's grave. The orange and purple wings lead to the inner caves; the Scepter of Celebras opens the shortcut to the waterfall."] = "잊혀진 땅에 있는 켄타우로스의 신성한 동굴로, 공주 테라드라스와 그녀의 타락한 대지 정령들이 재타르의 무덤 아래를 지배하고 있습니다. 주황색과 보라색 날개는 내부 동굴로 연결됩니다. 셀레브라스의 홀는 폭포로 가는 지름길을 엽니다.",
    ["The sapphire drops from Grimlok and the power source from Archaedas."] = "사파이어는 그림로크에서, 동력원은 아카에다스에서 떨어집니다.",
    ["The sapphire drops from Grimlok."] = "그림록에서 사파이어가 떨어집니다.",
    ["The service entrance side of Stratholme, held by the Scourge: the three ziggurats, the Slaughter House and Baron Rivendare's stronghold. Kill the Baron within 45 minutes to save Ysida Harmon."] = "스컬지가 점령하고 있는 스트라솔름의 서비스 입구 쪽: 세 개의 지구라트, 도살장, 남작 리븐데어의 요새. 이시다 하몬을 저장하려면 45분 이내에 남작을 처치하세요.",
    ["The sun-baked troll city in the deserts of Tanaris, home of the Sandfury tribe and their chief, Ukorz Sandscalp."] = "타나리스 사막에 있는 햇볕에 그을린 트롤 도시로, 성난모래 부족과 그들의 족장인 유코르즈 샌드스칼프의 본거지입니다.",
    ["The supplies are found in the caves leading toward the Deadmines entrance."] = "보급품은 죽음의 폐광 입구로 이어지는 동굴에서 찾을 수 있습니다.",
    ["The tablet Moon Over the Vale (around 29, 19)"] = "태블릿 골짜기의 달(29, 19경)",
    ["The tablet The Emperor's Tomb (around 25, 9)"] = "태블릿 제국의 무덤(약 25, 9)",
    ["The tablet at the bottom of the Vile Reef (around 25, 23)"] = "썩은내 산호초 바닥에 있는 서판(약 25, 23)",
    ["The tablet in the troll ruins on the coast (around 23, 12)"] = "해안가의 트롤 유적에 있는 서판(23, 12경)",
    ["The tablet is inside one of the vaults in the Reliquary of Kings, in Durgen Dirgehammer's final boss room. Open the vaults and interact with the tablet before leaving the dungeon."] = "마지막 우두머리 두르겐 더지해머의 방인 왕들의 성물실에 있는 금고 중 하나에 서판이 있습니다. 던전을 떠나기 전에 금고를 열고 서판을 확인하세요.",
    ["The tablets drop from Theka the Martyr and Hydromancer Velratha."] = "태블릿은 순교자 데카 및 유체술사 벨라타에서 드롭됩니다.",
    ["The top of Blackrock Spire, held by Rend Blackhand's Dark Horde and General Drakkisath's black dragonflight. The door needs the Seal of Ascension."] = "렌드 블랙핸드의 다크 호드와 사령관 드라키사스의 검은용군단이 들고 있는 검은바위 첨탑의 꼭대기입니다. 문에는 승천의 인장가 필요합니다.",
    ["The undead side tunnel is before the instance portal."] = "언데드 사이드 터널은 인스턴스 포털 앞에 있습니다.",
    ["The urns are in the outer Uldaman cave, before the instance portal.\n\nOptional introductory quest:"] = "항아리는 인스턴스 포털 앞 울다만 외부 동굴에 있습니다.\n\n선택적인 소개 퀘스트:",
    ["The web drops from Lethtendris.\n\nOptional introductory quest:"] = "거미줄은 레스텐드리스에서 떨어집니다.\n\n선택적인 소개 퀘스트:",
    ["Theka the Martyr"] = "순교자 데카",
    ["Theka's Last Breath"] = "테카의 마지막 숨결",
    ["Theldren"] = "텔드렌",
    ["Theldurin the Lost"] = "실성한 텔두린",
    ["Theldurin the Lost — Badlands"] = "실성한 텔두린 — 황야의 땅",
    ["Theldurin the Lost — 황야의 땅"] = "실성한 텔두린 — 황야의 땅",
    ["Theldurin the Lost, Badlands"] = "실성한 텔두린, 황야의 땅",
    ["Theldurin the Lost, 황야의 땅"] = "실성한 텔두린, 황야의 땅",
    ["Thelgen Rock"] = "텔겐 바위굴",
    ["Then Lord Maxwell Tyrosus and The Argent Hold, in Light's Hope Chapel, give the weapon or shield reward."] = "그런 다음 맥스웰 티로서스 경 및 여명회의 궤는 희망의 빛 예배당에서 무기 또는 방패 보상을 제공합니다.",
    ["Then take Bijou's Reconnaissance Report to Lexlort in Kargath for the reward."] = "그런 다음 비쥬의 정찰 보고서를 카르가스에 있는 렉스로트에게 가져가 보상을 받으세요.",
    ["Theodore Griffs — Apothecarium"] = "시어도어 그리프스 — 연금술 실험실",
    ["Theodore Griffs — 연금술 실험실"] = "시어도어 그리프스 — 연금술 실험실",
    ["Theodore Griffs, Undercity"] = "시어도어 그리프스, 언더시티",
    ["Theodore Griffs, 언더시티"] = "시어도어 그리프스, 언더시티",
    ["Theradric Crystal Carvings"] = "테라드릭 수정 조각",
    ["Theramore"] = "테라모어",
    ["Theramore Defender's Gauntlets"] = "테라모어 방어자의 건틀릿",
