    ["Thicket Raptor Meat comes from the Thicket raptors (Thicket Lurker, Thicket Hunter, Thicket Matriarch) in Stalker's Thicket, the area of Shadetooth."] = "덤불 랩터 고기는 추적자의 덤불에 있는 덤불 랩터(덤불 잠복꾼, 덤불 사냥꾼, 덤불 우두머리)에게서 얻습니다. 그늘이빨가 있는 구역입니다.",
    ["Thicket Raptor Meat는 추적자의 덤불에 있는 덤불 랩터(Thicket Lurker, Thicket Hunter, Thicket Matriarch)에게서 얻습니다. Shadetooth가 있는 구역입니다."] = "덤불 랩터 고기는 추적자의 덤불에 있는 덤불 랩터(덤불 잠복꾼, 덤불 사냥꾼, 덤불 우두머리)에게서 얻습니다. 그늘이빨가 있는 구역입니다.",
    ["Thief's Blade"] = "도적의 칼",
