    ["This is a chain quest with a step in Razorfen Kraul"] = "가시덩굴 우리 단계가 포함된 연쇄 퀘스트입니다.",
    ["This is a long chain that has a step in the Library"] = "라이브러리에 단이 있는 긴 체인입니다.",
    ["This leads directly into Underground Assault."] = "이는 지하 공격으로 직접 연결됩니다.",
    ["This mountain pass leads into Loch Modan. Alliance guards stand at the checkpoint, so keep running and let your speed carry you through."] = "이 산길은 모단 호수(모단 호수)로 이어집니다. 얼라이언스 경비원이 검문소에 서 있으니 계속 달리면서 속도를 높이세요.",
    ["This opens the Shen'dralas quests, Mithera's included."] = "셴드랄라스 퀘스트, 미테라가 포함되어 있습니다.",
