    ["Trash Drops"] = "일반 몬스터 전리품",
    ["Traumsense"] = "꿈의 낫",
    ["Travel into the Sunken Temple and discover the secret hidden in the circle of statues."] = "가라앉은 사원으로 여행하여 원형 조각상에 숨겨진 비밀을 찾아보세요.",
    ["Travel south from Undercity through Tirisfal Glades and Silverpine Forest, then continue into Hillsbrad Foothills until you reach Tarren Mill."] = "언더시티에서 티리스팔 숲 및 은빛소나무 숲을 거쳐 남쪽으로 이동한 다음 타렌 밀농장에 도달할 때까지 힐스브래드 구릉지로 계속 이동합니다.",
    ["Travel to Blackrock Depths and find Kharan Mighthammer. The King mentioned that Kharan was being held prisoner there - perhaps you should try looking for a prison."] = "검은바위 나락으로 이동하여 카란 마이트해머를 찾으세요. 왕은 카란이 그곳에서 포로로 잡혀 있다고 말했습니다. 아마도 당신은 감옥을 찾아보아야 할 것입니다.",
    ["Travel to Blackrock Depths and recover 10 Essence of the Elements. Your first inclination is to search the golems and golem makers. You remember Vivian Lagrave also muttering something about elementals."] = "검은바위 나락으로 이동하여 원소의 정수 10개를 회수하세요. 당신의 첫 번째 성향은 골렘과 골렘 제작자를 검색하는 것입니다. 비비안 라그레이브도 정령에 대해 중얼거렸던 것을 기억하시나요?",
    ["Travel to Blackrock Depths and recover 20 Dark Iron Fanny Packs. Return to Oralius when you have completed this task. You assume that the Dark Iron dwarves inside Blackrock Depths carry these 'fanny pack' contraptions."] = "검은바위 나락으로 이동하여 검은무쇠 허리 팩 20개를 복구하세요. 이 임무를 완료하면 오랄리우스에게 돌아가십시오. 당신은 검은바위 나락 내부의 검은무쇠 드워프들이 이러한 '엉덩이 가방' 장치를 가지고 있다고 가정합니다.",
    ["Travel to Blackrock Depths and slay Bael'Gar. Use the Altered Black Dragonflight Molt on Bael'Gar's remains to capture the Fiery Essence. Return the Encased Fiery Essence to Cyrus Therepentous."] = "검은바위 나락으로 이동하여 바엘가르를 처치하세요. 밸가르의 유해에 변형된 검은용군단 허물을 사용하여 불타는 정수를 캡처하세요. 담겨진 불의 정수를 키루스 테레펜터스로 반환합니다.",
    ["Travel to Blackrock Depths and slay General Angerforge! Return to Warlord Goretooth when the task is complete."] = "검은바위 나락으로 이동하여 사령관 앵거포지를 처치하세요! 작업이 완료되면 장군 고어투스로 돌아갑니다.",
    ["Travel to Blackrock Mountain in the northwest and enter Blackrock Depths. Find out what became of Marshal Windsor. You recall Ragged John talking about Windsor being dragged off to a prison."] = "북서쪽에 있는 검은바위 산으로 이동하여 검은바위 나락을 입력합니다. 치안대장 윈저가 어떻게 되었는지 알아보세요. 털보 존가 윈저가 감옥으로 끌려간 것에 대해 이야기했던 것을 기억합니다.",
    ["Travel to Blackrock Spire and collect 15 Spire Spider Eggs for Kibler. By the sound of it, these eggs could be found near spiders."] = "검은바위 첨탑으로 이동하여 키블러를 위한 첨탑거미 알 15개를 수집하세요. 그 소리에 따르면 이 알은 거미 근처에서 발견될 수 있었습니다.",
    ["Travel to Blackrock Spire and collect 20 Black Dragonspawn Eyes. Return to Myranda the Hag when the task is complete."] = "검은바위 첨탑으로 이동하여 검은용혈족 눈 20개를 수집하세요. 작업이 완료되면 노파 미란다로 돌아갑니다.",
    ["Travel to Blackrock Spire and destroy General Drakkisath. Return to Marshal Maxwell when the job is done."] = "검은바위 첨탑으로 이동하여 사령관 드라키사스를 파괴하세요. 작업이 완료되면 치안대장 맥스웰로 돌아갑니다.",
    ["Travel to Blackrock Spire and destroy War Master Voone, Highlord Omokk, and Overlord Wyrmthalak. Return to Marshal Maxwell when the job is done."] = "검은바위 첨탑으로 이동하여 대장군 부네, 대군주 오모크, 대군주 웜타라크를 파괴하세요. 작업이 완료되면 치안대장 맥스웰로 돌아갑니다.",
    ["Travel to Blackrock Spire and destroy War Master Voone, 대군주 오모크, and Overlord Wyrmthalak. Return to Marshal Maxwell when the job is done."] = "검은바위 첨탑으로 이동하여 대장군 부네, 대군주 오모크, 대군주 웜타라크를 파괴하세요. 작업이 완료되면 치안대장 맥스웰로 돌아갑니다.",
    ["Travel to Blackrock Spire and destroy the source of the worg menace. As you left Helendis, he shouted a name: Halycon. It is what the orcs refer to in regards to the worg."] = "검은바위 첨탑으로 이동하여 늑대인간 위협의 근원을 파괴하세요. 헬렌디스를 떠날 때 그는 할리콘이라는 이름을 외쳤습니다. 오크들이 늑대인간에 관해 언급하는 것이 바로 이것이다.",
    ["Travel to Blackrock Spire and find Bloodaxe Worg Pups. Use the cage to carry the ferocious little beasts. Bring back a Caged Worg Pup to Kibler."] = "검은바위 첨탑으로 가서 도끼부대 검은늑대 새끼들을 찾으세요. 우리를 사용하여 사나운 작은 짐승을 운반하세요. 사로잡은 새끼 검은늑대를 키블러에게 가져가세요.",
    ["Travel to Blackrock Spire and find out what happened to Bijou."] = "검은바위 첨탑으로 가서 비쥬에게 무슨 일이 일어났는지 알아내세요.",
    ["Travel to Blackrock Spire and slay General Drakkisath. Gather his blood and return it to Rexxar."] = "검은바위 첨탑으로 이동하여 사령관 드라키사스를 처치하세요. 그의 피를 모아 렉사르에게 돌려주십시오.",
    ["Travel to Blackrock Spire and slay Warchief Rend Blackhand. Take his head and return to Orgrimmar."] = "검은바위 첨탑으로 이동하여 대족장 렌드 블랙핸드를 처치하세요. 그의 머리를 잡고 오그리마로 돌아갑니다.",
    ["Travel to Blackrock Spire, slay Goraluk Anvilcrack and use the Blood Stained Pike on his corpse. Also find the Unforged Rune Covered Breastplate. Return the Soul Stained Pike and the breastplate to Lorax in Winterspring."] = "검은바위 첨탑으로 이동하여 고랄루크 앤빌크랙을 처치하고 그의 시체에 핏물이 깃든 창을 사용하십시오. 벼려지지 않은 룬문자 흉갑도 찾아보세요. 윈터스프링에 있는 로렉스에게 영혼이 깃든 창과 흉갑을 가져가세요.",
    ["Travel to Corin's Crossing to the east and slaughter the Scourge that inhabit the town. Collect 7 pieces of Living Rot in under 10 minutes. Use the Mortar and Pestle to grind the Living Rot into Coagulated Rot."] = "동쪽의 코린 교차로로 이동하여 마을에 서식하는 스컬지를 처치하세요. 10분 안에 살아있는 부패물 조각 7개를 수집하세요. 막자 사발을 사용하여 살아있는 부패물을 응고된 부패물로 갈아주세요.",
    ["Travel to Dire Maul and locate the Imp, Pusillin. Convince Pusillin to give you Azj'Tordin's Book of Incantations through any means necessary. Return to Azj'Tordin at the Lariss Pavilion in Feralas should you recover the Book of Incantations."] = "혈투의 전장으로 가서 임프, 푸실린을 찾으세요. 푸실린을 설득하여 필요한 모든 수단을 통해 아즈토르딘의 마법서를 제공하십시오. 마법서를 회수하려면 페랄라스의 라리스 정자에 있는 아즈토르딘에게 돌아가세요.",
    ["Travel to Gershala Nightwhisper in Auberdine, Darkshore."] = "어둠해안 아우버다인에 있는 게르샬라 나이트위스퍼로 이동하세요.",
    ["Travel to Grim Batol and track down Axtroz, drake champion of the Red Flight. Destroy him and take his skull. Return the skull to Emberstrife."] = "그림 바톨로 이동하여 붉은용군단의 드레이크 챔피언인 악스트로즈를 추적하세요. 그를 파괴하고 그의 두개골을 가져가세요. 해골을 엠버스트라이프에게 돌려주세요.",
    ["Travel to Ironforge and get High Priest Rohan's Exorcism Censer. You will need to make a donation of 150 gold in order to secure it."] = "아이언포지로 이동하여 대사제 로한의 퇴마 향로를 획득하세요. 이를 확보하려면 150골드를 기부해야 합니다.",
    ["Travel to Krol'dok Stronghold and slay Zalfan Moonshadow."] = "크롤도크 보루로 이동하여 잘판 문섀도우를 처치하세요.",
    ["Travel to Lakeshire and deliver Helendis Riverhorn's Letter to Magistrate Solomon."] = "레이크셔로 이동하여 헬렌디스 리버혼의 편지를 집정관 솔로몬에게 전달하세요.",
    ["Travel to Light's Hope in Eastern Plaguelands and seek out Leonid Barthalomew the Revered. Show him the Keepsake of Remembrance and tell him all that you have discovered."] = "동부 역병지대에 있는 희망의 빛으로 이동하여 존경받는 리어니드 바돌로매를 찾으세요. 그에게 추억의 유품을 보여주고 당신이 발견한 모든 것을 그에게 말하십시오.",
    ["Travel to Marvon Rivetseeker's workshop in Ratchet."] = "톱니항에 있는 마본 리벳시커의 작업장으로 이동하세요.",
    ["Travel to Northdale, in the northeastern region of the Eastern Plaguelands, and recover the Symbol of Lost Honor. Return to Tirion Fordring upon completion of your objective."] = "동부 역병지대 북동쪽 지역인 노스데일로 여행하여 실추된 명예의 상징을 회수하세요. 목표를 완료하면 티리온 폴드링으로 돌아가세요.",
    ["Travel to Silithus and search for a Reliquary of Purity within the ruins of Southwind Village. If you are able to find it, return with it to Rabine Saturna in Nighthaven, Moonglade."] = "실리더스로 이동하여 마파람 마를 폐허에서 정화의 성물함을 검색하세요. 그것을 찾을 수 있다면 달숲 나이트헤이븐에 있는 라빈 사투르나에게 가져가세요.",
    ["Travel to Stormwind City and venture to the city gates. Speak with Squire Rowe so that he may let Marshal Windsor know that you have arrived."] = "스톰윈드로 이동하여 성문으로 모험을 떠나세요. 수습기사 로우와 대화하면 치안대장 윈저에게 당신이 도착했다는 사실을 알릴 수 있습니다.",
    ["Travel to Stormwind and deliver Solomon's Plea to Highlord Bolvar Fordragon. Bolvar resides in Stormwind Keep."] = "스톰윈드로 이동하여 대영주 볼바르 폴드라곤에게 솔로몬의 간청을 전달하세요. 볼바르는 스톰윈드 왕궁에 거주합니다.",
    ["Travel to Stratholme and find Archivist Galford of the Scarlet Crusade. Destroy him and burn down the Scarlet Archive."] = "스트라솔름으로 가서 붉은십자군의 기록관 갈포드를 찾으세요. 그를 파괴하고 붉은십자군 기록을 불태워 버리세요.",
    ["Travel to Stratholme and find Menethil's Gift. Place the Keepsake of Remembrance upon the unholy ground."] = "스트라솔름으로 가서 메네실의 선물을 찾으세요. 추억의 유품을 부정한 땅에 놓으십시오.",
    ["Travel to Stratholme and search the ziggurats. Find and return new Scourge Data to Betina Bigglezink."] = "스트라솔름으로 이동하여 지구라트를 수색하세요. 새로운 스컬지 자료를 찾아 베티나 비글징크에 반환합니다.",
    ["Travel to Stratholme and slay Ramstein the Gorger. Take his head as a souvenir for Nathanos."] = "스트라솔름으로 가서 먹보 람스타인을 처치하세요. 나타노스에게 기념품으로 그의 머리를 가져가세요.",
    ["Travel to Stratholme, in the north. Search the supply crates that litter the city and recover 5 Stratholme Holy Water. Return to Leonid Barthalomew the Revered when you have collected enough of the blessed fluid."] = "북쪽에 있는 스트라솔름으로 여행하세요. 도시를 뒤덮고 있는 보급품 상자를 수색하고 스트라솔름 성수 5개를 회수하세요. 축복받은 액체를 충분히 모은 후 존경받는 리어니드 바돌로매에게 돌아가세요.",
    ["Travel to Stratholme, in the northern part of the Plaguelands. It is in the Scarlet Bastion that you will find the painting 'Of Love and Family,' hidden behind another painting depicting the twin moons of our world. Return the painting to Tirion Fordring."] = "역병지대 북부에 있는 스트라솔름으로 여행하세요. 우리 세계의 쌍둥이 달을 묘사한 또 다른 그림 뒤에 숨겨져 있는 그림 '가족과 사랑'를 찾을 수 있는 곳은 십자군 광장입니다. 그림을 티리온 폴드링에게 돌려주세요.",
    ["Travel to The Sepulcher in Silverpine Forest and speak with Trevan Rol about the missing Earthen Ring travelers."] = "은빛소나무 숲의 공동묘지로 가서 트레반 롤과 실종된 대지 고리회 여행자들에 관해 대화하세요.",
    ["Travel to Winterspring and find Haleh. Give her Awbee's scale."] = "윈터스프링으로 가서 할레를 찾으세요. 그녀에게 아우비의 체중계를 주세요.",
    ["Travel to island of Caer Darrow, in the south-central region of the Plaguelands, and look for any clues as to the whereabouts of the painting."] = "역병지대 남중부 지역에 있는 카엘 다로우 섬으로 여행하여 그림의 행방에 대한 단서를 찾으십시오.",
    ["Travel to the Arathi Highlands, to the ruins of Stromgarde. Search Stromgarde for a Keepsake of Remembrance. If you find such an item, return with it to Magistrate Marduke."] = "아라시 고원, 스트롬가드 폐허로 여행하세요. 스트롬가드에서 추억의 유품을 검색하세요. 그런 아이템을 찾으면 집정관 마르듀크에게 가져가세요.",
    ["Travel to the Burning Steppes and find Grark Lorkrub. You recall Lexlort mentioning that he was last seen in a massive Blackrock fortress. When you find Grark Lorkrub, use the Thorium Shackles to bind him and then lead him back through Blackrock Mountain to the Searing Gorge. Lexlort will have his men waiting on the other side to take Grark into custody."] = "불타는 평원으로 이동하여 그랄크 로크럽을 찾으세요. 렉스로트가 자신이 거대한 검은바위 요새에서 마지막으로 목격되었다고 언급한 것을 기억하실 것입니다. 그랄크 로크럽을 찾으면 토륨 족쇄를 사용하여 그를 묶은 다음 검은바위 산을 통해 이글거리는 협곡으로 다시 데려가세요. 렉스로트는 그랄크를 구금하기 위해 그의 부하들을 반대편에서 기다리게 할 것입니다.",
    ["Travel to the Burning Steppes and give Bijou's Information to Marshal Maxwell."] = "불타는 평원으로 이동하여 비쥬의 정보를 치안대장 맥스웰에게 전달하세요.",
    ["Travel to the Dwarven District in Stormwind and find an engineer who can help with explosives."] = "스톰윈드의 드워프 지구로 이동하여 폭발물 작업을 도울 수 있는 엔지니어를 찾으세요.",
    ["Travel to the Undercroft - at the southernmost section of the Eastern Plaguelands - and recover Taelan's Hammer. Return to Tirion Fordring upon completion of your objective."] = "동부 역병지대의 최남단 구역인 지하 납골당으로 이동하여 탤런의 망치를 회수하세요. 목표를 완료하면 티리온 폴드링으로 돌아가세요.",
    ["Travel to the Warpwood Quarter of Dire Maul and slay the water elemental, Hydrospawn. Return to Lorekeeper Lydros in the Athenaeum with the Hydrospawn Essence."] = "혈투의 전장의 굽이나무 지구로 이동하여 물의 정령 히드로스폰을 처치하세요. 히드로스폰의 정수를 가지고 도서관에 있는 현자 리드로스로 돌아가세요.",
    ["Travel to the Wetlands and meet the Deathstalker Agent in the hills above the Dragonmaw camp."] = "저습지로 이동하여 용아귀 캠프 위 언덕에서 죽음의 추적자를 만나세요.",
    ["Travel to the Wyrmbog in Dustwallow Marsh and seek out Emberstrife's Den. Once inside, wear the Amulet of Draconic Subversion and speak with Emberstrife."] = "먼지진흙 습지대의 용의 둥지에서 엠버스트라이프의 굴을 찾으세요. 안으로 들어가 용족 파멸의 아뮬렛을 착용한 뒤 엠버스트라이프와 대화하세요.",
    ["Travel to the Wyrmbog in Dustwallow Marsh. Find the ancient drake Emberstrife and beat him until his will is broken, place the Unforged Seal of Ascension before him, then use the Orb of Draconic Energy on him and force the Flames of the Black Dragonflight upon the Unforged Seal of Ascension."] = "먼지진흙 습지대를 타고 웜보그로 여행하세요. 고대 비룡 엠버스트라이프를 찾아 그의 의지가 꺾일 때까지 그를 때리고, 그 앞에 벼려지지 않은 승천의 인장을 배치한 다음 그에게 용력의 보주를 사용하고 벼려지지 않은 승천의 인장에 검은용군단의 불꽃을 강제로 가합니다.",
    ["Travel to the northern borders of the Eastern Plaguelands and recover the Quel'Thalas Registry. The item is somewhere in the Quel'Lithien lodge. You must also slay 8 Rangers, 8 Pathstriders, and 8 Woodsmen."] = "동부 역병지대의 북쪽 경계로 이동하여 쿠엘탈라스 기록부를 회수하세요. 해당 아이템은 쿠엘리시엔 산장 어딘가에 있습니다. 또한 레인저 8명, 패스스트라이더 8명, 나무꾼 8명을 처치해야 합니다.",
    ["Travel to the quarry in Blackrock Mountain and slay Overmaster Pyron. Return to Thunderheart when you have completed this assignment."] = "검은바위 산에 있는 채석장으로 이동하여 멸망의 파이론을 처치하세요. 이 임무를 완료하면 썬더하트로 돌아가세요.",
    ["Treacherous Treads"] = "미덥지 못한 발보호대",
    ["Treads of the Protector Golem"] = "수호자 골렘의 발보호대",
    ["Treant guarding the Capital Gardens."] = "캐피털 가든을 지키고 있는 트렌트.",
    ["Treant's Bane"] = "나무정령 파멸의 도끼",
    ["Tree Bark Jacket"] = "나무껍질 재킷",
