    ["Tribute chest awarded by Mizzle the Crafty after King Gordok is defeated. The tribute improves when Gordok guards and Captain Kromcrush are spared. Equipment pool is based on Classic-derived Forever reference data; individual drops still need live verification."] = "왕 고르독가 패배한 후 약삭빠른 미즐가 수여하는 공물 상자입니다. 고르독 경비병과 대장 크롬크러쉬를 아끼면 공물이 향상됩니다. 장비 풀은 클래식에서 파생된 포에버 참조 데이터를 기반으로 합니다. 개별 방울은 여전히 ​​실시간 확인이 필요합니다.",
    ["Trindlehaven Staff"] = "고리하늘 지팡이",
