    ["Twisted Evils"] = "뒤틀린 악마",
    ["Twisted Totems only drop while this quest is in your log. Water: Mirefin murlocs, northeast coast of Dustwallow Marsh. Air: Maraudine centaurs, Desolace. Earth: Lost Ones, Swamp of Sorrows. Fire: Dustbelcher ogres and Stonevault troggs, Badlands."] = "이 퀘스트를 수행 중일 때만 뒤틀린 토템을 획득할 수 있습니다. 물: 먼지진흙 습지대 북동쪽 해안의 수렁지느러미 멀록. 바람: 잊혀진 땅의 마라우딘 켄타우로스. 대지: 슬픔의 늪의 잃어버린 드레나이. 불: 황야의 땅의 먼지목도리 오우거와 바위동굴 트로그.",
    ["Two green dragons encountered after Jammal'an the Prophet. Both must be defeated to complete the encounter."] = "예언자 잠말란 이후 마주한 두 마리의 그린 드래곤. 만남을 완료하려면 둘 다 패배해야 합니다.",
    ["Two green dragons guarding the temple. Both must be defeated to complete the encounter. Morphaz also drops items for the hunter, rogue, priest and mage class quests."] = "두 마리의 녹색 용이 사원을 지키고 있습니다. 만남을 완료하려면 둘 다 패배해야 합니다. 몰파즈는 또한 사냥꾼, 도적, 사제 및 마법사 클래스 퀘스트에 대한 아이템을 떨어뜨립니다.",
    ["Two raptors, fought together. Not elite."] = "랩터 두 마리가 함께 싸웠습니다. 엘리트는 아닙니다.",
