    ["Undead Sandfury boss. Drops the First Mosh'aru Tablet for The Prophecy of Mosh'aru."] = "모래망치일족 언데드 우두머리입니다. '모쉬아루의 예언'에 필요한 첫번째 모쉬아루 서판을 획득할 수 있습니다.",
    ["Underbelly"] = "마법의 뒤안길",
