    ["Undercroft"] = "지하 납골당",
    ["Underground Assault"] = "지하 공격",
    ["Underground Map"] = "지하 지도",
    ["Underwater west of the Vile Reef: swim to Sunken Hollow by the island with the water elementals; the cave has a large tablet beside it"] = "썩은내 산호초 서쪽 수중: 물의 정령과 함께 섬 옆 가라앉은 동굴까지 수영하세요. 동굴 옆에는 큰 태블릿이 있습니다",
    ["Undying Headdress"] = "불멸의 머리장식",
