    ["Unique"] = "고유",
    ["Unique-Equipped"] = "고유 장착",
    ["Unknown Reward"] = "알 수 없는 보상",
    ["Unlocked by handing in Bring Me His Head to Sergeant Riftan."] = "하사관 리프탄에게 머리를 가져오면 잠금 해제됩니다.",
    ["Unstable Crystalline Shoulderpads"] = "불안정한 수정 어깨보호대",
    ["Unstable Power Core"] = "불안정한 동력핵",
    ["Unstable Sentinel"] = "불안정한 파수꾼",
    ["Unyielding Maul"] = "단호의 마울",
    ["Up the mountain path to the camp"] = "캠프로 향하는 산길 위로",
    ["Up the path into the hills"] = "언덕으로 올라가는 길",
    ["Up the tower, talk to the guard next to Archmage Tervosh (he looks like you in the disguise) and relieve him; don't get close to Jaina or she dispels it. You stay stuck a while after it completes: use Exit Vehicle."] = "탑으로 올라가 대마법사 테르보쉬 옆의 경비병과 대화하여 교대하세요. 경비병은 변장한 플레이어와 같은 모습입니다. 제이나에게 가까이 가면 변장이 해제되니 주의하세요. 완료 후 움직일 수 없다면 탈것에서 내리기 버튼을 누르세요.",
    ["Upper Blackrock Spire Entrance"] = "검은바위 첨탑 상층 입구",
    ["Ursolan"] = "우르솔란",
    ["Use An Unsent Letter, looted from Edwin VanCleef in The Deadmines"] = "죽음의 폐광의 에드윈 밴클리프에서 약탈한 부치지 않은 편지를 사용하세요.",
    ["Use An Unsent Letter, looted from Edwin VanCleef."] = "에드윈 밴클리프에서 약탈한 부치지 않은 편지를 사용하세요.",
    ["Use Dawn's Gambit in the Viewing Room and defeat Vectus."] = "관찰실에서 여명의 계략을 사용하여 벡투스를 처치하세요.",
    ["Use Egan's Blaster on the ghostly and spectral citizens of Stratholme. When the restless souls break free from their ghostly shells, use the blaster again - freedom will be theirs! Free 15 Restless Souls and return to Egan."] = "스트라솔름의 유령과 유령 시민에게 에간의 제령포를 사용하세요. 불안한 영혼들이 유령의 껍질에서 풀려나면 블래스터를 다시 사용하세요. 자유가 그들의 것이 될 것입니다! 불안한 영혼 15명을 구출하고 에간에게 돌아가세요.",
    ["Use Jaron's Pick to find the four Highborne Relic Fragments. Bring them to Aurora Skycaller in Eastern Plaguelands."] = "야론의 곡괭이를 사용하여 4개의 명가의 유물 조각을 찾으세요. 동부 역병지대에 있는 아우로라 스카이콜러에게 가져가세요.",
    ["Use Matrix Punchograph 3005-A with the White Punch Card to get a Yellow Punch Card."] = "백색 천공 카드와 함께 매트릭스 펀치그래프 3005-A를 사용하여 황색 천공 카드를 얻으세요.",
    ["Use Matrix Punchograph 3005-B with the Yellow Punch Card to get a Blue Punch Card."] = "황색 천공 카드와 함께 매트릭스 펀치그래프 3005-B를 사용하여 청색 천공 카드를 얻으세요.",
    ["Use Matrix Punchograph 3005-C with the Blue Punch Card to get a Red Punch Card."] = "청색 천공 카드와 함께 매트릭스 펀치그래프 3005-C를 사용하여 적색 천공 카드를 얻으세요.",
    ["Use Matrix Punchograph 3005-D with the Red Punch Card to get the Prismatic Punch Card, then bring it to Master Mechanic Castpipe in Ironforge."] = "적색 천공 카드와 함께 매트릭스 펀치그래프 3005-D를 사용하여 오색 천공 카드를 얻은 다음 아이언포지에 있는 수석수리공 캐스트파이프에게 가져가세요.",
    ["Use the Banner of Provocation in the center of the Ring of Law as High Justice Grimstone sentences you, slay Theldren and his gladiators, and bring the Top Piece of Lord Valthalak's Amulet to Anthion Harmon in the Eastern Plaguelands."] = "대법관 그림스톤가 당신에게 선고를 내릴 때 법의 고리 중앙에 있는 도전의 깃발을 사용하고, 텔드렌과 그의 검투사들을 처치하고, 동부 역병지대에 있는 군주 발타라크의 아뮬렛 가운데 조각을 안시온 하몬으로 가져오세요.",
    ["Use the Blood of Innocents at the brazier on the Scholomance porch. Rewards the Spectral Essence."] = "스칼로맨스 현관의 화로에서 순결한 피를 사용하세요. 영혼의 정수를 보상합니다.",
    ["Use the Crate with Holes to summon a Snufflenose Gopher and the Command Stick to make it find 6 Blueleaf Tubers. Bring them, the Command Stick and the Crate back to Mebok Mizzyrix."] = "구멍 난 상자를 사용하여 땅다람쥐를 소환하고 커맨드 스틱을 사용하여 6개의 청엽수 줄기를 찾도록 합니다. 그들과 커맨드 스틱, 상자를 메보크 미지릭스로 가져가세요.",
    ["Use the Damp Note dropped by Blackfathom Tide Priestesses"] = "검은심연 여사제가 떨어뜨린 축축한 쪽지를 사용하세요.",
    ["Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth spirits you must fight. Defeating these spirits will summon forth Death Knight Darkreaver; defeat him. Bring Darkreaver's Head to Sagorne Creststrider in the Valley of Wisdom, Orgrimmar."] = "스칼로맨스에 있는 대납골당 지하 중심부에서 예언의 탐지기를 사용하세요. 그렇게 하면 당신이 싸워야 할 영혼들이 나올 것입니다. 이 영혼들을 물리치면 죽음의 기사 다크리버가 소환됩니다. 그를 물리쳐라. 지혜의 계곡, 오그리마에 있는 사고른 크레스트스트라이더에게 다크리버의 머리카락을 가져가세요.",
    ["Use the Divination Scryer in the heart of the Great Ossuary's basement in the Scholomance. Doing so will bring forth the spirits you must judge. Defeating these spirits will summon forth Death Knight Darkreaver. Defeat him and reclaim the lost soul of the fallen charger. Give the Charger's Redeemed Soul and the Blessed Enchanted Barding to Darkreaver's Fallen Charger."] = "스칼로맨스에 있는 대납골당 지하 중심부에서 예언의 탐지기를 사용하세요. 그렇게 하면 당신이 심판해야 할 영들이 나올 것입니다. 이 영혼들을 물리치면 죽음의 기사 다크리버가 소환됩니다. 그를 물리치고 쓰러진 군마의 잃어버린 영혼을 되찾으세요. 구원된 군마의 영혼과 축복받은 마법 마갑을 다크리버 군마의 영혼에게 전달하세요.",
    ["Use the Eggscilloscope Prototype on an egg in the Rookery."] = "번식지의 알에 알껍질급속냉각기 견본을 사용하세요.",
    ["Use the Empty Leaden Collection Phial on Irradiated Invaders or Irradiated Pillagers, then take the full phial back to Ozzie Togglevolt."] = "조사된 침입자 또는 조사된 약탈자에게 빈 가연채집병을 사용한 다음 전체 약병을 오지 토글볼트에게 가져가세요.",
    ["Use the Empty Leaden Collection Phial on a living Irradiated Invader or Irradiated Pillager, then return the full phial to Ozzie Togglevolt."] = "살아있는 오염된 침략꾼 또는 오염된 약탈자에 빈 가연채집병을 사용한 다음 전체 약병을 오지 토글볼트에게 반환합니다.",
    ["Use the Exorcism Censer to drive out the spirits that torment Terrordale. When you have slain 25 Terrordale Spirits, return to Lord Grayson Shadowbreaker in the Cathedral District of Stormwind."] = "퇴마 향로를 사용하여 공포의 골짜기를 괴롭히는 영혼을 몰아내세요. 25명의 테러데일 영혼을 처치한 후 스톰윈드 대성당 구역에 있는 그레이슨 섀도브레이커 경으로 돌아가세요.",
    ["Use the Extra-Destructive Explosives quest-start item."] = "강력 파괴 폭발물 퀘스트 시작 아이템을 사용하세요.",
    ["Use the Moonsilver Blade to destroy Old-Fire Eye in Silverpine Forest."] = "달빛은 칼날을 사용하여 은빛소나무 숲에서 늙은 불눈을 파괴하세요.",
    ["Use the SI:7 Disguise Kit to eavesdrop on Jaina and her inner circle at the Theramore Mage Tower."] = "SI:7 변장 도구를 사용하여 테라모어 마법사 탑에 있는 제이나와 그녀의 내부 서클을 엿듣습니다.",
    ["Use the Sacred Mallet at the altar on the very top of Jintha'Alor: it turns into the Mallet of Zul'Farrak."] = "진타알로 꼭대기에 있는 제단에서 신성한 나무망치를 사용하세요. 줄파락의 나무망치로 변합니다.",
    ["Use the Soulbound Keepsake on Ras Frostwhisper to make him human, then kill him and bring back his human head."] = "라스 프로스트위스퍼에 영혼이 씌인 유품을 사용하여 그를 인간으로 만든 다음 그를 죽이고 그의 인간 머리를 가져오십시오.",
    ["Use the Twisted Totems to put an end to the quilboar ritual."] = "뒤틀린 토템을 사용하여 가시멧돼지 의식을 끝내십시오.",
    ["Use the Well Water Sample Kit at the Jansen Stead and Molsen Farm wells."] = "얀센 농장 및 몰센 농장 우물에서 우물물 표본 채취 도구를 사용하세요.",
    ["Use the hide and charcoal to make a rubbing of the Third Troll Legend tablet."] = "가죽과 숯을 사용하여 세 번째 트롤 전설 석판을 문지릅니다.",
    ["Use the hide and charcoal to make rubbings of the four Tablets of I'lalai in the Drowned City."] = "가죽과 숯을 사용하여 익사한 도시에 있는 이랄라이의 서판 네 개에 대한 탁본을 만드세요.",
    ["Use the note provided by Mason Connery to find his hidden treasure."] = "메이슨 코너리가 제공한 메모를 사용하여 숨겨진 보물을 찾으세요.",
    ["Use the supplied cage on a Bloodaxe Worg Pup in the worg area."] = "워그 영역의 도끼부대 새끼 검은늑대에 제공된 케이지를 사용합니다.",
    ["Using Jordan's Weapon Notes, find some Whitestone Oak Lumber, Bailor's Refined Ore Shipment, Jordan's Smithing Hammer, and a Kor Gem, and return them to Jordan Stilwell in Ironforge."] = "조던의 쪽지를 사용하여 일부 흰돌참나무 재목, 베일러의 정제 광석 선적, 조던의 대장장이 망치 및 코르석을 찾아 아이언포지에 있는 조던 스틸웰에게 반환합니다.",
    ["Using the module on the eggs in the Rookery can hatch whelps."] = "부화장의 알에 모듈을 사용하면 새끼용을 부화시킬 수 있습니다.",
    ["Uthel'nay"] = "우텔나이",
