    ["Uthel'nay, 오그리마"] = "우델나이, 오그리마",
    ["Vaelan (Scarshield Infiltrator), Lower Blackrock Spire"] = "바에란(방패부대 첩보원), 검은바위 첨탑 하층",
    ["Vaelan, Lower Blackrock Spire"] = "벨란, 검은바위 첨탑 하층",
