    ["Varrox"] = "바로스",
    ["Varrox Bleakhoof"] = "바록스 블리크후프",
    ["Varrox Bleakhoof, the last boss, has the head. Needs Timbermaw Hold reputation Neutral or better. The required level isn't confirmed yet."] = "바록스 블리크후프가 머리를 가지고 있습니다. 나무구렁 평판 중립 이상을 유지해야 합니다. 아직 요구되는 레벨이 확정되지 않았습니다.",
    ["Veilpiercer Girdle"] = "장막관통 요대",
    ["Vendetta"] = "복수의 단검",
    ["Vengeance of the Highborne"] = "명가의 복수",
    ["Venom Bottle"] = "독약병",
    ["Venom Bottles"] = "독병",
    ["Venom Bottles — The Hinterlands"] = "독병 — 동부 내륙지",
    ["Venom Fern Extract"] = "독고사리 즙",
    ["Venomridge"] = "맹독등",
    ["Venomspitter"] = "불그물 독송곳니",
    ["Venomstrike"] = "맹독의 쐐기활",
    ["Venomvessel Ring"] = "독혈관 링",
    ["Venture to Blackrock Depths and destroy the vile aggressors! Warlord Goretooth wants you to kill 10 Anvilrage Medics, 10 Anvilrage Soldiers and 10 Anvilrage Officers. Return to him once your task is complete."] = "검은바위 나락으로 모험을 떠나 사악한 공격자를 파괴하세요! 장군 고어투스는 10명의 앤빌라지 의료진, 10명의 앤빌라지 병사, 10명의 앤빌라지 장교를 처치해 달라고 부탁했습니다. 임무가 완료되면 그에게 돌아오십시오.",
    ["Venture to Blackrock Depths and destroy the vile aggressors! Warlord Goretooth wants you to kill 15 Anvilrage Guardsmen, 10 Anvilrage Wardens and 5 Anvilrage Footmen. Return to him once your task is complete."] = "검은바위 나락으로 모험을 떠나 사악한 공격자를 파괴하세요! 장군 고어투스는 성난모루 경비병 15명, 성난모루 감시자 10명, 성난모루 보병 5명을 처치해 달라고 부탁했습니다. 임무가 완료되면 그에게 돌아오십시오.",
    ["Venture to Maraudon and recover a Vial of Earth Song Water, then use it to put out Woodwyrd's flame at the Forlorn Gardens."] = "마라우돈으로 모험을 떠나 대지의 노래 물이 담긴 약병을 회수한 다음 이를 사용하여 외로운 정원에서 우드위어드의 불꽃을 끄세요.",
    ["Venture to Razorfen Downs and acquire Virulent Blood of Agamaggan, then return it to Kog'thug the Brave at Bristleback Retreat."] = "가시덩굴 구릉으로 가서 악성 아감마간의 핏덩이를 획득한 다음 뾰족털 골짜기에 있는 용감한 코그투그에게 가져가세요.",
    ["Venture to Stratholme and destroy Baron Rivendare. Take his head and return to Duke Nicholas Zverenhoff."] = "스트라솔름으로 가서 남작 리븐데어를 파괴하세요. 그의 머리를 잡고 공작 니콜라스 즈바른호프로 돌아갑니다.",
    ["Venture to the Burning Steppes and recover 10 Fractured Elemental Shards for Hierophant Theodora Mulvadania. You recall Theodora mentioning the golems and elementals of that region as being a source for these shards."] = "불타는 평원으로 모험을 떠나 제사장 테오도라 뮬바다니아를 위한 부서진 원소 파편 10개를 복구하세요. 테오도라가 해당 지역의 골렘과 정령을 이러한 파편의 출처로 언급한 것을 기억합니다.",
    ["Venture to the Molten Core entry portal in Blackrock Depths and recover a Core Fragment. Return to Lothos Riftwaker in Blackrock Mountain when you have recovered the Core Fragment."] = "검은바위 나락의 화산핵 진입 포탈로 가서 핵 조각을 복구하세요. 핵 조각을 복구한 후 검은바위 산의 로소스 리프트웨이커로 돌아갑니다.",
    ["Venture to the Ruins of Thaurissan in the Burning Steppes and recover information from the Thaurissan Relics. Return to Royal Historian Archesonus when you have recovered the information."] = "불타는 평원에 있는 타우릿산 폐허로 모험을 떠나 타우릿산 유물에서 정보를 복구하세요. 정보를 복구한 후 왕실사학자 아케소누스로 돌아가세요.",
    ["Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Alexi Barov when you have completed this task."] = "스칼로맨스로 모험을 떠나 바로브 가문의 재산을 되찾으세요. 이 재산은 네 가지 행위로 구성됩니다: 카엘 다로우 증서; 브릴 증서; 타렌 밀농장 증서; 그리고 사우스쇼어 증서. 이 작업을 완료하면 알렉시 바로브로 돌아가세요.",
    ["Venture to the Scholomance and recover the Barov family fortune. Four deeds make up this fortune: The Deed to Caer Darrow; The Deed to Brill; The Deed to Tarren Mill; and The Deed to Southshore. Return to Weldon Barov when you have completed this task."] = "스칼로맨스로 모험을 떠나 바로브 가문의 재산을 되찾으세요. 이 재산은 네 가지 행위로 구성됩니다: 카엘 다로우 증서; 브릴 증서; 타렌 밀농장 증서; 그리고 사우스쇼어 증서. 이 작업을 완료하면 웰던 바로브로 돌아가세요.",
