    ["Wait for Furen Longbeard to finish your armor."] = "푸렌 롱비어드가 갑옷을 완성할 때까지 기다리세요.",
    ["Wait for Jordan Stilwell to finish forging a weapon for you."] = "조던 스틸웰가 무기 제작을 마칠 때까지 기다리세요.",
    ["Wait for Scooty to calibrate the Goblin Transponder."] = "스쿠티가 고블린 응답장치를 보정할 때까지 기다립니다.",
    ["Wait for Thun'grim Firegaze to finish your armor."] = "툰그림 파이어게이즈가 갑옷을 완성할 때까지 기다리세요.",
