    ["War Handler's Gaze"] = "전쟁 조련사의 시선",
    ["War on the Shadowsworn"] = "어둠의혈맹과의 전쟁",
    ["Warblade of Caer Darrow"] = "카엘 다로우의 전투검",
    ["Warbringer Constructs"] = "전쟁인도자 피조물",
    ["Warden Thelwater"] = "교도소장 델워터",
    ["Warden Thelwater — The Stockade"] = "교도소장 델워터 — 스톰윈드 지하감옥",
    ["Warden Thelwater, outside The Stockade, Stormwind"] = "교도소장 델워터, 외부 스톰윈드 지하감옥, 스톰윈드",
    ["Warden Thelwater, outside The Stockade, 스톰윈드"] = "교도소장 델워터, 외부 스톰윈드 지하감옥, 스톰윈드",
    ["Warlock class book. Click the book to start the quest."] = "워록 클래스 북. 책을 클릭하면 퀘스트가 시작됩니다.",
    ["Warlock class quest. Needs 2 amber, 2 blue and 2 green Voodoo Feathers from the six troll guardians: Gasher, Mijan, Zolo, Hukku, Zul'Lor and Loro."] = "흑마법사 클래스 퀘스트입니다. 여섯 명의 트롤 수호자 게이셔, 마이잔, 졸로, 후쿠, 줄로 및 로로의 호박색 2개, 파란색 2개, 녹색 부두 깃털 2개가 필요합니다.",
    ["Warlock class quest. The fragments come from Shadowfang Keep and Blackfathom Deeps."] = "워록 클래스 퀘스트. 조각은 그림자송곳니 성채 및 검은심연 나락에서 나옵니다.",
    ["Warlock dreadsteed quest. After Immol'thar dies, run the ritual in his prison with J'eevee's Jar, the Black Lodestone and the Xorothian Glyphs. Bring Soul Shards."] = "흑마법사 공포마 퀘스트. 이몰타르가 죽은 후 지비의 단지, 검은 자철광 및 소로시안 상형문자를 사용하여 그의 감옥에서 의식을 실행하십시오. 영혼의 조각을 가져오세요.",
    ["Warlock dreadsteed quest. Release the Imp in a Jar at the alchemy lab in Ras Frostwhisper's room and wait for the parchment."] = "흑마법사 공포마 퀘스트. 라스 프로스트위스퍼의 방에 있는 연금술 연구실에 단지 안에 든 임프를 풀어주고 양피지를 기다리세요.",
    ["Warlord Goretooth"] = "장군 고어투스",
    ["Warlord Goretooth — Badlands"] = "장군 고어투스 — 황야의 땅",
    ["Warlord Goretooth — 황야의 땅"] = "장군 고어투스 — 황야의 땅",
    ["Warlord Goretooth, Badlands"] = "장군 고어투스, 황야의 땅",
    ["Warlord Goretooth, Kargath, Badlands"] = "장군 고어투스, 카르가스, 황야의 땅",
    ["Warlord Goretooth, Kargath, 황야의 땅"] = "장군 고어투스, 카르가스, 황야의 땅",
