    ["Warlord's Command"] = "장군의 명령",
    ["Warmaster Legguards"] = "대족장의 다리갑옷",
    ["Warning: Accept after completing In Search of Thaelrid, or you will lose that quest."] = "경고: 타엘리드 찾기를 완료한 후 수락하지 않으면 해당 퀘스트를 잃게 됩니다.",
    ["Warning: if not completed before accepting Blackfathom Villainy, this quest becomes unavailable."] = "경고: 검은심연의 음모를 수락하기 전에 완료하지 않으면 이 퀘스트를 사용할 수 없습니다.",
    ["Warosh, Lower Blackrock Spire"] = "와로쉬, 검은바위 첨탑 하층",
    ["Warpwood Binding"] = "굽이나무 허리띠",
    ["Warpwood Quarter"] = "굽이나무 지구",
    ["Warrior Kinship"] = "전사의 일족",
    ["Warrior class book. Click the book to start the quest."] = "전사 클래스 북. 책을 클릭하면 퀘스트가 시작됩니다.",
    ["Warrior class quest for both factions. Needs 2 amber, 2 blue and 2 green Voodoo Feathers from the six troll guardians: Gasher, Mijan, Zolo, Hukku, Zul'Lor and Loro.\n\nOptional introductory quest:"] = "두 세력 모두를 위한 전사 클래스 퀘스트입니다. 여섯 명의 트롤 수호자 게이셔, 마이잔, 졸로, 후쿠, 줄로 및 로로의 호박색 2개, 파란색 2개, 녹색 부두 깃털 2개가 필요합니다.\n\n선택적인 소개 퀘스트:",
    ["Warrior class quest from level 20. In this dungeon: Brutal Armor needs the Vial of Phlogiston from Roogug, the first boss. After Brutal Armor, Ula'elek, Orm Stonehoof (Thunder Bluff) and Velora Nitely each make one more piece:"] = "레벨 20부터 전사 클래스 퀘스트. 이 던전에서: 투사의 방어구는 첫 번째 보스인 루구그에게서 연소 약병가 필요합니다. 투사의 방어구 이후, 울라엘레크, 오름 스톤후프(썬더 블러프) 및 벨로라 나이틀리는 각각 하나의 조각을 더 만듭니다.",
    ["Warrior class quest from level 20. In this dungeon: Fire Hardened Mail needs the Vial of Phlogiston from Roogug, the first boss. After Fire Hardened Mail, Grimand Elmore (Stormwind), Klockmort Spannerspan (Ironforge) and Mathiel (Darnassus) each make one more piece:"] = "레벨 20부터 전사 클래스 퀘스트. 이 던전에서: 불에 달궈 만든 갑옷는 첫 번째 보스인 루구그에게서 연소 약병가 필요합니다. 불에 달궈 만든 갑옷, 그리만트 엘모어(스톰윈드), 클락몰트 스패너스판(아이언포지) 및 메시엘(다르나서스)이 각각 하나의 조각을 더 만든 후:",
    ["Warrior quests Fire Hardened Mail and Brutal Armor"] = "전사 퀘스트 불에 달궈 만든 갑옷 및 투사의 방어구",
    ["Warrior trainers"] = "워리어 트레이너",
    ["Warrior's Embrace"] = "전사의 은총",
    ["Warriors and Paladins. Lydros then gives The Forging of Quel'Serrar, which is finished in Onyxia's Lair."] = "전사·성기사 전용입니다. 이후 리드로스에게서 '쿠엘세라 검 만들기' 퀘스트를 받아 오닉시아의 둥지에서 완료합니다.",
