    ["Yorba Screwspigot, Steamwheedle Port, 타나리스"] = "요르바 스크류스피곳, 스팀휘들 항구, 타나리스",
    ["Yorba Screwspigot: Steamwheedle Port, Tanaris"] = "요르바 스크류스피곳: 스팀휘들 항구, 타나리스",
    ["Yorba Screwspigot: Steamwheedle Port, 타나리스"] = "요르바 스크류스피곳: 스팀휘들 항구, 타나리스",
    ["Yorus Barleybrew, Lakeshire, Redridge Mountains"] = "요루스 발리브루, 레이크셔, 붉은마루 산맥",
    ["Yorus Barleybrew, 호숫가 마을, 붉은마루 산맥"] = "요루스 발리브루, 레이크셔, 붉은마루 산맥",
    ["You have to be dead to talk to this guy. He's in Blackrock Mountain, in a room while walking the chain down to BRD."] = "이 사람과 대화하려면 죽어야 합니다. 그는 검은바위 산에 있고 방에 있는 동안 체인을 타고 검은바위 나락으로 내려갔습니다.",
    ["You may have just stumbled on to something that Marshal Windsor would be interested in seeing. There may be hope, after all."] = "방금 치안대장 윈저가 관심을 가질만한 내용을 우연히 발견했을 수도 있습니다. 결국 희망이 있을 수도 있습니다.",
    ["You must destroy the guardians surrounding the 5 Pylons that power the Prison of Immol'thar. Once the Pylons have powered down, the force field surrounding Immol'thar will have dissipated. Enter the Prison of Immol'thar and eradicate the foul demon that stands at its heart. Finally, confront Prince Tortheldrin in Athenaeum. Return to the Shen'dralar Ancient in the courtyard should you complete this quest."] = "이몰타르 감옥에 전력을 공급하는 5개의 수정탑을 둘러싸고 있는 수호자들을 파괴해야 합니다. 수정탑의 전원이 꺼지면 이몰타르를 둘러싼 역장이 사라질 것입니다. 이몰타르 감옥에 들어가서 그 중심에 서 있는 사악한 악마를 근절하세요. 마지막으로 도서관에서 왕자 토르텔드린과 대결하세요. 이 퀘스트를 완료하면 안뜰에 있는 셴드랄라 고대인으로 돌아가세요.",
    ["You must find the blue dragonflight drake champion, Scryer, and slay him. Pry his skull from his corpse and return it to Emberstrife. You know that Scryer can be found in Winterspring."] = "푸른용군단의 용사인 점술가를 찾아 처치해야 합니다. 그의 시체에서 두개골을 꺼내어 엠버스트라이프에게 가져가세요. 점술가를 여명의 설원에서 찾을 수 있다는 걸 아시죠?",
    ["You must retrieve the Blood of the Black Dragon Champion from General Drakkisath. Drakkisath can be found in his throne room behind the Halls of Ascension in Blackrock Spire."] = "사령관 드라키사스에서 검은용 용사의 피를 검색해야 합니다. 드라키사스는 검은바위 첨탑 승천의 전당 뒤에 있는 그의 알현실에서 찾을 수 있습니다.",
    ["You must search the world for a being capable of restoring the power to the Fragment of the Dragon's Eye. The only information you possess about such a being is that they exist."] = "용의눈 조각의 힘을 회복할 수 있는 존재를 세계 곳곳에서 찾아야 합니다. 그러한 존재에 대해 당신이 갖고 있는 유일한 정보는 그들이 존재한다는 것뿐입니다.",
    ["You need a remote detonator for the planned explosion."] = "폭발을 계획하려면 원격 기폭 장치가 필요합니다.",
    ["You receive a Blue Punch Card"] = "청색 천공 카드를 받았습니다.",
    ["You receive a Red Punch Card"] = "적색 천공 카드를 받았습니다.",
    ["You receive a Yellow Punch Card"] = "황색 천공 카드를 받았습니다.",
    ["Young Crocolisk Skins"] = "새끼 악어 가죽",
    ["Your class trainer"] = "당신의 클래스 트레이너",
    ["Your warrior trainer (Sorek in Orgrimmar) sends you to Ruga first. Timed: 30 minutes. The antennae come from the silithids at the Field of Giants, south of Camp Taurajo."] = "당신의 전사 트레이너(오그리마의 소렉)가 먼저 당신을 루가로 보냅니다. 시간 제한: 30분. 더듬이는 타우라조 캠프 남쪽에 있는 거인의 벌판에 있는 실리시드에게서 나옵니다.",
    ["Your warrior trainer (Wu Shen in Stormwind, or the trainers in Ironforge and Darnassus) sends you to Yorus Barleybrew in Lakeshire first. The run is timed."] = "당신의 전사 트레이너(스톰윈드의 우 셴 또는 아이언포지 및 다르나서스의 트레이너)가 먼저 당신을 레이크샤이어의 요루스 발리브루로 보냅니다. 실행 시간이 정해져 있습니다.",
