    ["|cff1eff00Equip: Increases damage and healing done by magical spells and effects by up to 14.|r"] = "|cff1eff00착용 효과: 마법 주문 및 효과로 인한 피해와 치유량이 최대 14만큼 증가합니다.|r",
    ["|cff1eff00Equip: Increases damage and healing done by magical spells and effects by up to 15.|r"] = "|cff1eff00착용 효과: 마법 주문 및 효과에 의한 피해와 치유량이 최대 15만큼 증가합니다.|r",
    ["|cff1eff00Equip: Increases damage and healing done by magical spells and effects by up to 16.|r"] = "|cff1eff00착용 효과: 마법 주문 및 효과에 의한 피해와 치유량이 최대 16만큼 증가합니다.|r",
    ["|cff1eff00Equip: Increases damage and healing done by magical spells and effects by up to 18.|r"] = "|cff1eff00착용 효과: 마법 주문 및 효과에 의한 피해와 치유량이 최대 18만큼 증가합니다.|r",
