    ["|cff1eff00Equip: Increases damage and healing done by magical spells and effects by up to 54.|r"] = "|cff1eff00착용 효과: 마법 주문 및 효과로 인한 피해와 치유량이 최대 54만큼 증가합니다.|r",
    ["|cff1eff00Equip: Increases damage and healing done by magical spells and effects by up to 68.|r"] = "|cff1eff00착용 효과: 마법 주문 및 효과에 의한 피해와 치유량이 최대 68만큼 증가합니다.|r",
    ["|cff1eff00Equip: Increases damage and healing done by magical spells and effects by up to 9.|r"] = "|cff1eff00착용 효과: 마법 주문 및 효과로 인한 피해와 치유량이 최대 9만큼 증가합니다.|r",
    ["|cff1eff00Equip: Increases damage done by Arcane spells and effects by up to 7.|r"] = "|cff1eff00착용 효과: 비전 주문 및 효과의 공격력을 최대 7까지 증가시킵니다.|r",
    ["|cff1eff00Equip: Increases damage done by Holy spells and effects by up to 18.|r"] = "|cff1eff00착용 효과: 신성 주문 및 효과의 공격력을 최대 18까지 증가시킵니다.|r",
    ["|cff1eff00Equip: Increases damage done by Nature spells and effects by up to 7.|r"] = "|cff1eff00착용 효과: 자연 주문 및 효과의 공격력을 최대 7까지 증가시킵니다.|r",
