    ["|cff1eff00Equip: Increases damage done to Beasts by magical spells and effects by up to 26.|r"] = "|cff1eff00착용 효과: 마법 주문 및 효과로 야수에게 주는 피해가 최대 26만큼 증가합니다.|r",
