    ["|cff1eff00Equip: Increases healing done by up to 33 and damage done by up to 11 for all magical spells and effects.|r"] = "|cff1eff00착용 효과: 모든 마법 주문 및 효과에 대해 치유량이 최대 33만큼 증가하고 공격력이 최대 11만큼 증가합니다.|r",
