FDJ.KoreanFullTranslations = KO

local baseFreeText = FDJ.LocalizeFreeText
local function Translate(value)
    if type(value) ~= "string" or value == "" then return value end
    if FDJ.GetLanguage() ~= "koKR" then return value end
    if KO[value] then return KO[value] end
    local resolved = baseFreeText and baseFreeText(value) or value
    if KO[resolved] then return KO[resolved] end
    -- 여러 문장을 이어 붙인 지도/목표 안내는 줄 단위로 조회합니다.
    -- 완전한 번역이 없는 새 문장을 임의의 단어 치환으로 변형하지 않습니다.
    if resolved:find("\n", 1, true) then
        resolved = resolved:gsub("([^\n]+)", function(line)
            return KO[line] or (baseFreeText and baseFreeText(line)) or line
        end)
    end
    -- WoW 색상 제어 코드는 원형을 유지하고 그 안의 표시 문구만 조회합니다.
    resolved = resolved:gsub("(|c%x%x%x%x%x%x%x%x)(.-)(|r)", function(color, text, reset)
        return color .. (KO[text] or text) .. reset
    end)
    return resolved
end
FDJ.LocalizeFreeText = Translate

-- 기존 필드별 한국어 테이블이 먼저 반환하는 문자열도 새 보완본을 통과시킵니다.
-- 함수 인수와 반환 타입을 유지하여 언어 변경·툴팁·지도 호출을 그대로 지원합니다.
for _, key in ipairs({"LocalizeDungeonName", "LocalizeDungeonField", "LocalizeQuestField",
    "LocalizeBossName", "LocalizeItemSlot"}) do
    local original = FDJ[key]
    if type(original) == "function" then
        FDJ[key] = function(...)
            -- 이름 필드의 기존 한국어 표기가 다른 경우에도 용어집의 표기를 우선합니다.
            if FDJ.GetLanguage() == "koKR" and (key == "LocalizeDungeonName" or key == "LocalizeBossName") then
                local name = ...
                if KO[name] then return KO[name] end
            end
            return Translate(original(...))
        end
    end
end
